    mdb               = {points={  8,  16,  24,  32,  40}, pct={ 10,  12,  14,  16,  18}, stat='magic def. bonus', gift=true , label='Magic Defense Bonus'},
    mev_bonus         = {points={  8,  16,  24}, pct={  0,   0,   0}, stat='magic evasion', gift=true , label='Magic Evasion Bonus'},
    max_hp_boost      = {points={  8,  16,  24,  32,  40,  48}, pct={ 30,  60, 120, 180, 240, 280}, stat='max hp', gift=true , label='Max HP Boost'},
    max_mp_boost      = {points={  8,  16,  24,  32}, pct={ 10,  20,  40,  60}, stat='max mp', gift=true , label='Max MP Boost'},
    plantoid_killer   = {points={  8}, pct={  0}, stat='plantoid killer', gift=true , label='Plantoid Killer'},
    rapid_shot        = {points={  8}, pct={  0}, stat='rapid shot', gift=true , label='Rapid Shot'},
    resist_gravity    = {points={  8,  16,  24}, pct={  0,   0,   0}, stat='resist gravity', gift=true , label='Resist Gravity'},
    resist_silence    = {points={  8}, pct={  0}, stat='resist silence', gift=true , label='Resist Silence'},
    resist_sleep      = {points={  8,  16,  24,  32}, pct={  0,   0,   0,   0}, stat='resist sleep', gift=true , label='Resist Sleep'},
    resist_slow       = {points={  8}, pct={  0}, stat='resist slow', gift=true , label='Resist Slow'},
    sc_bonus          = {points={  8,  16,  24,  32,  40}, pct={  8,  12,  16,  20,  23}, stat='skillchain bonus', gift=true , label='Skillchain Bonus'},
    store_tp          = {points={  8,  16,  24,  32,  40}, pct={ 10,  15,  20,  25,  30}, stat='store tp', gift=true , label='Store TP'},
    tenacity          = {points={  8,  16,  24}, pct={  5,   7,   9}, stat='tenacity', gift=true , label='Tenacity'},
    undead_killer     = {points={  8}, pct={  0}, stat='undead killer', gift=true , label='Undead Killer'},
    zanshin           = {points={  8,  16,  24}, pct={ 15,  25,  35}, stat='zanshin', gift=true , label='Zanshin'},
}

-- Subjob trait-point contributions, mirrored from the bluGuide addon's
-- res/traits.lua `subs` tables (the reference implementation that matches
-- /checkparam). A subjob that grants the SAME trait contributes POINTS to
-- that trait's pool — it does NOT add a separate flat value, and it does
-- NOT stack additively with the BLU set spells. The game takes the
-- effective points as max(spell_points(+gift), sub_points), then a single
-- tier lookup. So e.g. /DNC gives Accuracy Bonus 8 points (= tier I = +10
-- acc on its own); set enough BLU acc spells to exceed 8 points and the
-- BLU pool wins instead — never both summed. Keyed by the trait-table key
-- used in OW_BLU_TRAIT_TABLES above. Subjobs not listed for a trait grant
-- 0 points for it.
-- Subjob Evasion Bonus tier ladder, keyed by the subjob that grants it.
-- Values are the full BG-wiki "Evasion Bonus" Level-Obtained table, which
-- is the authoritative source — it supersedes the older capped tables in
-- both the vendored GearInfo and the (pre-Master-Level) bluGuide addon,
-- which both stopped at tier II (+22) because they assumed a subjob caps
-- at level 49. With Master Levels the subjob cap is now higher (e.g. 55+),
-- so a /THF sub at 55 crosses the level-50 breakpoint into Evasion Bonus
-- III (+35) — which neither legacy table accounted for. We read the
-- game-reported sub_job_level (already reflecting the ML-raised cap) and
-- walk this ladder. Both OmniWatch's max-not-sum subtraction AND the
-- vendored GearInfo base eva use these same numbers so they can't drift.
--   THF: 10->10, 30->22, 50->35, 70->48, 76->60, 88->72
--   DNC: 15->10, 45->22, 75->35, 86->48
--   PUP: 25->10, 40->22, 60->35, 76->48   (BG-wiki; note tier I is 25, not 20)
local OW_BLU_EVA_SUB_LADDER = {
    THF = { {88,72}, {76,60}, {70,48}, {50,35}, {30,22}, {10,10} },
    DNC = { {86,48}, {75,35}, {45,22}, {15,10} },
    PUP = { {76,48}, {60,35}, {40,22}, {25,10} },
}

-- Resolve the subjob Evasion Bonus value for a given subjob + level by
-- walking the ladder high→low and returning the first tier the level
-- meets. Returns 0 if the job grants no Evasion Bonus or the level is
-- below tier I.
local function ow_sub_eva_bonus(sub_job, sub_level)
    if not sub_job then return 0 end
    local ladder = OW_BLU_EVA_SUB_LADDER[sub_job:upper()]
    if not ladder then return 0 end
    for _, pair in ipairs(ladder) do
        if (sub_level or 0) >= pair[1] then return pair[2] end
    end
    return 0
end

local OW_BLU_TRAIT_SUBS = {
    acc_bonus     = { DNC = 8,  DRG = 8,  RNG = 16 },
    attack_bonus  = { WAR = 8,  DRG = 8,  DRK = 16 },
    auto_refresh  = { PLD = 8,  SMN = 8 },
    auto_regen    = { WHM = 8,  RUN = 8 },
    clear_mind    = { SMN = 24, BLM = 24, SCH = 16, GEO = 16, RDM = 8 },
    conserve_mp   = { SCH = 8,  BLM = 16, GEO = 24 },
    counter       = { MNK = 8 },
    defense_bonus = { WAR = 8,  PLD = 16 },
    -- NOTE (2026-06-11): these two lines were previously identical
    -- (copy-paste error), wrongly granting /WAR a Triple Attack tier
    -- and /THF a Double Attack tier in both the live trait engine and
    -- the BLU Spellsets editor preview. WAR sub grants Double Attack
    -- only; THF sub grants Triple Attack only (at master-level-raised
    -- sub levels; value is bluGuide's at-cap encoding).
    da            = { WAR = 8 },
    triple_attack = { THF = 16 },
    dw            = { NIN = 24, DNC = 16 },
    evasion_bonus = { THF = 16, DNC = 16, PUP = 8 },
    fast_cast     = { RDM = 24 },
    gilfinder     = { THF = 16 },
    mab           = { BLM = 16, RDM = 16 },
    mbb           = { BLM = 8 },
    mdb           = { RUN = 16, WHM = 16, RDM = 16 },
    max_hp_boost  = { RUN = 16, MNK = 16, NIN = 16, WAR = 8, PLD = 8 },
    max_mp_boost  = { SMN = 16, GEO = 8,  SCH = 8 },
    rapid_shot    = { RNG = 8,  COR = 8 },
    resist_silence= { BRD = 8,  SCH = 8 },
    resist_gravity= { THF = 16 },
    resist_sleep  = { PLD = 16 },
    resist_slow   = { PUP = 16, BST = 16, SMN = 16, DNC = 8 },
    sc_bonus      = { DNC = 8 },
    store_tp      = { SAM = 16 },
    undead_killer = { PLD = 8 },
    zanshin       = { SAM = 16 },
    inquartata    = { RUN = 24 },
    tenacity      = { RUN = 24 },
}

-- Cache the equipped-set summary so the per-frame stat compute doesn't
-- redo the spell-name → table lookup. Invalidated whenever the
-- equipped spells signal changes (we re-poll on each get_player tick
-- since equipping a new spell isn't a separate windower event).
local _ow_blu_cache_signature = nil
local _ow_blu_cache           = nil   -- {dw, stats, debug={}}

-- Read BLU JP totals + master level from windower. Returns:
--   {jp_spent=N, master_level=M, gifts=G}
-- where gifts = number of trait-bonus gifts active (0/1/2).
-- Falls back to {0, 0, 0} when player isn't BLU or data missing.
local function ow_get_blu_jp_summary()
    local p = windower.ffxi.get_player()
    if not p then return {jp_spent=0, master_level=0, gifts=0} end
    -- jp_details / job_points field varies by windower version.
    -- Try common shapes: p.job_points.blu, p.job_points['BLU'].
    local jp_spent, master_level = 0, 0
    if p.job_points then
        local entry = p.job_points.blu or p.job_points['BLU']
        if entry then
            -- Different windower builds expose different fields:
            --   jp_spent / spent_jp / total / jp
            jp_spent = tonumber(entry.jp_spent or entry.spent_jp
                                or entry.total or entry.jp or 0) or 0
            master_level = tonumber(entry.master_level or entry.ml or 0) or 0
        end
    end
    -- If nothing, look at top-level shortcuts some builds expose:
    if jp_spent == 0 and p.master_level then
        master_level = tonumber(p.master_level) or 0
    end
    -- Gifts: 100 JP spent → gift 1, 1200 JP spent → gift 2.
    local gifts = 0
    if jp_spent >= 100  then gifts = gifts + 1 end
    if jp_spent >= 1200 then gifts = gifts + 1 end
    return {jp_spent=jp_spent, master_level=master_level, gifts=gifts}
end

-- Resolve the equipped BLU set + JP into trait/stat output. Returns
-- two values: dw_pct (legacy compat) and stats_dict (new: contains
-- everything — DW, DA, TA, MAB, macc, accuracy, attack, defense,
-- store TP, fast cast, plus per-spell flat stats).
local function ow_resolve_blu_set(spell_ids, jp_summary)
    if not spell_ids then return 0, {} end
    -- Build a stable signature that includes JP/ML/gifts so we
    -- recompute when those change too.
    local sorted = {}
    for _, sid in ipairs(spell_ids) do sorted[#sorted+1] = sid end
    table.sort(sorted)
    local sig = table.concat(sorted, ',') .. '|'
        .. tostring(jp_summary.jp_spent) .. '|'
        .. tostring(jp_summary.master_level) .. '|'
        .. tostring(jp_summary.gifts)
    if sig == _ow_blu_cache_signature and _ow_blu_cache then
        return _ow_blu_cache.dw, _ow_blu_cache.stats
    end

    -- Step 1: accumulate trait points across the equipped set.
    local trait_pts = {}     -- e.g. {dw=16, da=4, mab=4}
    local out_stats = {}
    for _, sid in ipairs(spell_ids) do
        local sp = res.spells and res.spells[sid]
        local name = sp and (sp.en or sp.name)
        local entry = name and (OW_BLU_SPELLS[name]
                                or OW_BLU_SPELLS_LC[name:lower()])
        if entry then
            for k, v in pairs(entry) do
                if k == 'stats' then
                    for sk, sv in pairs(v) do
                        out_stats[sk] = (out_stats[sk] or 0) + sv
                    end
                elseif k == 'vitals' or k == 'id' or k == 'level' then
                    -- Metadata fields, not trait points. `vitals` holds
                    -- per-spell HP/MP modifiers (a table — would crash
                    -- the arithmetic below). `id` and `level` are
                    -- numbers but reference data, not contributions to
                    -- trait totals. Skip all three explicitly.
                elseif type(v) == 'number' then
                    trait_pts[k] = (trait_pts[k] or 0) + v
                end
                -- Any other non-number value silently ignored —
                -- protects against future schema additions.
            end
        end
    end

    -- Step 1.5: Double/Triple Attack combined family (bg-wiki: one
    -- spell pool; 8 family points = Double Attack, 16 = Triple Attack,
    -- and Triple Attack REPLACES the spell Double Attack. A subjob's
    -- Double Attack is a separate source that coexists with spell
    -- Triple Attack — the sub max-pool merge below re-adds it.)
    -- Summed across both keys so the data file may attribute family
    -- spells to either; gift-exempt (both tables carry gift=false).
    do
        local fam = (trait_pts.da or 0) + (trait_pts.triple_attack or 0)
        if fam >= 16 then
            trait_pts.triple_attack = fam
            trait_pts.da = nil
        elseif fam >= 8 then
            trait_pts.da = fam
            trait_pts.triple_attack = nil
        end
    end

    -- Step 2: apply gift bonus (+8 per gift) to gift-eligible categories.
    -- Per the BG-wiki hotfix: a trait must already be UNLOCKED by spell
    -- points alone before a gift can boost it — you cannot use the gift to
    -- reach tier I from fewer than 8 points. The unlock threshold is the
    -- first tier value, tbl.points[1] (8 for the standard traits). Gating
    -- on >0 (any points) was the pre-hotfix behaviour and wrongly turned a
    -- single 4-point acc spell + 2 gifts (4+16=20) into a tier-II trait
    -- (+22 acc) when /checkparam shows it grants nothing (4 < 8 = not
    -- unlocked). Verified against isolated (no-subjob) captures: every
    -- single sub-8-point spell reads 0, while two such spells (8 pts total)
    -- correctly unlock and take the gift. Each spell's points come from its
    -- own trait field (e.g. Vanity Dive acc_bonus=4, Anvil Lightning=8).
    local gift_bonus = (jp_summary.gifts or 0) * 8
    for cat, tbl in pairs(OW_BLU_TRAIT_TABLES) do
        local first_threshold = (tbl.points and tbl.points[1]) or 8
        if tbl.gift and gift_bonus > 0
                and (trait_pts[cat] or 0) >= first_threshold then
            trait_pts[cat] = trait_pts[cat] + gift_bonus
        end
    end

    -- Step 2b: fold in the SUBJOB trait-point contribution (bluGuide model).
    -- A subjob that grants the same trait contributes POINTS to that
    -- trait's pool, and the game uses max(spell_pool, sub_points) for the
    -- tier lookup — the BLU spells and the subjob trait do NOT stack
    -- additively (they're the same trait). So we take the higher of the
    -- already-accumulated spell points (with gift) and the subjob's points.
    -- This is why, with /DNC (Accuracy Bonus 8 pts = tier I), a small BLU
    -- acc set shows the DNC tier, and a larger BLU set overtakes it —
    -- matching /checkparam exactly, instead of summing the two (which read
    -- ~10 high). GearInfo's get_player_acc_from_job ALSO adds the subjob's
    -- Accuracy/Attack Bonus into the base acc/att, so for those two traits
    -- the merge must avoid double-counting (handled at merge time via the
    -- sub-value subtraction); here we just make the TIER reflect the max so
    -- the trait value itself is correct for every trait.
    do
        local p = windower.ffxi.get_player()
        local sj = p and p.sub_job and p.sub_job:upper()
        local slvl = p and (p.sub_job_level or 0) or 0
        if sj and slvl >= 30 then
            for cat, subtbl in pairs(OW_BLU_TRAIT_SUBS) do
                local sub_pts = subtbl[sj]
                if sub_pts and sub_pts > 0 then
                    -- RNG's 16-pt acc/etc. needs lvl 30+ too; bluGuide's
                    -- tables already encode the at-cap value, and a BLU
                    -- main always has a high-level sub here, so the >=30
                    -- gate is sufficient for the trait to be active.
                    local cur = trait_pts[cat] or 0
                    if sub_pts > cur then
                        trait_pts[cat] = sub_pts
                    end
                end
            end
        end
    end

    -- Step 3: threshold each category and write into out_stats.
    local function find_tier(points, thresholds, values)
        -- Walk thresholds high→low; first that points >= → that tier.
        for i = #thresholds, 1, -1 do
            if points >= thresholds[i] then
                return values[i], i, thresholds[i]
            end
        end
        return 0, 0, 0
    end

    -- For categories whose canonical tier values are string labels
    -- ("I"/"II"/"III", "GF"/"TH"), the auto-generated table has pct=0
    -- so the simple write-flat path doesn't help. Handle those here
    -- explicitly: choose the right stat key (or pair of stats) based
    -- on which tier was reached.
    --
    --   gilfinder:    8pts → 'gilfinder' = 1, 16pts → 'treasure hunter' = 1
    --   killer cats:  any tier ≥1 → '<type> killer' = 1 flag
    --   resist cats:  any tier ≥1 → 'resist <x>' = tier_index (1..N for I..N)
    --
    -- (DA / TA used to be lumped here as 'da_ta' with 8pts→DA, 16pts→TA.
    -- Per BG-wiki Blue_Mage_Job_Traits they're distinct traits with
    -- different spell sets, so they're now standalone OW_BLU_TRAIT_TABLES
    -- entries with their own stat keys ('double attack', 'triple attack')
    -- and the standard tier-write path handles them — no special case
    -- needed.)
    local function apply_string_tier_trait(cat, tier_idx, pts_required)
        if cat == 'gilfinder' then
            if tier_idx >= 2 then
                out_stats['treasure hunter'] = (out_stats['treasure hunter'] or 0) + 1
            elseif tier_idx >= 1 then
                out_stats['gilfinder'] = (out_stats['gilfinder'] or 0) + 1
            end
        elseif cat == 'auto_refresh' then
            -- Auto Refresh: 8pts threshold gives flat +1 refresh tick.
            if tier_idx >= 1 then
                out_stats['refresh'] = (out_stats['refresh'] or 0) + 1
            end
        else
            -- Generic string-tier categories (Killers, Resists, Rapid Shot,
            -- Macc Bonus, Mev Bonus): record tier index as the stat value.
            -- Downstream the stats panel can render "I/II/III" if desired.
            local tbl = OW_BLU_TRAIT_TABLES[cat]
            if tbl and tbl.stat then
                out_stats[tbl.stat] = (out_stats[tbl.stat] or 0) + tier_idx
            end
        end
    end

    for cat, pts in pairs(trait_pts) do
        local tbl = OW_BLU_TRAIT_TABLES[cat]
        if tbl then
            local val, tier_idx, _ = find_tier(pts, tbl.points, tbl.pct)
            if val > 0 then
                -- Numeric-tier category: write the flat/% value directly.
                out_stats[tbl.stat] = (out_stats[tbl.stat] or 0) + val
            elseif tier_idx > 0 then
                -- String-tier category (DA/TA, Killer, Resist, etc.):
                -- pct came back 0 because the canonical value is a label.
                -- Translate via the helper.
                apply_string_tier_trait(cat, tier_idx, tbl.points[tier_idx])
            end
        end
    end

    -- Step 4: JP-category linear bonuses.
    -- Magic Atk Bonus / Magic Acc Bonus categories add +1 per JP level
    -- they're capped at 20 each (max 1100 JP per category, 20 levels at
    -- 50/100/150/...). Without per-category windower access we can't
    -- read which categories the user spent JP on; we apply a CAP based
    -- estimate only when the user has the corresponding override set.
    -- Skipped for now — we'll surface this as user_config later if you
    -- want it; unsubstantiated guessing would mislead.

    -- Step 5: Master Level gift stat bumps.
    -- ML5: MAB+5, ML10: macc+10, ML15: Tactical Parry trait, ML20: +1 set
    -- slot, ML25: MAB+5 (cum 10), ML30: Auto-Refresh II trait, ML35:
    -- macc+10 (cum 20), ML40: cap pts bonus (no stat), ML45: +5 set pts,
    -- ML50: Resist Petrification.
    local ml = jp_summary.master_level or 0
    if ml >= 5  then out_stats['magic attack bonus'] = (out_stats['magic attack bonus'] or 0) + 5  end
    if ml >= 10 then out_stats['magic accuracy']     = (out_stats['magic accuracy']     or 0) + 10 end
    if ml >= 25 then out_stats['magic attack bonus'] = (out_stats['magic attack bonus'] or 0) + 5  end
    if ml >= 35 then out_stats['magic accuracy']     = (out_stats['magic accuracy']     or 0) + 10 end

    -- Cache + return. dw value preserved for legacy callers.
    local dw = out_stats['dw trait'] or 0
    _ow_blu_cache_signature = sig
    _ow_blu_cache = {dw=dw, stats=out_stats, trait_pts=trait_pts}
    return dw, out_stats
end

-- Pull the currently-equipped BLU spells from windower. Returns a list
-- of spell IDs (numeric) or nil if the player isn't on BLU. Wraps
-- both main-job (BLU/main) and sub-job (BLU/sub) cases.
local function ow_get_blu_set_spells()
    local p = windower.ffxi.get_player()
    if not p then return nil end
    local main_job = p.main_job
    local sub_job  = p.sub_job
    if main_job ~= 'BLU' and sub_job ~= 'BLU' then return nil end
    local data = nil
    if main_job == 'BLU' and windower.ffxi.get_mjob_data then
        data = windower.ffxi.get_mjob_data()
    elseif sub_job == 'BLU' and windower.ffxi.get_sjob_data then
        data = windower.ffxi.get_sjob_data()
    end
    if not data then return nil end
    local raw = data.spells or data.spell_ids or {}
    local out = {}
    local seen = {}
    -- IMPORTANT: walk with pairs(), NOT ipairs(). When a spell is unset
    -- from the MIDDLE of the BLU set (e.g. via bluGuide), windower's
    -- get_mjob_data().spells comes back as a SPARSE array with a nil/hole
    -- where the removed spell was. ipairs() stops at the first nil, so it
    -- silently dropped every spell AFTER the gap — collapsing a 15-spell
    -- set down to just the spell that happened to sit before the hole (the
    -- reported "1 equipped spell" bug, where removing Screwdriver left only
    -- Hysteric Barrage). pairs() visits every key regardless of gaps, so
    -- the full set is always collected. De-dupe defensively in case the
    -- table carries the set under both an array part and named keys.
    for k, v in pairs(raw) do
        if type(v) == 'number' and v > 0 and not seen[v] then
            seen[v] = true
            out[#out+1] = v
        end
    end
    return out
end

-- Walk currently-equipped gear and sum roll-enhancing bonuses for the
-- given roll name (e.g. "Caster's Roll"). Resolves names → IDs lazily
-- on first call and caches.
local function ow_roll_plus_for(roll_name)
    if not _PW_ROLL_GEAR_BY_ID then
        _PW_ROLL_GEAR_BY_ID = {}
        for name, contrib in pairs(PW_ROLL_GEAR_BY_NAME) do
            local item = res.items and (res.items:with('en', name)
                                        or res.items:with('enl', name))
            if item and item.id then
                _PW_ROLL_GEAR_BY_ID[item.id] = contrib
            end
        end
    end
    local equipment = windower.ffxi.get_items
                      and windower.ffxi.get_items('equipment')
    if not equipment then return 0 end
    local total = 0
    local slots = {'main','sub','range','ammo','head','neck',
                   'left_ear','right_ear','body','hands',
                   'left_ring','right_ring','back','waist',
                   'legs','feet'}
    for _, sn in ipairs(slots) do
        local bag = equipment[sn..'_bag']
        local idx = equipment[sn]
        if idx and idx ~= 0 and bag then
            local idata = windower.ffxi.get_items(bag, idx)
            if idata and idata.id then
                local rule = _PW_ROLL_GEAR_BY_ID[idata.id]
                if rule and rule[roll_name] then
                    total = total + rule[roll_name]
                end
            end
        end
    end
    return total
end
do
    local function try_load(name)
        local ok, data = pcall(require, name)
        if ok and type(data) == 'table' then return data end
        return nil
    end
    -- ow_Gifts is now an alias for the global Gifts loaded by
    -- gearinfo/_loader.lua from gearinfo/res/Gifts.lua (single source of
    -- truth). The sim module reads _G.ow_Gifts; consumers in this file
    -- read ow_Gifts directly. Both paths resolve to the same data.
    ow_Gifts                = Gifts                                 or {}
    -- user_config lives in AppData (see ow_user_config_dir comments
    -- above), not the addon folder, so try_load (which uses require
    -- with the addon's package path) won't find it. Use loadfile with
    -- the absolute AppData path. If the file is missing, the template
    -- writer below creates it; ow_user_config stays empty until then.
    do
        local cfg_path = ow_user_config_path()
        local chunk, err = loadfile(cfg_path)
        if chunk then
            local ok, data = pcall(chunk)
            if ok and type(data) == 'table' then
                ow_user_config = data
            else
                ow_chat(123,
                    '[OmniWatch] user_config.lua exists but didn\'t '
                    .. 'return a table -- keeping defaults. Error: '
                    .. tostring(data))
                ow_user_config = {}
            end
        else
            -- File missing or unreadable — that's fine on first run.
            -- Template writer will create it with defaults.
            ow_user_config = {}
        end

        -- ── One-time migration from legacy in-addon location ────────
        -- Earlier versions stored user_config inside addons/OmniWatch/
        -- data/user_config.lua. If we see that AppData is empty (no
        -- bards section) AND the legacy file exists with real values,
        -- copy them over. Only fires when AppData has nothing useful,
        -- so a re-run of the addon never clobbers fresh AppData edits.
        local needs_migration = (
            type(ow_user_config) ~= 'table'
            or ow_user_config.bards == nil
            or next(ow_user_config) == nil)
        if needs_migration then
            local legacy_path = windower.addon_path
                                .. 'data/user_config.lua'
            local legacy_chunk = loadfile(legacy_path)
            if legacy_chunk then
                local ok, legacy_data = pcall(legacy_chunk)
                if ok and type(legacy_data) == 'table'
                        and legacy_data.bards ~= nil then
                    ow_user_config = legacy_data
                    ow_chat(207,
                        '[OmniWatch] migrated user_config.lua from '
                        .. 'addon folder to %APPDATA%\\OmniWatch\\. '
                        .. 'You can delete the old file in '
                        .. 'data/user_config.lua now.')
                    -- The save call later (in setup wizard or chat
                    -- command) will write the new AppData copy. Don't
                    -- save here yet — legacy hand-edits to advanced
                    -- sections we don't round-trip would be lost.
                end
            end
        end
    end
    -- BLU spell trait + stat-bonus table. Populates the empty
    -- OW_BLU_SPELLS declared above and rebuilds the lowercase index.
    -- A missing file leaves both empty (BLU traits don't apply, but
    -- nothing else breaks).
    --
    -- BlueMagic.lua returns a name-keyed table with a `_by_id` sub-table
    -- at the bottom for id→entry fallback lookups; we copy only the
    -- name-keyed entries and leave _by_id accessible via the original
    -- module table for callers that want it.
    do
        local blu = try_load('data/resources/BlueMagic')
        if type(blu) == 'table' then
            for k, v in pairs(blu) do
                if k ~= '_by_id' then
                    OW_BLU_SPELLS[k] = v
                end
            end
            -- Stash the id-keyed fallback for callers that want it.
            OW_BLU_SPELLS_BY_ID = blu._by_id or {}
        end
        for k, v in pairs(OW_BLU_SPELLS) do
            OW_BLU_SPELLS_LC[k:lower()] = v
        end
    end
end

-- ── BRD song data adapter ─────────────────────────────────────────
-- Reads from TWO sources:
--   1. `Bard_Songs` global — loaded by gearinfo/_loader.lua from
--      gearinfo/res/Bard_Songs.lua. Flat id-keyed table, GearInfo-native
--      shape. Each entry has the standard GearInfo fields (id, en,
--      element, effect, ["Bard Bonus"]) PLUS our metadata extensions
--      (family, merit_key, merit_per, jp_key, jp_per, mirror_ranged,
--      marcato_extends_duration, haste_cap). GearInfo ignores the
--      extensions; OmniWatch reads them.
--   2. `gearinfo/res/BardGear.lua` — OmniWatch-specific gear tables
--      (gear name → Song+ levels, duration multipliers, song-class
--      duration). Returns {song_plus, duration, duration_by_class}.
--
-- Builds the legacy-named locals/globals (PW_SONG_GEAR_BY_NAME,
-- PW_SONG_HASTE_BY_NAME, PW_HONOR_MARCH_STATS_BY_NAME,
-- PW_SONG_STATS_BY_NAME, OW_SONG_DURATION_GEAR, OW_SONG_SPECIFIC_GEAR)
-- so existing consumer code works unchanged.
do
    -- Source 1: Bard_Songs global (id-keyed). Set by gearinfo/_loader.lua.
    local songs_by_id = (type(Bard_Songs) == 'table') and Bard_Songs or {}
    -- Source 2: gear tables.
    local ok_gear, bgear = pcall(require, 'gearinfo/res/BardGear')
    if not (ok_gear and type(bgear) == 'table') then bgear = {} end
    PW_SONG_GEAR_BY_NAME  = bgear.song_plus         or {}
    OW_SONG_DURATION_GEAR = bgear.duration          or {}
    OW_SONG_SPECIFIC_GEAR = bgear.duration_by_class or {}

    -- Initialize legacy-named per-song tables.
    PW_SONG_HASTE_BY_NAME        = {}
    PW_HONOR_MARCH_STATS_BY_NAME = {}
    PW_SONG_STATS_BY_NAME        = {}

    -- Walk songs by id, write into the legacy name-keyed tables.
    local song_count = 0
    for _, e in pairs(songs_by_id) do
        if type(e) == 'table' and e.en then
            song_count = song_count + 1
            local name   = e.en
            local effect = e.effect or {}
            local bonus  = e['Bard Bonus'] or {}

            -- Haste songs: GearInfo's effect[1] = 'ma_haste'.
            if effect[1] == 'ma_haste' then
                local cap = e.haste_cap or 8
                if name == 'Honor March' then
                    -- Multi-stat: bonus[plus] is a sub-table indexed
                    -- 1=ma_haste, 2=Accuracy, 3=Attack, 4=Ranged Acc.
                    local per_1024     = {}
                    local stats_by_plus = {}
                    for plus = 0, cap do
                        local row = bonus[plus]
                        if type(row) == 'table' then
                            per_1024[plus]      = row[1] or 0
                            stats_by_plus[plus] = {
                                acc = row[2] or 0,
                                att = row[3] or 0,
                            }
                        end
                    end
                    -- Assert the correct magic-haste values from BG-wiki's
                    -- Honor March potency table, independent of whatever the
                    -- vendored GearInfo Bard_Songs data ships (which has been
                    -- seen carrying a too-low base): +0 = 126/1024 (12.30%),
                    -- then +12/1024 per gear March+ step (138/150/162/174 at
                    -- +1..+4), continuing linearly to cap. Acc/Att rows above
                    -- are left as GearInfo provides them (already correct).
                    -- Kept in sync with honor_march in OmniWatch_Sim.lua.
                    for plus = 0, cap do
                        per_1024[plus] = 126 + 12 * plus
                    end
                    PW_SONG_HASTE_BY_NAME[name]        = {cap=cap, per_1024=per_1024}
                    PW_HONOR_MARCH_STATS_BY_NAME[name] = stats_by_plus
                else
                    -- Flat per-plus list (from GearInfo Bard_Songs).
                    local per_1024 = {}
                    for plus = 0, cap do
                        per_1024[plus] = bonus[plus] or 0
                    end
                    -- Assert the correct march magic-haste values from
                    -- BG-wiki, independent of the vendored GearInfo data.
                    -- Advancing/Victory March scale as
                    --   floor(base * (1 + 0.1 * March+))
                    -- (the HasteInfo/BG-wiki march formula), with base
                    -- 108/1024 (Advancing) and 163/1024 (Victory). Kept in
                    -- sync with advancing_march / victory_march in
                    -- OmniWatch_Sim.lua. Other haste songs keep GearInfo's
                    -- values. (Honor March is handled in the branch above —
                    -- it uses a +12/1024 linear step, not this formula.)
                    local march_base = ({
                        ['Advancing March'] = 108,
                        ['Victory March']   = 163,
                    })[name]
                    if march_base then
                        for plus = 0, cap do
                            per_1024[plus] = math.floor(march_base * (1 + 0.1 * plus))
                        end
                    end
                    PW_SONG_HASTE_BY_NAME[name] = {cap=cap, per_1024=per_1024}
                end
            end

            -- Stat-injection metadata: songs with a family + merit/JP
            -- key get translated into PW_SONG_STATS_BY_NAME for the
            -- generic stat injector.
            if e.family and (e.merit_key or e.jp_key) then
                local stat_key = nil
                local eff1     = effect[1]
                if     eff1 == 'Attack'          then stat_key = 'attack'
                elseif eff1 == 'Accuracy'        then stat_key = 'accuracy'
                elseif eff1 == 'Ranged Accuracy' then stat_key = 'ranged accuracy'
                elseif eff1 == 'DEF'             then stat_key = 'defense'
                elseif eff1 == 'Evasion'         then stat_key = 'evasion'
                end
                if stat_key then
                    local potency = {}
                    for plus = 0, 8 do
                        potency[plus] = bonus[plus] or 0
                    end
                    PW_SONG_STATS_BY_NAME[name] = {
                        family        = e.family,
                        stat          = stat_key,
                        mirror_ranged = e.mirror_ranged or false,
                        potency       = potency,
                        merit_key     = e.merit_key,
                        merit_per     = e.merit_per or 0,
                        jp_key        = e.jp_key,
                        jp_per        = e.jp_per or 0,
                    }
                end
            end
        end
    end

    if song_count == 0 then
        ow_chat(123,
            '[OmniWatch] BardSongs adapter: Bard_Songs global empty -- '
            .. 'gearinfo/_loader may not have loaded gearinfo/res/Bard_Songs.lua.')
    end
end

-- Normalize Cor_Rolls.lua entries. The GearInfo file uses a nested
-- 'bonus' table for the matching-job-in-party bonus, with the job in
-- bonus['Main job'] and the value in bonus.effect. Our compute path
-- expects flat fields bonus_job + job_bonus, so we fill those in here
-- without altering the source file. We also resolve the roll's buff_id
-- by name (each Phantom Roll's buff has the same display name as the
-- ability — "Hunter's Roll" buff sits on you while Hunter's is rolling).
do
    for roll_id, def in pairs(Cor_Rolls or {}) do
        if type(def) == 'table' then
            -- Map nested bonus → flat fields if not already set.
            if not def.bonus_job and def.bonus
               and type(def.bonus) == 'table' then
                local mj = def.bonus['Main job']
                if mj and mj ~= 'NON' and mj ~= '' then
                    def.bonus_job = mj
                end
                if not def.job_bonus and tonumber(def.bonus.effect) then
                    def.job_bonus = tonumber(def.bonus.effect)
                end
            end
            -- Resolve buff_id from the roll's name. Each roll's buff_id
            -- is named identically (Hunter's Roll JA → "Hunter's Roll" buff).
            if not def['status'] and not def['buff_id'] and def.en
               and res.buffs then
                local b = res.buffs:with('en', def.en)
                if not b then
                    b = res.buffs:with('enl', def.en)
                end
                if b and b.id then
                    def['buff_id'] = b.id
                end
            end
        end
    end
end

-- Convenience accessors. These read from the live stats dict (built by
-- ow_compute_stats from gear descriptions), since "Phantom Roll +N",
-- "Marches +N", and "Song +N" all appear as parseable stat lines on gear
-- and augments. Old user_config values (phantom_roll_plus, etc.) are kept
-- Returns the player's total Phantom Roll+ value used to boost roll
-- effects. Source priority:
--   1. ow_user_config.corsairs.self.phantom_roll (set via //ow setup
--      wizard) when non-zero — config is authoritative same as the
--      bard song_bonus chain.
--   2. stats['phantom roll'] (parsed from "Phantom Roll +N" gear
--      description text) as fallback for unconfigured users.
-- Returns 0 if neither source has a value.
local function ow_cfg_phantom_roll_plus(stats)
    local cfg = ow_user_config and ow_user_config.corsairs
                and ow_user_config.corsairs.self
                and tonumber(ow_user_config.corsairs.self.phantom_roll)
    if cfg and cfg > 0 then return cfg end
    return (stats and stats['phantom roll']) or 0
end

-- Walk currently-equipped gear and sum song-family bonuses from the
-- PW_SONG_GEAR_BY_NAME table. Returns the total Song+ levels for the
-- given family (e.g. 'marches', 'minuet'), INCLUDING the 'all' bucket.
-- Resolves names → IDs lazily on first call and caches.
local function ow_song_plus_for_family(family)
    if not _PW_SONG_GEAR_BY_ID then
        _PW_SONG_GEAR_BY_ID = {}
        -- Many items share the same English name across upgrade tiers
        -- (Gjallarhorn 75/80/85/90/95/99/119 all have en="Gjallarhorn",
        -- different IDs). res.items:with('en', name) returns only the
        -- FIRST match — so the user's equipped tier ID may not be in
        -- our map. Iterate the entire item resource table once and
        -- index EVERY ID whose name matches one of our entries.
        if res.items then
            for id, item in pairs(res.items) do
                if type(item) == 'table' then
                    local nm  = item.en
                    local nml = item.enl
                    local rule = (nm  and PW_SONG_GEAR_BY_NAME[nm])
                              or (nml and PW_SONG_GEAR_BY_NAME[nml])
                    if rule then
                        _PW_SONG_GEAR_BY_ID[id] = rule
                    end
                end
            end
        end
    end
    local equipment = windower.ffxi.get_items
                      and windower.ffxi.get_items('equipment')
    if not equipment then return 0 end
    local total = 0
    local hits = {}  -- for debug logging
    local all_slots = {}  -- for verbose debug: every slot + item name
    local slots = {'main','sub','range','ammo','head','neck',
                   'left_ear','right_ear','body','hands',
                   'left_ring','right_ring','back','waist',
                   'legs','feet'}
    for _, sn in ipairs(slots) do
        local bag = equipment[sn..'_bag']
        local idx = equipment[sn]
        if idx and idx ~= 0 and bag then
            local idata = windower.ffxi.get_items(bag, idx)
            if idata and idata.id then
                local item = res.items and res.items[idata.id]
                local nm = (item and (item.en or item.enl)) or ('id:'..idata.id)
                local rule = _PW_SONG_GEAR_BY_ID[idata.id]
                if rule then
                    local add = (rule[family] or 0) + (rule['all'] or 0)
                    if add > 0 then
                        total = total + add
                        hits[#hits+1] = string.format('%s(+%d)', nm, add)
                    end
                    all_slots[#all_slots+1] = string.format(
                        '%s=%s[+%d]', sn, nm, (rule[family] or 0) + (rule['all'] or 0))
                else
                    all_slots[#all_slots+1] = string.format(
                        '%s=%s', sn, nm)
                end
            end
        end
    end
    -- Throttled debug log: only print when the resulting total or hit
    -- list changes, to avoid chat spam on every compute tick.
    local key = family .. '|' .. total .. '|' .. table.concat(hits, ',')
    if _ow_song_walk_last_key ~= key then
        _ow_song_walk_last_key = key
        if _ow_cast_debug then
            ow_chat(207, string.format(
                '[OW] song-gear walk family=%s total=+%d gear=[%s]',
                family, total, table.concat(hits, ', ')))
            -- Verbose dump of every equipped slot. Lets us see what
            -- res.items[id].en returns for each item, so if a piece SHOULD
            -- give song+ but the table key doesn't match the resolved name,
            -- we can spot it.
            local chunk = {}
            for _, line in ipairs(all_slots) do
                chunk[#chunk+1] = line
                if #chunk >= 4 then
                    ow_chat(207, '[OW] eq: '
                        .. table.concat(chunk, ' | '))
                    chunk = {}
                end
            end
            if #chunk > 0 then
                ow_chat(207, '[OW] eq: '
                    .. table.concat(chunk, ' | '))
            end
        end
    end
    return total
end

-- Default user_config template. Used when data/user_config.lua is
-- missing or empty — written to disk on first load, then the user
-- hand-edits it. The previous flat-key schema (blu_dw_override only)
-- has been retired.
--
-- Structure:
--   setup_complete = bool
--                 Set to true after the user completes (or skips)
--                 //ow setup. While false/absent, addon prints a
--                 setup hint on load. Run //ow setup any time to
--                 re-run the wizard regardless of this flag.
--   bards = {
--     self    = { all_songs, minuet, march, madrigal, paeon, ballad,
--                 minne, mambo, prelude, carol, etude, scherzo },
--     <name>  = same shape, lowercase character name = key. Add one
--                 entry per ally bard whose songs you want attributed
--                 with correct potency. The key matches what
--                 buff.Caster carries in Buff_Processing's bard chain
--                 (windower normalizes player names to lowercase).
--   }
--   corsairs = {
--     self    = { phantom_roll },
--     <name>  = same shape for ally cors.
--   }
--
-- Future jobs (geomancers/etc.) can be added as sibling sections
-- without restructuring this one.
--
-- Each numeric value is the +N count for that song family from gear.
-- Examples:
--   all_songs    = 4   -- e.g. Gjallarhorn / Loughnashade
--   carol        = 2   -- e.g. Mousai Gages +1
--   minuet       = 1   -- e.g. Fili Hongreline (any +N tier)
--   phantom_roll = 5   -- e.g. Lanun gear stack
local PW_USER_CONFIG_DEFAULT = {
    setup_complete = false,
    bards = {
        self = {
            all_songs = 0,
            minuet    = 0,
            march     = 0,
            madrigal  = 0,
            paeon     = 0,
            ballad    = 0,
            minne     = 0,
            mambo     = 0,
            prelude   = 0,
            carol     = 0,
            etude     = 0,
            scherzo   = 0,
        },
        -- Add ally bards as sibling entries, lowercase character name
        -- as the key. Buff_Processing reads settings.Bards[buff.Caster]
        -- — buff.Caster is also lowercase, so keying lowercase here
        -- means the lookup hits naturally. Example:
        --   joachim = {
        --       all_songs = 7, march = 1, madrigal = 1, minuet = 1,
        --       paeon = 0, ballad = 0, minne = 0, mambo = 0,
        --       prelude = 0, carol = 0, etude = 0, scherzo = 0,
        --   },
    },
    corsairs = {
        self = {
            phantom_roll = 0,   -- "Phantom Roll +N" from gear (Lanun set, etc.)
        },
        -- Add ally cors keyed by lowercase character name. Example:
        --   sammeh = { phantom_roll = 5 },
    },
}

-- The list of family keys this addon recognizes. Used by the bard
-- settings refresh and the config validator. Keep in sync with the
-- default template above and with `result` in
-- _ow_brd_per_family_song_plus / settings.Bards.song_bonus.
local PW_BARD_FAMILY_KEYS = {
    'all_songs', 'minuet', 'march', 'madrigal', 'paeon', 'ballad',
    'minne', 'mambo', 'prelude', 'carol', 'etude', 'scherzo',
}

-- Geomancer field keys for self/ally entries. Stored under
-- ow_user_config.geomancers.<who>.<field>. Five fields:
--   indi      gear boosting Indi-spell potency
--   geo       gear boosting Geo-spell (Luopan) potency
--   bolster   gear boosting Bolster strength
--   handbell  Handbell skill bonus above 900 (scales "900 skill" base)
--   all       generic +all-geomancy gear bucket
local PW_GEO_FAMILY_KEYS = {
    'indi', 'geo', 'bolster', 'handbell', 'all',
}

-- Stub the old schema constant so any straggler reference doesn't
-- crash. Empty list — no flat keys exist anymore.
local PW_USER_CONFIG_SCHEMA = {}

-- Validate / normalize the loaded user_config to the expected shape.
-- For a nested config we don't "prune" unknown keys (that destroys
-- user's commented experiments). Instead we ensure required sections
-- exist with a default shape, so downstream code can read e.g.
-- ow_user_config.bards.self.carol without nil-checking every level.
do
    if type(ow_user_config) ~= 'table' then
        ow_user_config = {}
    end
    -- bards section
    if type(ow_user_config.bards) ~= 'table' then
        ow_user_config.bards = {}
    end
    if type(ow_user_config.bards.self) ~= 'table' then
        ow_user_config.bards.self = {}
    end
    -- Fill missing family keys on `self` with 0. Per-bard ally entries
    -- are left as-is — sparse entries (only listing non-zero families)
    -- read fine, downstream uses `(t[k] or 0)`.
    for _, fk in ipairs(PW_BARD_FAMILY_KEYS) do
        if ow_user_config.bards.self[fk] == nil then
            ow_user_config.bards.self[fk] = 0
        end
    end
    -- corsairs section. Single field today (phantom_roll), parallel
    -- shape so adding more (e.g. crooked_cards detection) is a one-
    -- liner later.
    if type(ow_user_config.corsairs) ~= 'table' then
        ow_user_config.corsairs = {}
    end
    if type(ow_user_config.corsairs.self) ~= 'table' then
        ow_user_config.corsairs.self = {}
    end
    if ow_user_config.corsairs.self.phantom_roll == nil then
        ow_user_config.corsairs.self.phantom_roll = 0
    end
    -- geomancers section. Mirrors the bard shape: self + zero-or-more
    -- ally entries, each with the five PW_GEO_FAMILY_KEYS fields.
    if type(ow_user_config.geomancers) ~= 'table' then
        ow_user_config.geomancers = {}
    end
    if type(ow_user_config.geomancers.self) ~= 'table' then
        ow_user_config.geomancers.self = {}
    end
    for _, fk in ipairs(PW_GEO_FAMILY_KEYS) do
        if ow_user_config.geomancers.self[fk] == nil then
            ow_user_config.geomancers.self[fk] = 0
        end
    end
    -- Setup completion flag. Drives the first-run prompt and the
    -- conditional setup nag on addon load.
    if ow_user_config.setup_complete == nil then
        ow_user_config.setup_complete = false
    end
end

-- Write the current ow_user_config back to data/user_config.lua, with
-- a friendly comment header. Returns ok, err. Uses raw io.open since
-- the addon path is known and we don't need fancy resource handling.
-- Write a starter user_config.lua if the file is missing. Hand-edit
-- thereafter — the addon does NOT round-trip your edits through chat
-- commands. Runtime config changes (//ow config <bard> <family> <N>)
-- update the in-memory ow_user_config but the user re-saves their
-- file by hand. This avoids fighting with hand-formatted comments.
function ow_write_user_config_template_if_missing()
    ow_write_brd_songgear_template_if_missing()
    -- Make sure %APPDATA%\OmniWatch\ exists before trying to write.
    -- No-ops if it's already there or if we can't run mkdir.
    ow_ensure_user_config_dir()
    local path = ow_user_config_path()
    local existing = io.open(path, 'r')
    if existing then existing:close(); return false end
    -- Binary mode ('wb') intentional: this source file has CRLF line
    -- endings, and Lua's default text-mode write on Windows would
    -- convert `\n` to `\r\n` — which doubles to `\r\r\n` when the
    -- source bytes are already `\r\n`. Binary mode passes bytes
    -- through unchanged. The resulting user_config.lua has CRLF
    -- line endings (matches Windows convention), which Lua's loader
    -- and any text editor handle fine.
    local f, err = io.open(path, 'wb')
    if not f then return false, err end
    f:write([[-- ─────────────────────────────────────────────────────────────────────────
-- OmniWatch user_config.lua
-- ─────────────────────────────────────────────────────────────────────────
-- Lives at: %APPDATA%\OmniWatch\user_config.lua
--   (typically C:\Users\<you>\AppData\Roaming\OmniWatch\user_config.lua)
-- Press Win+R, type %APPDATA%, hit Enter to navigate there.
--
-- This file moved out of the Windower addon folder because Windower
-- installs under Program Files can't write to data/ without admin
-- rights, which made the config wizard appear to silently fail.
--
-- Hand-edit this file, OR run `//ow setup` for a guided wizard.
-- After hand-editing, //lua r omniwatch.
--
-- Migrating to a new system: copy %APPDATA%\OmniWatch\ verbatim.
--
-- Structure:
--   setup_complete = bool — set to true once you've configured (or
--                   skipped) the wizard. While false, OmniWatch
--                   prints a setup hint on load. Run //ow setup
--                   any time to (re)configure.
--   bards.self    = your own song+ totals from gear, summed across
--                   all pieces of your usual cast set.
--   bards.<name>  = ally bard's song+ totals (lowercase character
--                   name as the key). Add one entry per ally bard
--                   you regularly play with whose song potency you
--                   want shown correctly on the panel. Without an
--                   entry, ally songs still get attribution but
--                   apply only base potency. Buff_Processing reads
--                   settings.Bards[buff.Caster] — buff.Caster is
--                   lowercase, so the key here must also be
--                   lowercase to match.
--   corsairs.self = your own Phantom Roll+ from gear (Lanun set,
--                   etc.). Single number that boosts all rolls.
--   corsairs.<name> = ally cor's phantom roll+, same shape.
--
-- Each numeric value is the +N count for that song family (sum
-- across all gear pieces in that bard's typical cast set). Examples:
--   all_songs    = 4   -- Gjallarhorn / Loughnashade
--   carol        = 2   -- Mousai Gages +1
--   minuet       = 1   -- Fili Hongreline (any +N tier prints "Minuet+1")
--   phantom_roll = 5   -- Lanun set with various pieces
--
-- Future jobs (geomancers / etc.) can be added as sibling sections;
-- this file's loader doesn't enforce a fixed top-level shape beyond
-- `bards` and `corsairs`.
-- ─────────────────────────────────────────────────────────────────────────
return {
    setup_complete = false,

    bards = {
        self = {
            all_songs = 0,
            minuet    = 0,
            march     = 0,
            madrigal  = 0,
            paeon     = 0,
            ballad    = 0,
            minne     = 0,
            mambo     = 0,
            prelude   = 0,
            carol     = 0,
            etude     = 0,
            scherzo   = 0,
        },
        -- Add ally bards here. Example:
        -- joachim = {
        --     all_songs = 7,
        --     minuet    = 1, march = 1, madrigal = 1,
        --     paeon = 0, ballad = 0, minne = 0, mambo = 0,
        --     prelude = 0, carol = 0, etude = 0, scherzo = 0,
        -- },
    },

    corsairs = {
        self = {
            phantom_roll = 0,
        },
        -- Add ally cors here. Example:
        -- sammeh = { phantom_roll = 5 },
    },
}
]])
    f:close()
    return true
end

-- Persist the in-memory ow_user_config back to disk in the same shape
-- as the template. Used by //ow config <bard> <family> <N> to commit
-- runtime changes. Preserves only what's in ow_user_config.bards —
-- other top-level sections the user added by hand are NOT preserved
-- (we round-trip only the bards section since that's what we own).
-- If you keep a hand-edit-only workflow you'll never call this.
function ow_save_user_config()
    -- AppData location, not the addon folder — see ow_user_config_dir
    -- comments above. Make sure the dir exists first; on a fresh
    -- install the user might run //ow setup before the load handler
    -- has called ow_write_user_config_template_if_missing.
    ow_ensure_user_config_dir()
    local path = ow_user_config_path()
    local f, err = io.open(path, 'w')
    if not f then return false, err end
    f:write('-- ─────────────────────────────────────────────────────────────────────────\n')
    f:write('-- OmniWatch user_config.lua (auto-saved by //ow setup or //ow config)\n')
    f:write('-- Hand-edit if you prefer; structure is documented in the addon source.\n')
    f:write('-- ─────────────────────────────────────────────────────────────────────────\n')
    f:write('return {\n')
    f:write(string.format('    setup_complete = %s,\n',
        ow_user_config.setup_complete and 'true' or 'false'))
    f:write('\n')
    f:write('    bards = {\n')
    -- Walk known bard keys, write `self` first then sorted ally names.
    local function _emit_bard(key, t)
        f:write(string.format('        %s = {\n', key))
        for _, fk in ipairs(PW_BARD_FAMILY_KEYS) do
            local v = tonumber(t and t[fk]) or 0
            f:write(string.format('            %-10s = %d,\n', fk, v))
        end
        f:write('        },\n')
    end
    local bards = (ow_user_config and ow_user_config.bards) or {}
    if bards.self then _emit_bard('self', bards.self) end
    local ally_names = {}
    for k, _ in pairs(bards) do
        if k ~= 'self' and type(bards[k]) == 'table' then
            ally_names[#ally_names+1] = k
        end
    end
    table.sort(ally_names)
    for _, name in ipairs(ally_names) do
        _emit_bard(name, bards[name])
    end
    f:write('    },\n')
    f:write('\n')
    f:write('    corsairs = {\n')
    local function _emit_cor(key, t)
        f:write(string.format('        %s = {\n', key))
        f:write(string.format('            phantom_roll = %d,\n',
            tonumber(t and t.phantom_roll) or 0))
        f:write('        },\n')
    end
    local cors = (ow_user_config and ow_user_config.corsairs) or {}
    if cors.self then _emit_cor('self', cors.self) end
    local cor_ally_names = {}
    for k, _ in pairs(cors) do
        if k ~= 'self' and type(cors[k]) == 'table' then
            cor_ally_names[#cor_ally_names+1] = k
        end
    end
    table.sort(cor_ally_names)
    for _, name in ipairs(cor_ally_names) do
        _emit_cor(name, cors[name])
    end
    f:write('    },\n')
    f:write('\n')

    -- ── Geomancers section ─────────────────────────────────────────
    -- Wizard-managed gear-scaling values for Indi/Geo spells, Bolster,
    -- Handbell skill, and a generic +all bucket. self + zero-or-more
    -- ally entries; all five fields written for each (sparse 0 fields
    -- kept explicit so hand-editing is obvious). Consumed by
    -- _ow_refresh_geo_settings to populate settings.Geo[<name>].
    f:write('    geomancers = {\n')
    local function _emit_geo(key, t)
        f:write(string.format('        %s = {\n', key))
        for _, fk in ipairs(PW_GEO_FAMILY_KEYS) do
            f:write(string.format('            %-9s = %d,\n',
                fk, tonumber(t and t[fk]) or 0))
        end
        f:write('        },\n')
    end
    local geos = (ow_user_config and ow_user_config.geomancers) or {}
    if geos.self then _emit_geo('self', geos.self) end
    local geo_ally_names = {}
    for k, _ in pairs(geos) do
        if k ~= 'self' and type(geos[k]) == 'table' then
            geo_ally_names[#geo_ally_names+1] = k
        end
    end
    table.sort(geo_ally_names)
    for _, name in ipairs(geo_ally_names) do
        _emit_geo(name, geos[name])
    end
    f:write('    },\n')
    f:write('\n')

    -- ── Player section ──────────────────────────────────────────────
    -- General player-scoped settings the wizard writes alongside the
    -- bard/cor gear data. Currently just unity_rank (1=highest, 11=lowest)
    -- which feeds settings.player.rank via _ow_refresh_unity_rank.
    -- Defaults to 1 if not explicitly set, matching the loader's default.
    f:write('    player = {\n')
    do
        local p = (ow_user_config and ow_user_config.player) or {}
        local ur = tonumber(p.unity_rank) or 1
        if ur < 1  then ur = 1  end
        if ur > 11 then ur = 11 end
        f:write(string.format('        unity_rank = %d,\n', ur))
    end
    f:write('    },\n')
    f:write('}\n')
    f:close()
    return true
end

-- ── Optional icon extractor ─────────────────────────────────────────────────
-- Load icon_extractor lazily and tolerate it being missing / broken.
-- If it fails to load for any reason, the addon still runs and sends data;
-- only the icon extraction is disabled.
local icon_extractor  = nil
local icons_available = false

local ok, mod_or_err = pcall(require, 'icon_extractor')
if ok then
    icon_extractor  = mod_or_err
    icons_available = true
else
    ow_chat(123,
        '[OmniWatch] icon_extractor not loaded: ' .. tostring(mod_or_err))
    ow_chat(123,
        '[OmniWatch] Put icon_extractor.lua in Windower4/addons/OmniWatch/ '
        .. 'to enable icons. Addon will run without them.')
end

-- icon_extractor reads windower.ffxi_path at extraction time. If that isn't
-- set (rare, but possible on some installs), feed it the resolved path.
if icons_available and icon_extractor.ffxi_path then
    local ok2, err2 = pcall(icon_extractor.ffxi_path, windower.ffxi_path)
    if not ok2 then
        ow_chat(123,
            '[OmniWatch] icon_extractor ffxi_path error: ' .. tostring(err2))
    end
end

-- ── Icon cache path ─────────────────────────────────────────────────────────
-- BMPs land in addons/OmniWatch/icons/equipment/<item_id>.bmp
-- (Python reads from icons/equipment/; we write here directly so there's
-- a single canonical location and no duplicate parent-folder cache.)
local function norm_path(p)
    if not p or p == '' then return '' end
    if p:sub(-1) ~= '/' and p:sub(-1) ~= '\\' then p = p .. '/' end
    return p
end

-- windower.addon_path is the reliable variable for an addon's own folder.
-- Fall back to windower_path + 'addons/OmniWatch/' just in case.
local ADDON_PATH = norm_path(windower.addon_path)
if ADDON_PATH == '' then
    ADDON_PATH = norm_path(windower.windower_path) .. 'addons/OmniWatch/'
end
local ICON_DIR = ADDON_PATH .. 'icons/equipment/'
-- Buff/debuff status icons live in a sibling cache folder. Filenames are
-- '<buff_id>.bmp' (windower's status_id == FFXI internal buff id == the
-- DAT row index for the icon). Python loads from icons/status/<id>.bmp.
local STATUS_ICON_DIR = ADDON_PATH .. 'icons/status/'

-- Make sure the icons dir exists. Use `mkdir /q` (Windows shell) which
-- creates intermediate parents implicitly when the path uses backslashes.
-- Probe-write tests writeability after the mkdir, so a failed creation
-- still surfaces a chat error on first use.
do
    for _, d in ipairs({ICON_DIR, STATUS_ICON_DIR}) do
        local probe_path = d .. '.probe'
        local f = io.open(probe_path, 'wb')
        if not f then
            -- /q suppresses interactive prompts; backslash path is required
            -- on Windows for nested dir creation in cmd.exe.
            os.execute('mkdir "' .. d:gsub('/', '\\') .. '" 2>nul')
            f = io.open(probe_path, 'wb')
        end
        if f then f:close(); os.remove(probe_path) end
    end
end

-- ── Multibox display lock (per-character stream tag) ────────────────
-- When 2+ FFXI clients each run their own OmniWatch, all of them send
-- their live-display data to these same fixed ports. The overlay would
-- then flip ("jitter") between characters as packets interleave. To fix
-- this WITHOUT per-character views, every live-display payload is tagged
-- with the SENDING character's name as a "@name@" prefix. The Python
-- overlay locks the display to one character (whoever is picked in the
-- header dropdown / the logged-in char) and DROPS tagged packets from any
-- other character. '@' never appears in FFXI character names or in the
-- payload field delimiters (, ; |), so the prefix is unambiguous and the
-- parser strips it cleanly. Single-box is unaffected: the name always
-- matches the one locked character, so nothing is dropped.
--
-- A GLOBAL function (not a local) to stay clear of Lua 5.1's 200-local
-- ceiling and to be reachable from every send site.
function _OW_MB_TAG(payload)
    local p = windower.ffxi.get_player()
    local nm = (p and p.name) or ''
    return '@' .. nm .. '@' .. payload
end

-- ── Dynamic UDP port discovery (lua side) ───────────────────────
-- The overlay now binds OS-assigned (ephemeral) ports instead of fixed
-- 5000-5015 to dodge Windows reserved-port collisions, and publishes them
-- to ow_ports_py.txt. We read that and point each channel socket at the
-- discovered port. Our own inbound command socket binds ephemerally too and
-- publishes its port to ow_ports_lua.txt. Both files live under
-- %APPDATA%/OmniWatch (ow_user_config_dir()), the dir both sides already
-- use. If discovery is unavailable we fall back to the legacy fixed ports.
OW_LEGACY_PORTS = {
    party=5000, equip=5001, target=5002, zone=5003, status=5004,
    gs=5005, cast=5006, equip_rich=5007, stats=5008, timers=5009,
    dps=5010, inv=5012, chat=5013, skillchain=5015,
}
OW_LEGACY_CMD_PORT = 5011
OW_PORTS_PY_RAW = nil      -- last-read ow_ports_py.txt content (change detect)
OW_NEXT_PORT_POLL = 0      -- throttle for the prerender re-resolve poll

function ow_ports_py_path()  return ow_user_config_dir() .. '/ow_ports_py.txt' end
function ow_ports_lua_path() return ow_user_config_dir() .. '/ow_ports_lua.txt' end

function ow_read_py_ports()
    -- Parse "<channel> <port>" lines from ow_ports_py.txt into {channel=port},
    -- or nil if the file is absent/empty. Updates OW_PORTS_PY_RAW.
    local f = io.open(ow_ports_py_path(), 'r')
    if not f then OW_PORTS_PY_RAW = nil; return nil end
    local raw = f:read('*a'); f:close()
    OW_PORTS_PY_RAW = raw
    if not raw or raw == '' then return nil end
    local ports = {}
    for line in raw:gmatch('[^\r\n]+') do
        local ch, prt = line:match('^(%S+)%s+(%d+)')
        if ch and prt then ports[ch] = tonumber(prt) end
    end
    return ports
end

function ow_resolve_peers(ports)
    -- Point every registered channel socket at its discovered port (or the
    -- legacy fixed port if discovery is unavailable). Safe to call repeatedly.
    if not OW_CHANNEL_SOCKETS then return end
    ports = ports or ow_read_py_ports()
    for ch, sock in pairs(OW_CHANNEL_SOCKETS) do
        if sock then
            local prt = (ports and ports[ch]) or OW_LEGACY_PORTS[ch]
            if prt then pcall(function() sock:setpeername('127.0.0.1', prt) end) end
        end
    end
end

function ow_write_lua_cmd_port(port)
    -- Publish our inbound command port so the overlay can find it.
    local path = ow_ports_lua_path()
    local tmp = path .. '.tmp'
    local f = io.open(tmp, 'w')
    if not f then
        ow_chat(123,
            '[OmniWatch] could not write command-port file: ' .. tostring(path))
        return
    end
    f:write('cmd ' .. tostring(port) .. '\n')
    f:close()
    os.remove(path)            -- os.rename won't overwrite on Windows
    os.rename(tmp, path)
end

function ow_poll_port_discovery(now)
    -- Re-resolve channel peers when ow_ports_py.txt changes (overlay started
    -- after us, or restarted with new ports). Throttled to ~1 Hz.
    now = now or os.clock()
    if now < OW_NEXT_PORT_POLL then return end
    OW_NEXT_PORT_POLL = now + 1.0
    local prev = OW_PORTS_PY_RAW
    local ports = ow_read_py_ports()
    if OW_PORTS_PY_RAW ~= prev then
        ow_resolve_peers(ports)
    end
end

-- Party data  → port 5000
local udp = socket.udp()
udp:setpeername("127.0.0.1", 5000)

-- Equipment data → port 5001
local udp_equip = socket.udp()
udp_equip:setpeername("127.0.0.1", 5001)

-- Rich equipment metadata (tooltip data) → port 5007
-- Format per packet (one per filled slot):
--   slot_idx|item_id|item_name|ilvl|jobs|category|level|augment1|augment2|augment3|augment4
-- Empty fields are still present. '|' in fields escaped as \p.
local udp_equip_rich = socket.udp()
udp_equip_rich:setpeername("127.0.0.1", 5007)

-- Parsed character stats (summed across all equipment) → port 5008
-- Format: lines of "STAT|<key>|<value>" separated by \n in a single packet.
-- Uses checkparam's parsing logic for item description text.
local udp_stats = socket.udp()
udp_stats:setpeername("127.0.0.1", 5008)

-- Target data → port 5002
local udp_target = socket.udp()
udp_target:setpeername("127.0.0.1", 5002)

-- Zone/position data → port 5003
local udp_zone = socket.udp()
udp_zone:setpeername("127.0.0.1", 5003)

-- Mob debuff/buff events → port 5004
-- Line-based ASCII protocol:
--   APPLY|<target_id>|<spell_id>|<effect_id>|<duration>|<actor_id>|<is_buff>
--   REMOVE|<target_id>|<effect_id>
--   CLEAR|<target_id>
local udp_status = socket.udp()
udp_status:setpeername("127.0.0.1", 5004)

-- GearSwap state events → port 5005
-- Line-based ASCII protocol:
--   SET|<literal set path>     (e.g. "Engaged.DW.MaxHaste")
--   STATE|<state fallback>     (e.g. "Engaged.Normal.Burtgang")
local udp_gs = socket.udp()
udp_gs:setpeername("127.0.0.1", 5005)

-- Mob cast/ability events → port 5006
-- Line-based ASCII protocol:
--   CAST_START|<mob_id>|<kind>|<name>
--   CAST_DONE|<mob_id>|<kind>|<name>
--   CAST_CANCEL|<mob_id>
-- kind is "spell" or "ability".
local udp_cast = socket.udp()
udp_cast:setpeername("127.0.0.1", 5006)

-- Build the CFGWIZ|open|<flat-fields> payload from ow_user_config and
-- send it to the pygame overlay. Used by both the //ow setup command
-- handler and the inbound CFGWIZ|request_open from the in-panel
-- "Gear settings" button. Defined AFTER udp_gs is declared so the
-- send call resolves to the right local (Lua's lexical scoping looks
-- backward from where the function body is parsed, not from where
-- it's called).
function _ow_cfgwiz_open()
    if not udp_gs then
        ow_chat(123,
            '[OW Setup] internal error: udp_gs not initialized')
        return
    end
    -- Format: dotted-path=int, comma-separated. Examples:
    --   bards.self.all_songs=4,bards.self.carol=2,
    --   bards.joachim.all_songs=7,
    --   corsairs.self.phantom_roll=5,
    --   player.unity_rank=1
    local parts = {}

    -- Player.unity_rank emitted FIRST so it sorts/reads at the top of
    -- the payload. Default 1 (highest tier) when nothing is saved yet,
    -- matching the loader's default for settings.player.rank. Clamp to
    -- 1..11 to defend against a corrupt config file.
    local ur = ow_user_config and ow_user_config.player
               and tonumber(ow_user_config.player.unity_rank) or 1
    if ur < 1 then ur = 1 end
    if ur > 11 then ur = 11 end
    parts[#parts+1] = string.format('player.unity_rank=%d', ur)

    local function emit_bard(key, t)
        for _, fk in ipairs(PW_BARD_FAMILY_KEYS) do
            parts[#parts+1] = string.format('bards.%s.%s=%d',
                key, fk, tonumber(t and t[fk]) or 0)
        end
    end
    local function emit_cor(key, t)
        parts[#parts+1] = string.format('corsairs.%s.phantom_roll=%d',
            key, tonumber(t and t.phantom_roll) or 0)
    end
    local function emit_geo(key, t)
        for _, fk in ipairs(PW_GEO_FAMILY_KEYS) do
            parts[#parts+1] = string.format('geomancers.%s.%s=%d',
                key, fk, tonumber(t and t[fk]) or 0)
        end
    end
    local bards = (ow_user_config and ow_user_config.bards) or {}
    emit_bard('self', bards.self or {})
    local bard_allies = {}
    for k, _ in pairs(bards) do
        if k ~= 'self' and type(bards[k]) == 'table' then
            bard_allies[#bard_allies+1] = k
        end
    end
    table.sort(bard_allies)
    for _, name in ipairs(bard_allies) do
        emit_bard(name, bards[name])
    end
    local cors = (ow_user_config and ow_user_config.corsairs) or {}
    emit_cor('self', cors.self or {})
    local cor_allies = {}
    for k, _ in pairs(cors) do
        if k ~= 'self' and type(cors[k]) == 'table' then
            cor_allies[#cor_allies+1] = k
        end
    end
    table.sort(cor_allies)
    for _, name in ipairs(cor_allies) do
        emit_cor(name, cors[name])
    end
    local geos = (ow_user_config and ow_user_config.geomancers) or {}
    emit_geo('self', geos.self or {})
    local geo_allies = {}
    for k, _ in pairs(geos) do
        if k ~= 'self' and type(geos[k]) == 'table' then
            geo_allies[#geo_allies+1] = k
        end
    end
    table.sort(geo_allies)
    for _, name in ipairs(geo_allies) do
        emit_geo(name, geos[name])
    end
    local payload = 'CFGWIZ|open|' .. table.concat(parts, ',')
    udp_gs:send(payload)
end

-- ── Timer stream (port 5009) ───────────────────────────────────────────────
-- Carries two related streams to the python overlay's timer panels:
--   RECAST|kind|name|seconds_remaining[|...]   — multiple per packet, one per active cooldown
--   BUFF|name|seconds_remaining|source         — self-cast buff with computed duration
-- kind for RECAST is 'spell' or 'ability'. source for BUFF is 'self', 'other', 'food', 'song', 'roll'.
-- Recast packets are sent at 4Hz (250ms) when polled. Buff packets are sent
-- at cast_complete time + on duration ticks.
local udp_timers = socket.udp()
udp_timers:setpeername("127.0.0.1", 5009)

-- ── DPS tracker stream (port 5010) ────────────────────────────────────────
-- Carries the rolling 5-min combat metrics to the python overlay's DPS
-- panel. Pipe-encoded line protocol; sent at 2 Hz from the prerender tick.
-- Format (single multi-line packet):
--   DPS|<scope>|<window_sec>|<total_white>|<total_magic>|<total_ws>|
--       <hits>|<misses>|<crits>|<blinks>|<parries>|<evasions>|
--       <mob_swings_at_me>|<spell_lands>|<spell_resists>|<longest_hit>
--   WS|<name>|<count>|<total_dmg>|<best>
--   MOB|<mob_name>|<total_dmg>|<seconds_since_last_hit>
--   PARTY|<member_name>|<total_white>|<total_magic>|<total_ws>
-- <scope> is "me" or "all" depending on PW_DPS_INCLUDE_PARTY.
-- The python side discards any panel block when an empty packet arrives
-- (e.g. on zone change or //ow dps reset).
local udp_dps = socket.udp()
udp_dps:setpeername("127.0.0.1", 5010)

-- ── Inventory snapshot stream (port 5012) ─────────────────────────────────
-- Carries per-slot lists of items the current main job can equip from the
-- player's bags. Pushed once at sim mode activation and again whenever
-- inventory changes (item used, gear swap, pull from bag, etc.). Format:
--   SIM_INV|MAIN_JOB|<3-letter job>           — sent first
--   SIM_INV|SLOT|<slot>|<id>:<name>;<id>:<name>;...    — one per slot
--   SIM_INV|END                               — terminator (atomic swap on python side)
-- Slot keys match SIM_GEAR_SLOTS in python: main, sub, range, ammo, head,
-- neck, left_ear, right_ear, body, hands, left_ring, right_ring, back,
-- waist, legs, feet.
local udp_inv = socket.udp()
udp_inv:setpeername("127.0.0.1", 5012)
-- Also exposed on _G so packet-listener do/end blocks defined later in
-- this file (e.g. the Home Point attunement listener) can send on the
-- same inventory channel without bringing the local in scope. Plain
-- alias — same socket, same peer.
_G._ow_udp_inv = udp_inv

-- ── Chat stream (port 5013) ───────────────────────────────────────────────
-- Carries chat-text events (say/party/tell/LS/yell/system) and synthesized
-- battle events (combat actions, buff/debuff applications, /checkparam)
-- to the Python overlay's chat panel. Drained at 10 Hz from the prerender
-- tick via _chat.drain_text(udp_chat). Wire format documented in
-- chat/drain.lua header.
local udp_chat = socket.udp()
udp_chat:setpeername("127.0.0.1", 5013)

-- ── Skillchain stream socket (shared with Skillchains.lua) ──────────
-- Owned here so all UDP port management lives in one place; Skillchains.lua
-- adopts this via _G._ow_udp_skillchain instead of opening its own socket.
_G._ow_udp_skillchain = socket.udp()
_G._ow_udp_skillchain:settimeout(0)

-- Channel registry: name -> socket. Names match the keys the overlay writes
-- to ow_ports_py.txt. ow_resolve_peers() points each at the discovered port.
OW_CHANNEL_SOCKETS = {
    party = udp, equip = udp_equip, equip_rich = udp_equip_rich,
    stats = udp_stats, target = udp_target, zone = udp_zone,
    status = udp_status, gs = udp_gs, cast = udp_cast,
    timers = udp_timers, dps = udp_dps, inv = udp_inv,
    chat = udp_chat, skillchain = _G._ow_udp_skillchain,
}

-- Resolve once now (uses the discovery file if the overlay is already up,
-- else legacy fixed ports; the prerender poll re-resolves on change).
ow_resolve_peers()

-- ── Bags-at-top inventory snapshot (port 5012) ──────────────────────────
-- Separate stream from SIM_INV. Walks every bag and emits one packet per
-- bag plus an INV_END sentinel so the python "bags at top" widget can
-- show item counts and contents per bag. Always-on (not gated by sim
-- activation), but rate-limited to ~once every 5 seconds to avoid wire
-- spam. Format per bag:
--   INV_BAG|<bag_name>|<count>|<id>,<count>,<name>;<id>,<count>,<name>;...
-- Then sentinel:
--   INV_END|<unix_timestamp>
local _ow_bag_inv_last_emit = 0
local _OW_BAG_INV_BAGS = {
    'inventory', 'safe', 'safe2', 'storage', 'locker',
    'satchel',   'sack', 'case',
    'wardrobe',  'wardrobe2', 'wardrobe3', 'wardrobe4',
    'wardrobe5', 'wardrobe6', 'wardrobe7', 'wardrobe8',
}

function _ow_sanitize_item_name(name)
    -- Strip wire delimiters from item names. Returns cleaned string.
    if not name then return '' end
    return (tostring(name):gsub('[|;,]', ' '))
end

local function _ow_emit_inventory_snapshot()
    local items = windower.ffxi.get_items and windower.ffxi.get_items()
    if not items then return end
    for _, bag_name in ipairs(_OW_BAG_INV_BAGS) do
        local bag_data = items[bag_name]
        local entries = {}
        if type(bag_data) == 'table' then
            for slot = 1, 80 do
                local it = bag_data[slot]
                if type(it) == 'table' and it.id and it.id > 0 then
                    local cnt = tonumber(it.count) or 1
                    local nm = ''
                    if res and res.items and res.items[it.id] then
                        nm = res.items[it.id].english or res.items[it.id].en or ''
                    end
                    if nm == '' then nm = '#' .. tostring(it.id) end
                    nm = _ow_sanitize_item_name(nm)
                    entries[#entries + 1] = string.format('%d,%d,%s', it.id, cnt, nm)
                end
            end
        end
        local payload = string.format('INV_BAG|%s|%d|%s',
            bag_name, #entries, table.concat(entries, ';'))
        pcall(function() udp_inv:send(_OW_MB_TAG(payload)) end)
    end

    -- ── Porter Slip contents ─────────────────────────────────────────────
    -- For every porter slip the player holds (across all bags), emit a
    -- line listing the items currently registered to it. Sent BEFORE the
    -- INV_END sentinel so Python's atomic-swap reader picks up slip data
    -- with the same snapshot timestamp as the bag data.
    --
    -- Wire format (one line per slip the player owns):
    --   INV_SLIP|<slip_item_id>|<slip_name>|<count>|<id1>,<name1>;<id2>,<name2>;...
    --
    -- The slips library handles the bitmask math: each slip's extdata is a
    -- packed bitmask of which entries in slips.items[slip_id] are stored;
    -- get_player_items() decodes this into a flat list of item IDs.
    --
    -- Skip silently if the slips lib didn't load on startup, or if the
    -- player owns no slips. Empty slips (zero items registered) are still
    -- emitted with count=0 so the Python panel can show "Slip 01 (0 items)"
    -- consistently with non-empty ones — gives the user a stable list of
    -- their slips even before they've registered anything.
    if _G._ow_slips and _G._ow_slips.get_player_items then
        local _slips = _G._ow_slips    -- cache global → local for hot loop
        local ok, player_slips = pcall(_slips.get_player_items)
        if ok and type(player_slips) == 'table' then
            -- Build the set of slip IDs the player actually holds. The
            -- library's get_player_items() initializes EVERY slip ID to
            -- an empty list regardless of ownership — so we can't just
            -- iterate that table. We have to scan the bag data we
            -- already pulled and check each item's id against the
            -- canonical slip list.
            --
            -- _slips.storages is a list of all slip item IDs; building a
            -- set lets us check `held_slips[it.id]` in O(1) per bag
            -- item. Fast enough that walking every bag a second time is
            -- imperceptible.
            local slip_id_set = {}
            for _, sid in ipairs(_slips.storages) do
                slip_id_set[sid] = true
            end
            local held_slips = {}     -- slip_id → true for slips owned
            for _, bag_name in ipairs(_OW_BAG_INV_BAGS) do
                local bag_data = items[bag_name]
                if type(bag_data) == 'table' then
                    for slot = 1, 80 do
                        local it = bag_data[slot]
                        if type(it) == 'table' and it.id
                                and slip_id_set[it.id] then
                            held_slips[it.id] = true
                        end
                    end
                end
            end

            -- Walk slips.storages for stable ordering (canonical Slip
            -- 01..08 sequence), emit ONLY for slips the player owns.
            -- Empty slips (zero items registered) still emit with
            -- count=0 so the user sees "Slip 05 (0 items)" if they
            -- own an empty slip — gives a stable list of held slips
            -- even before anything's registered to a fresh one.
            for _, slip_id in ipairs(_slips.storages) do
                if held_slips[slip_id] then
                    local stored = player_slips[slip_id] or {}
                    local slip_name = ''
                    if res.items and res.items[slip_id] then
                        slip_name = res.items[slip_id].english
                                 or res.items[slip_id].en or ''
                    end
                    if slip_name == '' then
                        slip_name = '#' .. tostring(slip_id)
                    end
                    slip_name = _ow_sanitize_item_name(slip_name)

                    local item_entries = {}
                    -- stored is a list (sometimes T{} / L{} from Windower's
                    -- container library); use ipairs for a flat walk.
                    for _, iid in ipairs(stored) do
                        local nm = ''
                        if res.items and res.items[iid] then
                            nm = res.items[iid].english
                              or res.items[iid].en or ''
                        end
                        if nm == '' then nm = '#' .. tostring(iid) end
                        nm = _ow_sanitize_item_name(nm)
                        item_entries[#item_entries + 1] =
                            string.format('%d,%s', iid, nm)
                    end
                    local slip_payload = string.format(
                        'INV_SLIP|%d|%s|%d|%s',
                        slip_id, slip_name, #item_entries,
                        table.concat(item_entries, ';'))
                    pcall(function() udp_inv:send(_OW_MB_TAG(slip_payload)) end)
                end
            end
        end
    end

    pcall(function()
        -- ── Currency snapshot ────────────────────────────────────────
        -- Pull the latest values from gil (live read) + the cached
        -- tier-1/2 currencies (filled by the incoming-chunk handler
        -- registered below). One line, simple key=value pairs;
        -- Python parses with str.split.
        --
        -- Always-emitted: even when the cached values are 0 because we
        -- haven't received the first packet yet, the python side needs
        -- something so the header doesn't show stale data from before
        -- the last login. Zero is a fine placeholder.
        local gil_val = 0
        if items and items.gil then
            gil_val = tonumber(items.gil) or 0
        end
        local cur = _G._ow_currency_cache or {}
        local payload = string.format(
            'CURRENCY|gil=%d;sparks=%d;accolades=%d;' ..
            'gallimaufry=%d;temenos=%d;apollyon=%d;' ..
            'escha_beads=%d;nyzul_tokens=%d;ichor=%d',
            gil_val,
            tonumber(cur.sparks) or 0,
            tonumber(cur.accolades) or 0,
            tonumber(cur.gallimaufry) or 0,
            tonumber(cur.temenos) or 0,
            tonumber(cur.apollyon) or 0,
            tonumber(cur.escha_beads) or 0,
            tonumber(cur.nyzul_tokens) or 0,
            tonumber(cur.ichor) or 0)
        udp_inv:send(_OW_MB_TAG(payload))
    end)

    pcall(function()
        -- ── Points snapshot ───────────────────────────────────────────
        -- Three trackable point types:
        --   exp / exp_tnl       — from packet 0x061 cache
        --   cp / cp_tnl         — live-read from get_player().job_points;
        --                          tnl is fixed at 30000 per JP
        --   exemplar / exemplar_tnl — from packet 0x061 cache
        --
        -- CP is read fresh every snapshot because it's available
        -- live through the player table; we don't have to wait for
        -- a packet. EXP and Exemplar come from cache because they
        -- only update on packet receive.
        local pts = _G._ow_points_cache or {}
        local cp_val      = 0
        local cp_tnl_val  = tonumber(pts.cp_tnl) or 30000
        local player = windower.ffxi.get_player and windower.ffxi.get_player()
        if player and player.main_job and player.job_points then
            local mj_key = string.lower(player.main_job)
            local jp_entry = player.job_points[mj_key]
            if type(jp_entry) == 'table' and jp_entry.cp then
                cp_val = tonumber(jp_entry.cp) or 0
            end
        end
        local points_payload = string.format(
            'POINTS|exp=%d;exp_tnl=%d;cp=%d;cp_tnl=%d;' ..
            'exemplar=%d;exemplar_tnl=%d',
            tonumber(pts.exp) or 0,
            tonumber(pts.exp_tnl) or 0,
            cp_val,
            cp_tnl_val,
            tonumber(pts.exemplar) or 0,
            tonumber(pts.exemplar_tnl) or 0)
        udp_inv:send(_OW_MB_TAG(points_payload))
    end)

    pcall(function()
        -- ── Trust ownership snapshot ──────────────────────────────────
        -- Walks the player's known spells and emits the names of those
        -- that resolve to category='Trust' in res.spells. Python uses
        -- this for the checklist's Trusts category (auto-checked rows).
        --
        -- Emitted alongside currencies/points so the same throttle
        -- cadence drives all the slow-changing metadata. The list is
        -- only 30-130 names so a single packet is plenty.
        --
        -- Format: TRUSTS|<name1>|<name2>|...|<nameN>
        -- An empty list emits 'TRUSTS|' (no trailing names). The
        -- separator is '|' because trust names never contain it (and
        -- res.spells normalizes English names without pipes).
        local owned = {}
        if windower.ffxi.get_spells and res and res.spells then
            local ok_spells, spells = pcall(windower.ffxi.get_spells)
            if ok_spells and type(spells) == 'table' then
                for sid, has in pairs(spells) do
                    if has then
                        local spell = res.spells[sid]
                        if spell and spell.type == 'Trust' then
                            local nm = spell.english or spell.en or ''
                            if nm ~= '' then
                                owned[#owned + 1] = nm
                            end
                        end
                    end
                end
            end
        end
        table.sort(owned)
        local trust_payload = 'TRUSTS|' .. table.concat(owned, '|')
        udp_inv:send(_OW_MB_TAG(trust_payload))
    end)

    pcall(function()
        -- ── BLU spell ownership snapshot ──────────────────────────────
        -- Mirrors the trust snapshot but for Blue Magic. Walks the
        -- player's known spells filtering for type=='BlueMagic' (learned
        -- set), AND enumerates res.spells for every BLU spell that
        -- exists in the game (master list). Both lists are sent so the
        -- python side doesn't need to hardcode a master list that goes
        -- stale when SE adds new spells.
        --
        -- Format: BLU_SPELLS|<learned1>|<learned2>|...||<master1>|<master2>|...
        -- The '||' is the section separator. Spell names never contain
        -- pipes so '|' is safe within each section. Names use spell.en
        -- (Windower's English field) to match the same source any
        -- gearswap addon would use.
        --
        -- Throttle: rides the same cadence as trusts (slow-changing
        -- metadata snapshot). Spell learning happens at most a few
        -- times per session for an active player.
        local learned, master = {}, {}
        if windower.ffxi.get_spells and res and res.spells then
            local ok_spells, spells = pcall(windower.ffxi.get_spells)
            if ok_spells and type(spells) == 'table' then
                for sid, has in pairs(spells) do
                    if has then
                        local spell = res.spells[sid]
                        if spell and spell.type == 'BlueMagic' then
                            local nm = spell.english or spell.en or ''
                            if nm ~= '' then
                                learned[#learned + 1] = nm
                            end
                        end
                    end
                end
            end
            -- Master list: every BLU spell that exists in res.spells,
            -- regardless of whether the player has learned it. This is
            -- the same source Windower's BLU addons use.
            for _, spell in pairs(res.spells) do
                if spell and spell.type == 'BlueMagic' then
                    local nm = spell.english or spell.en or ''
                    if nm ~= '' then
                        master[#master + 1] = nm
                    end
                end
            end
        end
        table.sort(learned)
        table.sort(master)
        local blu_payload = 'BLU_SPELLS|' ..
            table.concat(learned, '|') .. '||' ..
            table.concat(master, '|')
        udp_inv:send(_OW_MB_TAG(blu_payload))
    end)

    pcall(function()
        -- ── Currently equipped BLU set (names) ──────────────────────
        -- Consumed by the overlay's BLU Spellsets panel to highlight
        -- which saved set (if any) matches the live loadout. Only
        -- meaningful on BLU main (the panel's equip path requires it);
        -- otherwise the body is empty and the overlay clears its copy.
        -- Format: BLU_CURRENT|<name1>|<name2>|... (names never contain
        -- pipes).
        local names = {}
        local p = windower.ffxi.get_player()
        if p and p.main_job == 'BLU' then
            local ids = ow_get_blu_set_spells() or {}
            for _, sid in pairs(ids) do
                local sp = res.spells[sid]
                local nm = sp and (sp.english or sp.en)
                if nm then names[#names + 1] = nm end
            end
        end
        table.sort(names)
        udp_inv:send(_OW_MB_TAG('BLU_CURRENT|' .. table.concat(names, '|')))
    end)

    pcall(function()
        -- ── BLU spell→trait catalog + trait tier ladders ─────────────
        -- Consumed by the BLU Spellsets editor so it can group spells
        -- under trait sections and show live trait totals/tiers for
        -- the ticked selection. Two payloads:
        --   BLU_TIERS|<trait_key>=<Label>=<t1,t2,...>=<gift>=<stat>=<v1,v2,...>|...
        --   BLU_TRAITS|<Spell Name>=<set cost>=<key:pts[,key:pts]>|...
        -- Spell/trait names never contain '|' '=' or ','. Sourced from
        -- the same tables the live trait engine uses (OW_BLU_SPELLS +
        -- OW_BLU_TRAIT_TABLES), so the editor's math matches the game.
        -- The trailing <stat>=<values> fields let the Python "show live"
        -- preview map a resolved tier to its actual stat value (e.g. DW
        -- tier III -> 25) without duplicating the pct tables — lua stays
        -- the single source of truth for the numbers.
        if type(OW_BLU_TRAIT_TABLES) == 'table' then
            local tp = {}
            for key, t in pairs(OW_BLU_TRAIT_TABLES) do
                if type(t) == 'table' and t.label
                        and type(t.points) == 'table' then
                    local stat_key = t.stat or ''
                    local vals = ''
                    if type(t.pct) == 'table' then
                        vals = table.concat(t.pct, ',')
                    end
                    tp[#tp + 1] = key .. '=' .. t.label .. '='
                        .. table.concat(t.points, ',') .. '='
                        .. (t.gift and '1' or '0') .. '='
                        .. stat_key .. '=' .. vals
                end
            end
            table.sort(tp)
            udp_inv:send(_OW_MB_TAG('BLU_TIERS|' .. table.concat(tp, '|')))
        end
        if type(OW_BLU_SPELLS) == 'table' then
            -- Set-point cost comes from Windower's res.spells
            -- (blu_points); build an id→cost map once per emit.
            local cost_by_id = {}
            for _, sp in pairs(res.spells) do
                if sp and sp.type == 'BlueMagic' and sp.id then
                    cost_by_id[sp.id] = sp.blu_points or 0
                end
            end
            local parts = {}
            for name, entry in pairs(OW_BLU_SPELLS) do
                if type(entry) == 'table' then
                    local tps = {}
                    for k, v in pairs(entry) do
                        if type(v) == 'number'
                                and k ~= 'id' and k ~= 'level' then
                            tps[#tps + 1] = k .. ':' .. v
                        end
                    end
                    local cost = entry.id and cost_by_id[entry.id] or 0
                    parts[#parts + 1] = name .. '=' .. cost .. '='
                        .. table.concat(tps, ',')
                end
            end
            table.sort(parts)
            udp_inv:send(_OW_MB_TAG('BLU_TRAITS|' .. table.concat(parts, '|')))
        end
        -- Live per-character bonus context: JP gift count (each gift =
        -- +8 points to gift-eligible traits, only once the trait is
        -- unlocked by spell points alone) and the current subjob's
        -- per-trait point pools (game takes max(spell pool, sub pool)).
        -- Format: BLU_BONUS|gifts=<n>|<key>:<pts>|...
        do
            local p2 = windower.ffxi.get_player()
            local prof = ow_get_blu_jp_summary()
            local bparts = { 'gifts=' .. tostring(prof.gifts or 0) }
            local sj = p2 and p2.sub_job and p2.sub_job:upper()
            local slvl = p2 and (p2.sub_job_level or 0) or 0
            if sj and slvl >= 30 and type(OW_BLU_TRAIT_SUBS) == 'table' then
                for cat, subtbl in pairs(OW_BLU_TRAIT_SUBS) do
                    local sp2 = subtbl[sj]
                    if sp2 and sp2 > 0 then
                        bparts[#bparts + 1] = cat .. ':' .. sp2
                    end
                end
            end
            udp_inv:send(_OW_MB_TAG('BLU_BONUS|' .. table.concat(bparts, '|')))
        end
    end)

    pcall(function()
        -- ── Mount ownership snapshot ─────────────────────────────────
        -- Mirrors the BLU snapshot: two pipe-separated sections holding
        -- the learned set and the master list. Mounts come back from
        -- windower.ffxi.get_abilities().mounts as an array of ids (the
        -- key items that grant each mount), and the master list lives
        -- in res.mounts keyed by mount-id.
        --
        -- Format: MOUNTS|<learned1>|<learned2>|...||<master1>|...
        -- Names use mount.english (Windower's English field). Mount
        -- names never contain pipes so '|' is safe within each section.
        local learned, master = {}, {}
        if windower.ffxi.get_abilities and res and res.mounts then
            local ok_abil, abilities = pcall(windower.ffxi.get_abilities)
            if ok_abil and type(abilities) == 'table' then
                -- abilities.mounts is an array of mount IDs the player
                -- owns. Walk it and resolve each to the canonical
                -- english name via res.mounts.
                if type(abilities.mounts) == 'table' then
                    for _, mid in pairs(abilities.mounts) do
                        local m = res.mounts[mid]
                        if m then
                            local nm = m.english or m.en or m.name or ''
                            if nm ~= '' then
                                learned[#learned + 1] = nm
                            end
                        end
                    end
                end
            end
            -- Master list: every mount that exists in res.mounts.
            for _, m in pairs(res.mounts) do
                if m then
                    local nm = m.english or m.en or m.name or ''
                    if nm ~= '' then
                        master[#master + 1] = nm
                    end
                end
            end
        end
        table.sort(learned)
        table.sort(master)
        local mount_payload = 'MOUNTS|' ..
            table.concat(learned, '|') .. '||' ..
            table.concat(master, '|')
        udp_inv:send(_OW_MB_TAG(mount_payload))
    end)

    pcall(function()
        -- ── Spells by school (BLM/WHM/SMN/NIN/BRD/GEO) ───────────────
        -- Generic per-school spell snapshot. Mirrors BLU_SPELLS' shape
        -- (learned|...||master|...) but parameterised over res.spells
        -- type strings, so all the caster checklists auto-mark from the
        -- same packet stream. One packet per school keeps decoding
        -- simple: python routes on the packet prefix, no schema needed.
        --
        -- Schools handled:
        --   BlackMagic   → SPELLS_BLM
        --   WhiteMagic   → SPELLS_WHM
        --   SummonerPact → SPELLS_SMN
        --   Ninjutsu     → SPELLS_NIN
        --   BardSong     → SPELLS_BRD
        --   Geomancy     → SPELLS_GEO
        --
        -- BlueMagic intentionally NOT included here — that category has
        -- its own dedicated emit above with the same shape, kept
        -- separate for backward compatibility with the BLU_SPELLS|
        -- packet python already parses.
        --
        -- Format per school:
        --   SPELLS_<TAG>|<learned1>|<learned2>|...||<master1>|...
        -- Empty learned-section is valid ('SPELLS_WHM|||<master>'
        -- means no spells learned but the master list is present).
        local school_to_tag = {
            BlackMagic   = 'BLM',
            WhiteMagic   = 'WHM',
            SummonerPact = 'SMN',
            Ninjutsu     = 'NIN',
            BardSong     = 'BRD',
            Geomancy     = 'GEO',
        }

        if windower.ffxi.get_spells and res and res.spells then
            -- Walk learned spells once, bucketing by school. Buckets
            -- are keyed by the WIRE TAG ('BLM'/'WHM'/...), not the
            -- spell.type string ('BlackMagic'/'WhiteMagic'/...), so
            -- the emit loop below can read `learned_by_school[tag]`
            -- directly. Use the VALUE side of pairs() to initialize.
            local learned_by_school = {}
            for _, tag in pairs(school_to_tag) do
                learned_by_school[tag] = {}
            end
            local ok_spells, spells = pcall(windower.ffxi.get_spells)
            if ok_spells and type(spells) == 'table' then
                for sid, has in pairs(spells) do
                    if has then
                        local spell = res.spells[sid]
                        if spell then
                            local tag = school_to_tag[spell.type]
                            if tag then
                                local nm = spell.english or spell.en or ''
                                if nm ~= '' then
                                    local bucket = learned_by_school[tag]
                                    bucket[#bucket + 1] = nm
                                end
                            end
                        end
                    end
                end
            end

            -- Walk master res.spells once, bucketing by school. Same
            -- TAG-keyed structure as the learned table above.
            local master_by_school = {}
            for _, tag in pairs(school_to_tag) do
                master_by_school[tag] = {}
            end
            for _, spell in pairs(res.spells) do
                if spell then
                    local tag = school_to_tag[spell.type]
                    if tag then
                        local nm = spell.english or spell.en or ''
                        if nm ~= '' then
                            local bucket = master_by_school[tag]
                            bucket[#bucket + 1] = nm
                        end
                    end
                end
            end

            -- Emit one packet per school.
            for _, tag in pairs(school_to_tag) do
                local learned_arr = learned_by_school[tag]
                local master_arr  = master_by_school[tag]
                table.sort(learned_arr)
                table.sort(master_arr)
                local payload = 'SPELLS_' .. tag .. '|' ..
                    table.concat(learned_arr, '|') .. '||' ..
                    table.concat(master_arr, '|')
                udp_inv:send(_OW_MB_TAG(payload))
            end
        end
    end)

    pcall(function()
        -- ── Weapon Skills by skill type (H2H / Dagger / Sword / etc) ─
        -- Walks windower.ffxi.get_abilities().weapon_skills (an array
        -- of WS IDs the player has unlocked across all jobs) and
        -- enumerates res.weapon_skills for the master list. Buckets by
        -- res.weapon_skills[id].skill — the integer matching the
        -- skills.lua weapon-type ID (1=Hand-to-Hand, 2=Dagger, ...
        -- 12=Staff, 25=Archery, 26=Marksmanship). One packet per
        -- weapon type so python can render a tab per type.
        --
        -- Wire format per weapon type:
        --   WS_<TAG>|<learned1>|<learned2>|...||<master1>|...
        -- where <TAG> is the python-side category key suffix:
        --   H2H, DAG, SWD, GSD, AXE, GAX, SCY, POL, KAT, GKT,
        --   CLB, STF, ARC, MRK
        --
        -- Includes "unlearnable" WSes too: Windower's
        -- res.weapon_skills has no unlearnable flag and the file is
        -- clean (no -1 icons / no empty levels — every entry is a
        -- real WS the canonical resource extractor produced).
        local skill_to_tag = {
            [1]  = 'H2H',  -- Hand-to-Hand
            [2]  = 'DAG',  -- Dagger
            [3]  = 'SWD',  -- Sword
            [4]  = 'GSD',  -- Great Sword
            [5]  = 'AXE',  -- Axe
            [6]  = 'GAX',  -- Great Axe
            [7]  = 'SCY',  -- Scythe
            [8]  = 'POL',  -- Polearm
            [9]  = 'KAT',  -- Katana
            [10] = 'GKT',  -- Great Katana
            [11] = 'CLB',  -- Club
            [12] = 'STF',  -- Staff
            [25] = 'ARC',  -- Archery
            [26] = 'MRK',  -- Marksmanship
        }

        if windower.ffxi.get_abilities and res and res.weapon_skills then
            -- Learned WS IDs come from get_abilities().weapon_skills,
            -- which is an array of integer IDs (one per WS unlocked).
            local learned_by_tag = {}
            for _, tag in pairs(skill_to_tag) do
                learned_by_tag[tag] = {}
            end
            local ok_abil, abilities = pcall(windower.ffxi.get_abilities)
            if ok_abil and type(abilities) == 'table'
               and type(abilities.weapon_skills) == 'table' then
                for _, wsid in pairs(abilities.weapon_skills) do
                    local ws = res.weapon_skills[wsid]
                    if ws and ws.skill then
                        local tag = skill_to_tag[ws.skill]
                        if tag then
                            local nm = ws.english or ws.en or ''
                            if nm ~= '' then
                                local bucket = learned_by_tag[tag]
                                bucket[#bucket + 1] = nm
                            end
                        end
                    end
                end
            end

            -- Master: walk res.weapon_skills.
            local master_by_tag = {}
            for _, tag in pairs(skill_to_tag) do
                master_by_tag[tag] = {}
            end
            for _, ws in pairs(res.weapon_skills) do
                if ws and ws.skill then
                    local tag = skill_to_tag[ws.skill]
                    if tag then
                        local nm = ws.english or ws.en or ''
                        if nm ~= '' then
                            local bucket = master_by_tag[tag]
                            bucket[#bucket + 1] = nm
                        end
                    end
                end
            end

            -- Emit one packet per weapon type.
            for _, tag in pairs(skill_to_tag) do
                local learned_arr = learned_by_tag[tag]
                local master_arr  = master_by_tag[tag]
                table.sort(learned_arr)
                table.sort(master_arr)
                local payload = 'WS_' .. tag .. '|' ..
                    table.concat(learned_arr, '|') .. '||' ..
                    table.concat(master_arr, '|')
                udp_inv:send(_OW_MB_TAG(payload))
            end
        end
    end)

    pcall(function()
        -- ── Player nation snapshot ───────────────────────────────────
        -- Lightweight metadata the Outpost Warps checklist uses to
        -- annotate its header. Sent on the same cadence as the other
        -- inventory-side snapshots since nation is essentially static
        -- per-session (it can only change via the Immigration NPC).
        --
        -- Format: NATION|<id>|<name>
        -- Where <id> is 0=Sandy, 1=Bastok, 2=Windy, 3=Other/Jeuno.
        -- Always 1-2 fields, never empty (we always know the player's
        -- nation when get_player() returns).
        local p = windower.ffxi.get_player and windower.ffxi.get_player()
        if p and type(p.nation) == 'number' then
            local names = {
                [0] = "San d'Oria",
                [1] = "Bastok",
                [2] = "Windurst",
                [3] = "Jeuno",
            }
            local nm = names[p.nation] or ("Nation " .. tostring(p.nation))
            udp_inv:send(_OW_MB_TAG('NATION|' .. tostring(p.nation) .. '|' .. nm))
        end
    end)

    pcall(function() udp_inv:send(_OW_MB_TAG('INV_END|' .. tostring(os.time()))) end)
    _ow_bag_inv_last_emit = os.clock()
end

-- ── Currency packet handler ──────────────────────────────────────────────
-- Listens for the two currency update packets the server pushes:
--   0x113 — Currency Info     (tier-1: Sparks, Accolades, Conquest Pts, …)
--   0x118 — Currency Info 2   (tier-2: Gallimaufry, Temenos, Apollyon, …)
--
-- Uses packets.parse() to extract labeled fields rather than hardcoding
-- byte offsets. fields.lua has had history of wrong offsets (Accolades
-- once was off; curtracker shipped a fix), so we lookup by label and
-- skip silently if a field is missing — that way the addon keeps working
-- if Windower's fields.lua doesn't have everything we need.
--
-- The field labels used here come from the canonical Windower fields.lua;
-- they're the spaces-and-capitalization-sensitive names of the slots in
-- the parsed packet. If Square Enix renames or moves a currency, only
-- this one map needs updating.
--
-- Wrapped in a do...end block so the field-map table and request helper
-- don't add top-level locals — the OmniWatch main chunk is at Lua 5.1's
-- 200-local ceiling and any new local up here would push it over. Inside
-- a do block the variables are scoped and don't count against the main
-- chunk's limit.
do
    local _OW_CURRENCY_FIELDS = {
        ['Sparks of Eminence'] = 'sparks',
        ['Unity Accolades']    = 'accolades',
        ['Gallimaufry']        = 'gallimaufry',
        -- Tier-2 limbus currencies. The field labels in Windower's
        -- fields.lua are 'Temenos Units' and 'Apollyon Units' per
        -- live-packet inspection (the //ow currencydebug dump). Note
        -- the in-game spelling is Temenos (Greek τέμενος), NOT
        -- Tenemos — a common misspelling. Earlier guesses at
        -- 'Temenos Currency' / 'Apollyon Currency' / bare 'Temenos'
        -- and 'Apollyon' all missed; only the 'Units' suffix is
        -- correct. Listing both -Units and the older legacy forms
        -- so we keep working on installs whose fields.lua hasn't
        -- been updated.
        ['Temenos Units']      = 'temenos',
        ['Apollyon Units']     = 'apollyon',
        ['Temenos Currency']   = 'temenos',
        ['Apollyon Currency']  = 'apollyon',
        ['Temenos']            = 'temenos',
        ['Apollyon']           = 'apollyon',
        -- Escha Beads (Escha zone currency for upper-tier crafting/
        -- alluvion skirmish rewards). Windower's fields.lua
        -- typically labels this 'Escha Beads', but some forks use
        -- a bare 'Beads'. Listing both for robustness — if neither
        -- matches on this install, run //ow currencydebug while
        -- opening the currency menu, find the field label in the
        -- dump, and add it here.
        ['Escha Beads']        = 'escha_beads',
        ['Beads']              = 'escha_beads',
        -- Nyzul Isle tokens. The packet field name is one of these
        -- in practice:
        --   'Nyzul Isle Assault Points' — most common modern label
        --   'Nyzul Tokens'              — abbreviated form
        --   'Tokens'                    — older minimal label
        -- Including all three so any current install works without
        -- a fields.lua update.
        ['Nyzul Isle Assault Points'] = 'nyzul_tokens',
        ['Nyzul Tokens']              = 'nyzul_tokens',
        ['Tokens']                    = 'nyzul_tokens',
        -- Ichor (Reisenjima trial / yorcia currency). Usually shows
        -- up as 'Therion Ichor' in fields.lua but the bare 'Ichor'
        -- form exists on some forks.
        ['Therion Ichor']      = 'ichor',
        ['Ichor']              = 'ichor',
    }

    ow_safe_register('incoming chunk', function(id, data)
        if id ~= 0x113 and id ~= 0x118 then return end
        local ok, parsed = pcall(packets.parse, 'incoming', data)
        if not ok or type(parsed) ~= 'table' then
            if _G._ow_currency_debug then
                ow_chat(123, string.format(
                    '[OW currency] 0x%03X parse FAILED: %s',
                    id, tostring(parsed)))
            end
            return
        end
        local cache = _G._ow_currency_cache
        if type(cache) ~= 'table' then return end

        -- Debug: dump every parsed field so we can see what labels
        -- Windower's fields.lua actually produces for this install.
        -- We only print numeric fields (the ones likely to be currencies)
        -- and skip obvious header noise to keep the output readable.
        if _G._ow_currency_debug then
            local field_lines = {}
            for k, v in pairs(parsed) do
                local nv = tonumber(v)
                if nv and nv > 0
                        and k ~= '_size' and k ~= '_sequence'
                        and k ~= '_raw' and k ~= 'sub_kind' then
                    field_lines[#field_lines + 1] =
                        string.format('%s=%s', tostring(k), tostring(nv))
                end
            end
            -- Sort for stable output.
            table.sort(field_lines)
            ow_chat(207, string.format(
                '[OW currency] 0x%03X fields (%d nonzero numeric): %s',
                id, #field_lines, table.concat(field_lines, ', ')))
        end

        local matched = 0
        for label, key in pairs(_OW_CURRENCY_FIELDS) do
            local v = parsed[label]
            if v ~= nil then
                local n = tonumber(v)
                if n then
                    cache[key] = n
                    matched = matched + 1
                end
            end
        end
        if _G._ow_currency_debug then
            ow_chat(207, string.format(
                '[OW currency] 0x%03X matched %d of our known labels',
                id, matched))
        end
    end)

    -- ── Currency request injection ───────────────────────────────────
    -- The server only pushes 0x113 / 0x118 on certain triggers (zone
    -- change, opening the in-game currency menu, certain quest steps).
    -- Without a nudge, an OmniWatch session that stays in one zone
    -- for hours never sees fresh values.
    --
    -- Two outgoing packets refresh both currency tiers:
    --   0x10F "Currency Menu"   → triggers 0x113 (Sparks, Accolades, …)
    --   0x115 "Currency Menu 2" → triggers 0x118 (Gallimaufry,
    --                              Temenos, Apollyon, …)
    -- Both have zero custom fields. We send them together once per
    -- interval, driven by the prerender loop calling
    -- _G._ow_request_currency_update.
    local CURRENCY_REQUEST_INTERVAL = 300   -- seconds (5 minutes)
    _G._ow_request_currency_update = function()
        local now = os.clock()
        if (now - (_G._ow_currency_last_request or 0))
                < CURRENCY_REQUEST_INTERVAL then
            return
        end
        -- Tier-1 + tier-2 each have their own request packet, and
        -- each triggers a different incoming response:
        --   outgoing 0x10F → incoming 0x113 (tier-1: Sparks, Accolades, …)
        --   outgoing 0x115 → incoming 0x118 (tier-2: Gallimaufry,
        --                                    Temenos, Apollyon, …)
        -- Per Windower's data.lua both outgoing requests are
        -- "Currency Menu" / "Currency Menu 2" with zero custom
        -- fields. This is the same pattern Ivaar's Currencies
        -- addon uses to refresh both tiers.
        --
        -- Use packets.inject(packet) — NOT
        -- windower.packets.inject_outgoing — because the latter
        -- expects a pre-built BINARY STRING, while packets.new()
        -- returns a TABLE. packets.inject() does the build →
        -- string → inject for us in one call.
        local r1_ok, r1_err = pcall(function()
            local p = packets.new('outgoing', 0x10F, {})
            packets.inject(p)
        end)
        local r2_ok, r2_err = pcall(function()
            local p = packets.new('outgoing', 0x115, {})
            packets.inject(p)
        end)
        if _G._ow_currency_debug then
            ow_chat(207, string.format(
                '[OW currency] request 0x10F: %s | 0x115: %s',
                (r1_ok and 'OK' or ('FAIL ' .. tostring(r1_err))),
                (r2_ok and 'OK' or ('FAIL ' .. tostring(r2_err)))))
        end
        _G._ow_currency_last_request = now
    end
end

-- ── Points handler (EXP / Exemplar from 0x061, CP live-read) ─────────────
-- Same shape as the currency block above. Listens for incoming 0x061
-- ("Char Stats") packets which carry experience and exemplar fields.
-- Capacity Points (CP) are NOT in 0x061 — they come from a per-job
-- table on the player struct, which we read directly each prerender
-- tick (no packet handler needed).
--
-- Wrapped in do...end so the field-label map doesn't push the main
-- chunk past Lua 5.1's 200-local ceiling.
--
-- The actual fields.lua label for "current experience" varies between
-- builds — pointwatch reads it via raw byte offsets because the labels
-- in fields.lua have been unreliable for these fields. To stay
-- portable, the map below lists every plausible variant; we accept
-- whichever one the user's fields.lua actually exposes. The
-- //ow pointsdebug command (defined elsewhere) dumps the parsed fields
-- so unknown installs can be diagnosed.
do
    local _OW_POINTS_FIELDS = {
        -- Current experience. The canonical labels in Windower's
        -- fields.lua (confirmed via live //ow pointsdebug dump) are
        -- 'Current EXP' and 'Required EXP'. Older / forked builds
        -- may use the longer 'Experience Points' / 'Experience
        -- Points TNL' style, so both forms are listed.
        ['Current EXP']                = 'exp',
        ['Required EXP']               = 'exp_tnl',
        ['Experience Points']          = 'exp',
        ['Experience']                 = 'exp',
        ['Current Experience']         = 'exp',
        ['Experience Points TNL']      = 'exp_tnl',
        ['Experience Needed']          = 'exp_tnl',
        ['Required Experience']        = 'exp_tnl',
        ['Experience TNL']             = 'exp_tnl',
        -- Exemplar from the canonical fields.lua (confirmed labels).
        ['Current Exemplar Points']    = 'exemplar',
        ['Required Exemplar Points']   = 'exemplar_tnl',
    }

    ow_safe_register('incoming chunk', function(id, data)
        if id ~= 0x061 then return end
        local ok, parsed = pcall(packets.parse, 'incoming', data)
        if not ok or type(parsed) ~= 'table' then
            if _G._ow_points_debug then
                ow_chat(123, string.format(
                    '[OW points] 0x061 parse FAILED: %s',
                    tostring(parsed)))
            end
            return
        end
        local cache = _G._ow_points_cache
        if type(cache) ~= 'table' then return end

        -- Diagnostic dump: list every numeric field with its value.
        -- Same pattern as the currency-debug handler.
        if _G._ow_points_debug then
            local field_lines = {}
            for k, v in pairs(parsed) do
                local nv = tonumber(v)
                if nv and nv > 0
                        and k ~= '_size' and k ~= '_sequence'
                        and k ~= '_raw' and k ~= 'sub_kind' then
                    field_lines[#field_lines + 1] =
                        string.format('%s=%s', tostring(k), tostring(nv))
                end
            end
            table.sort(field_lines)
            ow_chat(207, string.format(
                '[OW points] 0x061 fields (%d nonzero numeric): %s',
                #field_lines, table.concat(field_lines, ', ')))
        end

        local matched = 0
        for label, key in pairs(_OW_POINTS_FIELDS) do
            local v = parsed[label]
            if v ~= nil then
                local n = tonumber(v)
                if n then
                    cache[key] = n
                    matched = matched + 1
                end
            end
        end
        if _G._ow_points_debug then
            ow_chat(207, string.format(
                '[OW points] 0x061 matched %d of our known labels',
                matched))
        end
    end)

    -- ── Points request injection ─────────────────────────────────────
    -- Same staleness problem as currencies: the server only pushes
    -- incoming 0x061 (Char Stats) on certain triggers — zone change,
    -- gaining/losing experience, opening the Status menu, leveling
    -- up. If the player parks in town all day, EXP and Exemplar
    -- values never refresh on their own.
    --
    -- Fix: periodically inject outgoing 0x061 ("Equipment Screen")
    -- which tells the server we're opening the equipment window;
    -- the server responds by pushing a fresh incoming 0x061 stats
    -- packet. This is the same mechanism BarFiller and pointwatch
    -- use to keep their EXP bars live.
    --
    -- Per Windower's fields.lua, outgoing 0x061 has one field:
    --   {ctype='data[4]', label='_unknown1'}  -- "Always zero?"
    -- packets.new('outgoing', 0x061, {}) fills it with zeros.
    -- Injection is silent — it does NOT actually open the in-game
    -- equipment menu, only requests the stats data.
    --
    -- Throttled identically to the currency request: once per
    -- interval, driven by the prerender loop calling
    -- _G._ow_request_points_update. Defaults to 5 minutes so we
    -- don't spam the server.
    _G._ow_points_last_request = 0
    local POINTS_REQUEST_INTERVAL = 300   -- seconds (5 minutes)
    _G._ow_request_points_update = function()
        local now = os.clock()
        if (now - (_G._ow_points_last_request or 0))
                < POINTS_REQUEST_INTERVAL then
            return
        end
        local req_ok, req_err = pcall(function()
            local p = packets.new('outgoing', 0x061, {})
            packets.inject(p)
        end)
        if _G._ow_points_debug then
            ow_chat(207, string.format(
                '[OW points] request 0x061: %s',
                (req_ok and 'OK' or ('FAIL ' .. tostring(req_err)))))
        end
        _G._ow_points_last_request = now
    end

    -- ── Live event listeners for instant EXP refresh ─────────────────
    -- The 5-minute throttle is fine for idle sessions, but when the
    -- player is actively grinding it would feel sluggish to see the
    -- header lag 5 minutes behind every kill. Windower fires native
    -- events the instant EXP changes, so we hook those for live
    -- updates between scheduled requests.
    --
    --   'gain experience' — args (amount, chain_number, limit)
    --     Fires on every EXP gain. `limit` is true for limit points
    --     (which we don't track separately — they're the same field
    --     past level 99 anyway).
    --   'lose experience' — args (amount)
    --     Death penalty, etc.
    --   'level up' / 'level down' — TNL resets to a different value,
    --     so we need a fresh 0x061 to get the new "Required EXP".
    --
    -- Strategy: update the cache locally for instant header feedback,
    -- then ALSO inject a 0x061 request to pick up the authoritative
    -- value from the server (chain bonus, Exemplar tick, etc.). We
    -- bypass the throttle for these — they're rare enough that there's
    -- no spam concern (the throttle exists for the periodic refresh,
    -- not for event-driven updates).
    local function _ow_force_points_refresh()
        _G._ow_points_last_request = 0
        if _G._ow_request_points_update then
            pcall(_G._ow_request_points_update)
        end
        -- Also force the next inventory snapshot to emit immediately,
        -- so python sees the new value without waiting for the regular
        -- snapshot cadence.
        _ow_bag_inv_last_emit = 0
    end

    ow_safe_register('gain experience', function(amount, _chain, limit)
        local cache = _G._ow_points_cache
        if type(cache) == 'table' and tonumber(amount) then
            -- Optimistic local update for instant feedback. The 0x061
            -- request below will overwrite with the authoritative
            -- value if our math drifts.
            cache.exp = (tonumber(cache.exp) or 0) + tonumber(amount)
            -- Clamp so we never display "60000/56000" briefly during
            -- the round-trip — when current >= required, show the
            -- cap until the server confirms.
            local tnl = tonumber(cache.exp_tnl) or 0
            if tnl > 0 and cache.exp > tnl then
                cache.exp = tnl
            end
        end
        _ow_force_points_refresh()
    end)

    ow_safe_register('lose experience', function(amount)
        local cache = _G._ow_points_cache
        if type(cache) == 'table' and tonumber(amount) then
            cache.exp = math.max(0,
                (tonumber(cache.exp) or 0) - tonumber(amount))
        end
        _ow_force_points_refresh()
    end)

    ow_safe_register('level up', function(_level)
        -- TNL changes on level up. The optimistic update above can't
        -- predict the new threshold, so just force a refresh and let
        -- the server tell us.
        _ow_force_points_refresh()
    end)
    ow_safe_register('level down', function(_level)
        _ow_force_points_refresh()
    end)
end

-- ── Teleport Ring recharge timers ─────────────────────────────────────────
-- Tracks cooldowns for the four enchanted teleport rings (Warp,
-- Dem, Holla, Mea) by watching action packets for the player using
-- one. Same mechanism as the original Warp-Ring-only module:
--   * a central handle_incoming_action hook receives every action
--     the addon parses
--   * we deep-walk the action's numeric fields looking for any of
--     our tracked item ids
--   * on match, stamp os.time() as the per-ring use timestamp
--
-- Wire format (single line, emitted at 1Hz):
--     RINGS|warp=<sec>;dem=<sec>;holla=<sec>;mea=<sec>
--
-- Per-ring values are seconds remaining (0 = ready). The python side
-- cycles which ring's status it displays in the equipment-panel
-- header every N seconds (user-configurable in the Equipment modal).
--
-- ID NOTES
-- --------
-- Warp Ring's id (28540) was confirmed via in-game testing. The
-- other three I've set to my best-guess sequential ids; if any
-- ring doesn't trigger the timer on first use, enable debug
-- (//ow warpring) and use the ring — the debug line will print
-- "WR hook saw action cat=N param=N" with the ring's actual id.
-- Update the corresponding entry below if param doesn't match.
do
    local POLL_SEC = 1

    -- Per-ring config table. Item IDs confirmed in-game by BalladOfWorms:
    --   Warp Ring         28540  600s    (10 min)
    --   Dem Ring          26177  600s    (10 min)
    --   Holla Ring        26176  600s    (10 min)
    --   Mea Ring          26178  600s    (10 min)
    --   Echad Ring        27556  7200s   (2 hr — instant Adoulin warp)
    --   Trizek Ring       27557  7200s   (2 hr — instant Ru'Lude warp)
    --   Reraise Ring      26169  72000s  (20 hr — single-charge reraise)
    --   Endorsement Ring  28469  7200s   (2 hr — exp/cp bonus)
    --   Emporox's Ring    28470  7200s   (2 hr — sparks bonus)
    -- To add another tracked ring, append an entry — the rest of
    -- the module is generic. The python side picks up any keys
    -- present in the RINGS|... payload that match its ring_state
    -- dict (and only those rings; unknown keys are ignored).
    local RINGS = {
        { key='warp',        id=28540, name='Warp Ring',        cooldown=600   },
        { key='dem',         id=26177, name='Dem Ring',         cooldown=600   },
        { key='holla',       id=26176, name='Holla Ring',       cooldown=600   },
        { key='mea',         id=26178, name='Mea Ring',         cooldown=600   },
        { key='echad',       id=27556, name='Echad Ring',       cooldown=7200  },
        { key='trizek',      id=27557, name='Trizek Ring',      cooldown=7200  },
        { key='reraise',     id=26169, name='Reraise Ring',     cooldown=72000 },
        { key='endorsement', id=28469, name='Endorsement Ring', cooldown=7200  },
        { key='emporox',     id=28470, name="Emporox's Ring",   cooldown=7200  },
    }

    -- Build a fast id→ring lookup so the action hook can route a
    -- detected id to the right ring in O(1) instead of scanning.
    local RING_BY_ID = {}
    for _, r in ipairs(RINGS) do RING_BY_ID[r.id] = r end

    -- Per-ring state: last_use_at[key] = os.time() of last detected
    -- use, or nil if never used (or pre-reload). Reload loses this.
    local _last_use_at = {}
    local _last_poll   = 0

    local function _compute_remaining(ring)
        local last = _last_use_at[ring.key]
        if not last then return 0 end
        local elapsed = os.time() - last
        local rem = ring.cooldown - elapsed
        if rem < 0 then rem = 0 end
        return rem
    end

    -- Deep-walks a table looking for any matching ring id. Returns
    -- the ring entry whose id was found, or nil. Single pass — finds
    -- the FIRST id match in walk order, which is fine since you
    -- can only activate one ring per action.
    local function _find_ring_id_in(t, depth)
        if depth > 5 then return nil end
        for k, v in pairs(t) do
            if type(v) == 'number' then
                local ring = RING_BY_ID[v]
                if ring then return ring end
            elseif type(v) == 'table' then
                local found = _find_ring_id_in(v, depth + 1)
                if found then return found end
            end
        end
        return nil
    end

    -- Action-detection hook called from handle_incoming_action.
    -- Same approach as the prior warp-ring-only version, just
    -- generalized to all four rings.
    _G._ow_warp_ring_check = function(act)
        if not act or not act.actor_id then return end
        local player = windower.ffxi.get_player()
        if not (player and player.id) then return end
        if act.actor_id ~= player.id then return end

        if _G._ow_warp_ring_debug then
            ow_chat(207, string.format(
                '[OmniWatch] ring hook saw action cat=%s param=%s',
                tostring(act.category), tostring(act.param)))
        end

        local ring = _find_ring_id_in(act, 0)
        if ring then
            _last_use_at[ring.key] = os.time()
            if _G._ow_warp_ring_debug then
                ow_chat(207, string.format(
                    '[OmniWatch] %s used (id=%d cat=%s); '
                    .. 'cooldown started (%ds)',
                    ring.name, ring.id, tostring(act.category),
                    ring.cooldown))
            end
            _last_poll = 0  -- force next emit
        end
    end

    -- Periodic emit. Single RINGS|... line carrying all four rings'
    -- remaining seconds. Python parses and stores per-ring state for
    -- its cycle display.
    _G._ow_warp_ring_poll = function()
        local now = os.clock()
        if (now - _last_poll) < POLL_SEC then return end
        _last_poll = now
        if not udp_inv then return end

        local parts = {}
        for _, ring in ipairs(RINGS) do
            parts[#parts+1] = string.format(
                '%s=%d', ring.key, _compute_remaining(ring))
        end
        local payload = 'RINGS|' .. table.concat(parts, ';')
        pcall(function() udp_inv:send(_OW_MB_TAG(payload)) end)
    end

    -- Diagnostic.
    _G._ow_warp_ring_diag = function()
        local hook_ok = (_G._ow_warp_ring_check ~= nil)
        local poll_ok = (_G._ow_warp_ring_poll ~= nil)
        ow_chat(207, string.format(
            '[OmniWatch] Teleport Rings: hook=%s poll=%s',
            hook_ok and 'installed' or 'MISSING',
            poll_ok and 'installed' or 'MISSING'))
        for _, ring in ipairs(RINGS) do
            local rem  = _compute_remaining(ring)
            local last = _last_use_at[ring.key]
            local age  = last and (tostring(os.time() - last) .. 's ago')
                              or 'never'
            ow_chat(207, string.format(
                '[OmniWatch]   %-10s id=%d cd=%ds  last=%s  remaining=%ds',
                ring.name, ring.id, ring.cooldown, age, rem))
        end
        _G._ow_warp_ring_debug = not _G._ow_warp_ring_debug
        ow_chat(207,
            '[OmniWatch] ring debug = '
            .. tostring(_G._ow_warp_ring_debug)
            .. ' (when on: prints every player action received)')
    end

    -- Manual reset of all ring cooldowns.
    _G._ow_warp_ring_reset = function()
        for _, ring in ipairs(RINGS) do
            _last_use_at[ring.key] = nil
        end
        _last_poll = 0
        ow_chat(207,
            '[OmniWatch] Teleport Rings: cleared all cooldowns')
    end
end

-- ── Warp proximity scanner (Home Point / Survival Guide) ───────────────────
-- Drives the python overlay's floating Warp button. Scans nearby entities
-- for a Home Point or Survival Guide NPC within superwarp's usable range
-- (6 yalms, matching superwarp's own find_npc threshold) and emits a tiny
-- status line so the button can pulse when travel is possible:
--
--   WARPNEAR|hp=<0|1>;sg=<0|1>
--
-- Self-throttled (~2 Hz) so it's cheap to call every prerender. MB-tagged
-- so multiboxers only see the locked character's proximity. The actual
-- warp is performed by superwarp via a WARP|... command the overlay sends
-- back (handled in the inbound drain), not here — this is detection only.
do
    local _WARP_NEAR_POLL_SEC = 0.5
    local _WARP_NEAR_RANGE_SQ = 6 * 6     -- 6 yalms, squared (2D)
    local _warp_near_last     = 0
    -- One entry per superwarp network, in WARPNEAR field order (must
    -- match the python overlay's WARP_NETWORKS). `any` lists lowercased
    -- substrings of the network's NPC names; `exclude` vetoes a match
    -- (Waypoint vs Proto-Waypoint, whose name CONTAINS 'waypoint').
    -- Person-named NPCs (abyssea town teleporters, Unity concierges)
    -- are guarded by the NPC-only spawn_type filter in the loop, so a
    -- nearby PLAYER named e.g. 'Vincent' can't light a network.
    local _WARP_NEEDLES = {
        { key = 'hp',  any = { 'home point' } },
        { key = 'sg',  any = { 'survival guide' } },
        { key = 'wp',  any = { 'waypoint' }, exclude = 'proto-waypoint' },
        { key = 'ab',  any = { 'veridical conflux', 'cavernous maw',
                               'ernst', 'ivan', 'willis', 'horst',
                               'kierron', 'vincent' } },
        { key = 'ew',  any = { 'eschan portal', 'ethereal ingress',
                               'undulating confluence',
                               'dimensional portal' } },
        { key = 'po',  any = { 'runic portal' } },
        { key = 'pwp', any = { 'proto-waypoint' } },
        { key = 'un',  any = { 'igsli', 'urbiolaine', 'teldro-kesdrodo',
                               'yonolala', 'nunaarl bthtrogg' } },
        { key = 'vw',  any = { 'atmacite refiner' } },
    }

    _G._ow_warp_near_poll = function()
        local now = os.clock()
        if (now - _warp_near_last) < _WARP_NEAR_POLL_SEC then return end
        _warp_near_last = now
        if not udp_inv then return end
        if not (windower.ffxi and windower.ffxi.get_mob_array) then return end

        local me = windower.ffxi.get_mob_by_target
                   and windower.ffxi.get_mob_by_target('me')
        local near = {}
        local remaining = #_WARP_NEEDLES
        if me and me.x and me.y then
            for _, v in pairs(windower.ffxi.get_mob_array()) do
                if type(v) == 'table' and v.valid_target and v.name
                        and v.x and v.y
                        -- NPC-only: spawn_type 2 = NPC. Players (13)
                        -- and monsters (16) never count, so a player
                        -- named after a teleporter NPC can't match.
                        and (v.spawn_type == nil or v.spawn_type == 2) then
                    local dx, dy = v.x - me.x, v.y - me.y
                    if (dx * dx + dy * dy) <= _WARP_NEAR_RANGE_SQ then
                        local lname = v.name:lower()
                        for _, spec in ipairs(_WARP_NEEDLES) do
                            if not near[spec.key]
                                    and not (spec.exclude and lname:find(
                                        spec.exclude, 1, true)) then
                                for _, needle in ipairs(spec.any) do
                                    if lname:find(needle, 1, true) then
                                        near[spec.key] = true
                                        remaining = remaining - 1
                                        break
                                    end
                                end
                            end
                        end
                        if remaining <= 0 then break end
                    end
                end
            end
        end

        local parts = {}
        for _, spec in ipairs(_WARP_NEEDLES) do
            parts[#parts + 1] = spec.key .. '='
                .. (near[spec.key] and 1 or 0)
        end
        local payload = 'WARPNEAR|' .. table.concat(parts, ';')
        pcall(function() udp_inv:send(_OW_MB_TAG(payload)) end)
    end
end

-- ── Home Point attunement listener ────────────────────────────────────────
-- Sniffs the incoming Home Point NPC menu packets and decodes the
-- attunement bitfield so the python checklist can mark visited HPs.
-- Menu packets are 0x032 and 0x034 (NPC interaction start, two
-- variants). The packet carries a "Menu ID" we can match to identify
-- a Home Point NPC (8700..8704), and a 32-byte "Menu Parameters" field
-- whose first 16 bytes are four little-endian uint32s. Each bit N of
-- the 128-bit concatenation = "HP #N is attuned" (same indexing as
-- DarkstarProject's homepoint.lua / Windower's res tables).
--
-- Emit format to python: HOMEPOINTS|i1,i2,i3,...
-- Indices are decimal strings; empty list emits 'HOMEPOINTS|'.
-- Python merges these additively, since reading the bitfield from
-- one NPC visit doesn't invalidate previous visits.
--
-- Wrapped in do...end to keep the OW_HP_MENU_IDS local out of the
-- main chunk's 200-local pool.
do
    local OW_HP_MENU_IDS = {
        [8700] = true, [8701] = true, [8702] = true,
        [8703] = true, [8704] = true,
    }

    -- Dedicated debug log file for HP packet captures. The chat-only
    -- log is too narrow for full 50+ byte packet dumps (FFXI chat
    -- truncates around 100 chars), so we mirror the same APPDATA path
    -- emit.lua uses for chatdebug_log.txt but with a distinct
    -- filename so we don't churn it up with chat traffic.
    local _hp_log_file = nil
    local function _ow_hp_filelog(line)
        if not _G._ow_hp_debug then return end
        if not _hp_log_file then
            local path
            local appdata = os.getenv('APPDATA')
            if appdata and appdata ~= '' then
                appdata = appdata:gsub('\\', '/')
                path = appdata .. '/OmniWatch/hpdebug_log.txt'
            else
                local base = windower.addon_path or ''
                if base ~= '' and base:sub(-1) ~= '/'
                                and base:sub(-1) ~= '\\' then
                    base = base .. '/'
                end
                path = base .. 'data/hpdebug_log.txt'
            end
            local f, err = io.open(path, 'a')
            if not f then
                ow_chat(123,
                    '[OW HP] file open failed (' .. tostring(err)
                    .. '). File log disabled.')
                return
            end
            _hp_log_file = f
            local now = os.date('*t')
            f:write(string.format(
                '\n=== HP debug trace started %04d-%02d-%02d %02d:%02d:%02d ===\n',
                now.year, now.month, now.day,
                now.hour, now.min, now.sec))
        end
        _hp_log_file:write(line)
        _hp_log_file:write('\n')
        _hp_log_file:flush()
    end

    local function _ow_hp_log(fmt, ...)
        if _G._ow_hp_debug then
            local line = string.format('[OW HP] ' .. fmt, ...)
            ow_chat(207, line)
            _ow_hp_filelog(line)
        end
    end

    local function _ow_hp_dump_bytes(label, s)
        if not _G._ow_hp_debug or not s then return end
        local hex = {}
        for i = 1, #s do
            hex[i] = string.format('%02X', s:byte(i))
        end
        -- File-only (too long for chat). Format in rows of 16 bytes
        -- for readability.
        _ow_hp_filelog(string.format('%s (%d bytes):', label, #s))
        for row_start = 1, #hex, 16 do
            local row_end = math.min(row_start + 15, #hex)
            local row = {}
            for i = row_start, row_end do
                row[#row + 1] = hex[i]
            end
            _ow_hp_filelog(string.format('  %04X  %s',
                row_start - 1, table.concat(row, ' ')))
        end
    end

    local function _ow_emit_homepoints(idxs)
        local sock = _G._ow_udp_inv
        if not sock then
            _ow_hp_log('emit FAILED: _G._ow_udp_inv not bound yet')
            return
        end
        local payload = 'HOMEPOINTS|' .. table.concat(idxs, ',')
        local sent_ok, sent_err = pcall(function() sock:send(payload) end)
        if not sent_ok then
            _ow_hp_log('UDP send FAILED: %s', tostring(sent_err))
        else
            _ow_hp_log('emitted %d indices', #idxs)
        end
    end

    ow_safe_register('incoming chunk', function(id, data)
        if id ~= 0x032 and id ~= 0x034 then return end
        _ow_hp_log('saw 0x%03X packet, %d bytes', id, #data)
        -- Always dump the full raw packet to the file log when debug
        -- is on, regardless of Menu ID. This is the critical bit:
        -- previous diagnostics only saw the parsed 'Menu Parameters'
        -- field, which is just one slice of the packet. Looking at the
        -- whole packet lets us find where the real attunement bitfield
        -- actually lives.
        _ow_hp_dump_bytes(string.format('raw 0x%03X', id), data)

        local ok, parsed = pcall(packets.parse, 'incoming', data)
        if not ok or type(parsed) ~= 'table' then
            _ow_hp_log('packets.parse FAILED: %s', tostring(parsed))
            return
        end

        if _G._ow_hp_debug then
            local field_names = {}
            for k, _v in pairs(parsed) do
                field_names[#field_names + 1] = tostring(k)
            end
            table.sort(field_names)
            _ow_hp_log('parsed fields: %s', table.concat(field_names, ', '))
            -- Dump every parsed field's value to the file log. For
            -- string-valued fields, dump as hex (these are the binary
            -- chunks we need to inspect). For numeric, just print
            -- the decimal value.
            for _, k in ipairs(field_names) do
                local v = parsed[k]
                if type(v) == 'string' then
                    _ow_hp_dump_bytes(string.format('  field %q', k), v)
                elseif type(v) == 'number' then
                    _ow_hp_filelog(string.format(
                        '  field %q = %s (0x%X)',
                        k, tostring(v), v))
                else
                    _ow_hp_filelog(string.format(
                        '  field %q = %s', k, tostring(v)))
                end
            end
        end

        local menu_id = tonumber(parsed['Menu ID'])
        _ow_hp_log('Menu ID = %s', tostring(menu_id))
        if not menu_id or not OW_HP_MENU_IDS[menu_id] then
            _ow_hp_log('Menu ID not in HP set; skipping decode')
            return
        end

        local params = parsed['Menu Parameters']
        if type(params) ~= 'string' then
            _ow_hp_log('Menu Parameters not a string (got %s)',
                type(params))
            return
        end
        if #params < 16 then
            _ow_hp_log('Menu Parameters too short (%d bytes)', #params)
            return
        end

        local function u32_le(s, off)
            local b1, b2, b3, b4 = s:byte(off, off + 3)
            if not b1 then return 0 end
            return b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
        end
        -- Attunement bitfield layout INSIDE Menu Parameters:
        -- Bytes 0..3 are leading metadata (always 00 00 00 00 on real
        -- captures from a player with HPs attuned — appears to be a
        -- header / cost / fee field of some kind, not the bitfield).
        -- Bytes 4..19 are the four little-endian uint32 attunement
        -- chunks. Bytes 20..31 are unrelated NPC interaction metadata.
        --
        -- Verified against a real packet capture from a player who had
        -- attuned through HP index 121: read at offset 4 yielded
        -- Sets 0-3 = 0xFFFFFFFF, 0xFFFFFFFF, 0xFFEEFFF7, 0x03FFFFFF.
        -- That last one has its top 6 bits clear which matches the
        -- 122-entry master list (indices 0..121, bits 122..127 padded
        -- to zero). Reading from offset 0 instead produced spurious
        -- all-FF data that included nonexistent HP indices.
        --
        -- Lua strings are 1-indexed, so packet byte offset 4 = Lua
        -- string offset 5.
        local sets = {
            u32_le(params, 5),   -- HPs 0..31
            u32_le(params, 9),   -- HPs 32..63
            u32_le(params, 13),  -- HPs 64..95
            u32_le(params, 17),  -- HPs 96..127
        }
        _ow_hp_log('Sets: 0x%08X 0x%08X 0x%08X 0x%08X',
            sets[1], sets[2], sets[3], sets[4])

        local idxs = {}
        for set_i = 1, 4 do
            local v = sets[set_i]
            local base = (set_i - 1) * 32
            for bit_i = 0, 31 do
                if (math.floor(v / (2 ^ bit_i)) % 2) == 1 then
                    idxs[#idxs + 1] = tostring(base + bit_i)
                end
            end
        end
        _ow_emit_homepoints(idxs)
    end)
end

-- ── Survival Guide attunement listener ────────────────────────────────────
-- Same shape as the Home Point listener above, but a different set of
-- Menu IDs (8500/8501) identifies the Survival Guide NPCs, and the
-- master list is a flat 0..N list keyed by visit-order index rather
-- than zone+number pairs. The bitfield layout in Menu Parameters is
-- assumed to mirror Home Points (4-byte leading metadata, then four
-- little-endian uint32s) — verified-by-default-and-fixed-if-wrong via
-- the //ow sgdebug toggle which dumps full packet bytes.
--
-- Emit format: SURVIVAL_GUIDES|i1,i2,...
-- Python REPLACES the auto set on each emit (each packet carries the
-- full attunement state).
do
    local OW_SG_MENU_IDS = {
        [8500] = true,
        [8501] = true,
    }

    local _sg_log_file = nil
    local function _ow_sg_filelog(line)
        if not _G._ow_sg_debug then return end
        if not _sg_log_file then
            local path
            local appdata = os.getenv('APPDATA')
            if appdata and appdata ~= '' then
                appdata = appdata:gsub('\\', '/')
                path = appdata .. '/OmniWatch/sgdebug_log.txt'
            else
                local base = windower.addon_path or ''
                if base ~= '' and base:sub(-1) ~= '/'
                                and base:sub(-1) ~= '\\' then
                    base = base .. '/'
                end
                path = base .. 'data/sgdebug_log.txt'
            end
            local f, err = io.open(path, 'a')
            if not f then
                ow_chat(123,
                    '[OW SG] file open failed (' .. tostring(err)
                    .. '). File log disabled.')
                return
            end
            _sg_log_file = f
            local now = os.date('*t')
            f:write(string.format(
                '\n=== SG debug trace started %04d-%02d-%02d %02d:%02d:%02d ===\n',
                now.year, now.month, now.day,
                now.hour, now.min, now.sec))
        end
        _sg_log_file:write(line)
        _sg_log_file:write('\n')
        _sg_log_file:flush()
    end

    local function _ow_sg_log(fmt, ...)
        if _G._ow_sg_debug then
            local line = string.format('[OW SG] ' .. fmt, ...)
            ow_chat(207, line)
            _ow_sg_filelog(line)
        end
    end

    local function _ow_sg_dump_bytes(label, s)
        if not _G._ow_sg_debug or not s then return end
        local hex = {}
        for i = 1, #s do
            hex[i] = string.format('%02X', s:byte(i))
        end
        _ow_sg_filelog(string.format('%s (%d bytes):', label, #s))
        for row_start = 1, #hex, 16 do
            local row_end = math.min(row_start + 15, #hex)
            local row = {}
            for i = row_start, row_end do
                row[#row + 1] = hex[i]
            end
            _ow_sg_filelog(string.format('  %04X  %s',
                row_start - 1, table.concat(row, ' ')))
        end
    end

    local function _ow_emit_survival_guides(idxs)
        local sock = _G._ow_udp_inv
        if not sock then
            _ow_sg_log('emit FAILED: _G._ow_udp_inv not bound yet')
            return
        end
        local payload = 'SURVIVAL_GUIDES|' .. table.concat(idxs, ',')
        local sent_ok, sent_err = pcall(function() sock:send(payload) end)
        if not sent_ok then
            _ow_sg_log('UDP send FAILED: %s', tostring(sent_err))
        else
            _ow_sg_log('emitted %d indices', #idxs)
        end
    end

    ow_safe_register('incoming chunk', function(id, data)
        if id ~= 0x032 and id ~= 0x034 then return end
        local ok, parsed = pcall(packets.parse, 'incoming', data)
        if not ok or type(parsed) ~= 'table' then return end
        local menu_id = tonumber(parsed['Menu ID'])
        if not menu_id or not OW_SG_MENU_IDS[menu_id] then return end

        -- Past this point we know it's an SG NPC. Log everything when
        -- debug is on; otherwise stay quiet.
        _ow_sg_log('saw 0x%03X packet for SG NPC, Menu ID %d, %d bytes',
            id, menu_id, #data)
        _ow_sg_dump_bytes(string.format('raw 0x%03X', id), data)

        if _G._ow_sg_debug then
            local field_names = {}
            for k, _v in pairs(parsed) do
                field_names[#field_names + 1] = tostring(k)
            end
            table.sort(field_names)
            _ow_sg_log('parsed fields: %s', table.concat(field_names, ', '))
            for _, k in ipairs(field_names) do
                local v = parsed[k]
                if type(v) == 'string' then
                    _ow_sg_dump_bytes(string.format('  field %q', k), v)
                elseif type(v) == 'number' then
                    _ow_sg_filelog(string.format(
                        '  field %q = %s (0x%X)',
                        k, tostring(v), v))
                end
            end
        end

        local params = parsed['Menu Parameters']
        if type(params) ~= 'string' or #params < 20 then
            _ow_sg_log('Menu Parameters too short or missing (got %s, %d bytes)',
                type(params), params and #params or 0)
            return
        end

        local function u32_le(s, off)
            local b1, b2, b3, b4 = s:byte(off, off + 3)
            if not b1 then return 0 end
            return b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
        end
        -- Survival Guide bitfield layout is DIFFERENT from Home Points.
        -- Verified from a real packet capture:
        --   Menu Parameters bytes 0-3:   00 00 00 00     leading zero
        --   Menu Parameters bytes 4-11:  XX XX XX XX     8 bytes of menu
        --                                XX XX XX XX     metadata / pose
        --   Menu Parameters bytes 12-15: <set 0>         indices 0..31
        --   Menu Parameters bytes 16-19: <set 1>         indices 32..63
        --   Menu Parameters bytes 20-23: <set 2>         indices 64..95
        --   Menu Parameters bytes 24-27: <set 3>         indices 96..127
        --   Menu Parameters bytes 28-31: trailing flags
        --
        -- Reading at offset 4 (the HP layout) yielded indices that
        -- didn't match the in-game menu. Reading at offset 12 gave
        -- Set 3 = 0x00000001 (only bit 0 set = index 96 only) — the
        -- canonical clean trailing-padding pattern for a player who's
        -- attuned through the lower-numbered indices but not the
        -- last one (Eastern Adoulin). 98 entries in the master list
        -- means valid bits run 0..97; any bit 98+ being set would be
        -- spurious. The offset-12 read produced no spurious high bits.
        --
        -- Lua strings are 1-indexed, so byte offset 12 = string offset 13.
        local sets = {
            u32_le(params, 13),  -- SGs 0..31
            u32_le(params, 17),  -- SGs 32..63
            u32_le(params, 21),  -- SGs 64..95
            u32_le(params, 25),  -- SGs 96..127
        }
        _ow_sg_log('Sets: 0x%08X 0x%08X 0x%08X 0x%08X',
            sets[1], sets[2], sets[3], sets[4])

        local idxs = {}
        for set_i = 1, 4 do
            local v = sets[set_i]
            local base = (set_i - 1) * 32
            for bit_i = 0, 31 do
                if (math.floor(v / (2 ^ bit_i)) % 2) == 1 then
                    idxs[#idxs + 1] = tostring(base + bit_i)
                end
            end
        end
        _ow_emit_survival_guides(idxs)
    end)
end

-- ── Inventory snapshot builder + sender ──────────────────────────────────
-- Walks all bags, looks each item up in res.items, and emits per-slot
-- packets containing items the current main job can equip in that slot.
-- Used by the sim window's gear dropdowns.
--
-- Throttled: only sends when sim is active AND inventory has changed
-- (or sim was just turned on). _ow_inv_snap_dirty is flipped to true on
-- any windower 'incoming chunk' that affects inventory (0x01D, 0x01E,
-- 0x01F, 0x020) plus on logout/zone-change. Drained by prerender.

-- Slot order matches python's SIM_GEAR_SLOTS exactly. The bit value is
-- res.slots:with('en', name).id.
local _OW_SIM_SLOT_KEYS = {
    'main', 'sub', 'range', 'ammo',
    'head', 'neck', 'left_ear', 'right_ear',
    'body', 'hands', 'left_ring', 'right_ring',
    'back', 'waist', 'legs', 'feet',
}

-- Lazy-built lookups. Populated on first send; stable across the addon
-- lifetime. The reverse maps avoid an O(slots) scan per item check.
local _OW_SLOT_NAME_TO_ID = nil   -- 'main' → bit number
local _OW_JOB_NAME_TO_ID  = nil   -- 'NIN'  → bit number

function _ow_build_sim_lookups()
    if _OW_SLOT_NAME_TO_ID and _OW_JOB_NAME_TO_ID then return end
    _OW_SLOT_NAME_TO_ID = {}
    _OW_JOB_NAME_TO_ID  = {}
    if res and res.slots then
        for id, s in pairs(res.slots) do
            if s.en then _OW_SLOT_NAME_TO_ID[s.en:lower()] = id end
        end
        -- Map our underscore-style python slot keys to windower's
        -- with-space slot names. Windower uses 'left ear', 'right ear',
        -- 'left ring', 'right ring' (with space), and 'main' / 'sub' /
        -- 'range' / 'ammo' / 'head' / 'neck' / 'body' / 'hands' / 'legs'
        -- / 'feet' / 'back' / 'waist'.
        local aliases = {
            left_ear  = 'left ear',
            right_ear = 'right ear',
            left_ring = 'left ring',
            right_ring = 'right ring',
        }
        for py_key, win_key in pairs(aliases) do
            local id = _OW_SLOT_NAME_TO_ID[win_key]
            if id then _OW_SLOT_NAME_TO_ID[py_key] = id end
        end
    end
    if res and res.jobs then
        for id, j in pairs(res.jobs) do
            if j.ens then _OW_JOB_NAME_TO_ID[j.ens] = id end
        end
    end
end

-- Build the snapshot and send it. Heavy work — only call when actually
-- needed (sim toggled on, or inventory dirty + sim still on).
local _ow_inv_snap_dirty = true   -- prime: send on first sim activation
local _ow_inv_snap_last_sent = 0  -- guards against multi-send per second

-- Reverse lookup: item id → {bag = bag_id, idx = slot_idx}. Used by
-- the sim compute path to resolve sim'd item ids to a (bag, slot_idx)
-- pair so windower.ffxi.get_items(bag, idx) returns full item_data.
-- Without this cache, the compute would walk every bag every tick to
-- find sim'd items (16 slots × 12 bags × ~80 slots = ~15k lookups per
-- 100ms), which causes a noticeable delay between picking gear in the
-- sim window and the stats panel updating.
--
-- Invalidated whenever inventory changes (same packet ids that mark
-- _ow_inv_snap_dirty: 0x01D-0x020). Rebuilt on next access.
local _ow_inv_id_to_loc = nil  -- nil = needs rebuild

function _ow_rebuild_id_to_loc()
    local map = {}
    if res and res.bags then
        for _, bag in pairs(res.bags) do
            local bag_items = windower.ffxi.get_items(bag.id)
            if bag_items then
                for slot_idx, it in pairs(bag_items) do
                    if type(it) == 'table' and it.id and it.id > 0 then
                        -- Multiple bags may have the same item id; first
                        -- found wins. The compute doesn't care which
                        -- specific copy it reads since the underlying
                        -- res.items[id] data is identical for non-augmented
                        -- gear, and augmented gear's extdata is per-slot
                        -- so we'd need a smarter lookup either way.
                        if not map[it.id] then
                            map[it.id] = {bag = bag.id, idx = slot_idx}
                        end
                    end
                end
            end
        end
    end
    _ow_inv_id_to_loc = map
end

-- Public: get (bag, idx) for an item id, or nil if not in any bag.
-- Caller is the sim compute path. Builds the cache lazily on first
-- call and after inventory changes.
function _ow_get_item_loc(iid)
    if _ow_inv_id_to_loc == nil then
        _ow_rebuild_id_to_loc()
    end
    return _ow_inv_id_to_loc and _ow_inv_id_to_loc[iid] or nil
end

-- Resolve a sim equipment reference into (bag, idx) for the gear scan.
-- The reference can be:
--   - integer 0      → empty slot
--   - integer N      → item id; resolves to ANY copy in bags (legacy)
--   - {id, bag, idx} → exact instance; verify the slot still holds the
--                       expected id, fall back to id-scan if it moved.
-- Returns (bag, idx) or nil if not found.
function _ow_resolve_sim_equip(ref)
    if type(ref) == 'number' then
        if ref <= 0 then return nil end
        local loc = _ow_get_item_loc(ref)
        return loc and loc.bag or nil, loc and loc.idx or nil
    end
    if type(ref) ~= 'table' then return nil end
    local want_id = tonumber(ref.id) or 0
    if want_id <= 0 then return nil end
    local bag = tonumber(ref.bag) or 0
    local idx = tonumber(ref.idx) or 0
    -- Verify the cached slot still holds the right item id.
    if bag > 0 and idx > 0 then
        local cur = windower.ffxi.get_items(bag, idx)
        if cur and cur.id == want_id then
            return bag, idx
        end
    end
    -- Cached slot is stale. Scan all bags for a copy of want_id with
    -- matching augment fingerprint. We don't have the fingerprint
    -- from the ref directly (sim only stored bag/idx); fall back to
    -- "any copy of this id" — better to find SOME instance than none.
    -- Future improvement: ref.fp would let us pick the exact copy.
    local loc = _ow_get_item_loc(want_id)
    return loc and loc.bag or nil, loc and loc.idx or nil
end

-- Build the static (per-item-id) tooltip card for the sim's gear-
-- selection tooltips: item level, equip level, jobs string, and the
-- description-derived stat lines. These depend only on the item id (not
-- on the specific augmented copy), so the sim sends them once per unique
-- id (deduped) rather than per inventory entry — augments, which DO vary
-- per copy, ride a separate AUG stream. Mirrors the equip_rich field
-- derivation so non-equipped tooltips match the live equipment panel.
-- Returns ilvl, lvl, jobs, stat_lines (or nil if the id is unknown).
function _ow_sim_item_card(item_id)
    local resource = res.items and res.items[item_id]
    if not resource then return nil end
    local ilvl = tonumber(resource.item_level) or 0
    local lvl  = tonumber(resource.level) or 0
    local jobs = ''
    if type(resource.jobs) == 'table' then
        local jlist = {}
        for k, v in pairs(resource.jobs) do
            local jid = (type(k) == 'number' and v == true) and k
                     or (type(v) == 'number' and v) or nil
            if jid and res.jobs and res.jobs[jid] then
                jlist[#jlist + 1] = res.jobs[jid].ens or ''
            end
        end
        jobs = table.concat(jlist, ',')
    end
    local stat_lines = {}
    local dent  = res.item_descriptions and res.item_descriptions[item_id]
    local dtext = dent and (dent.english or dent.en)
    if dtext and dtext ~= '' then
        for line in dtext:gmatch('[^\r\n]+') do
            local trimmed = line:gsub('^%s+', ''):gsub('%s+$', '')
            if trimmed ~= '' then
                stat_lines[#stat_lines + 1] = trimmed
            end
        end
    end
    return ilvl, lvl, jobs, stat_lines
end

local function _ow_send_sim_inventory()
    if not (_sim and _sim.is_active and _sim.is_active()) then return end
    if not res or not res.items then return end

    _ow_build_sim_lookups()
    local p = windower.ffxi.get_player()
    if not p then return end
    local job = (p.main_job or ''):upper()
    local job_id = _OW_JOB_NAME_TO_ID[job]

    -- Walk every bag/slot. We do NOT dedupe by id anymore — augmented
    -- items with the same id (e.g. multiple Camulus's Mantles) need to
    -- appear as separate entries. Each entry carries the (bag, idx)
    -- location so the sim can resolve back to the exact item with its
    -- augments.
    --
    -- IMPORTANT: windower.ffxi.get_items(bag_id) returns a table with
    -- numeric slot indices (1..N) but ALSO metadata fields (count, max,
    -- enabled). Use pairs (not ipairs) so we don't stop at the first
    -- empty slot — items are in arbitrary slots, not packed at 1..N.
    -- Skip non-table entries (the metadata fields).
    local pool = {}    -- list of {id, name, slots, jobs, bag, idx, tag, fp}
    if res.bags then
        for _, bag in pairs(res.bags) do
            local bag_items = windower.ffxi.get_items(bag.id)
            if bag_items then
                for slot_idx, it in pairs(bag_items) do
                    if type(it) == 'table' and it.id and it.id > 0
                       and type(slot_idx) == 'number' then
                        local meta = res.items[it.id]
                        if meta and meta.slots and meta.jobs then
                            local en = meta.en or meta.enl or ('item:' .. it.id)
                            -- Augments: read via extdata, build tag + fingerprint
                            local augs = ow_get_item_augments(bag.id, slot_idx)
                            local tag  = augs and ow_augment_tag(augs) or ''
                            local fp   = augs and ow_augment_fingerprint(augs) or ''
                            table.insert(pool, {
                                id = it.id, name = en,
                                slots = meta.slots, jobs = meta.jobs,
                                bag = bag.id, idx = slot_idx,
                                tag = tag, fp = fp, augs = augs,
                            })
                        end
                    end
                end
            end
        end
    end

    -- Emit MAIN_JOB header.
    local ok, err = pcall(function()
        udp_inv:send('SIM_INV|MAIN_JOB|' .. job)
    end)
    if not ok then
        ow_chat(123, '[OmniWatch] sim inv send failed: ' .. tostring(err))
        return
    end

    -- For each slot, build semicolon-separated list of entries.
    -- Format per entry: <id>@<bag>:<idx>:<tag>:<name>
    --   - id, bag, idx are integers
    --   - tag is the short augment summary (e.g. "DEX/Acc/WSD") or empty
    --   - name is the item's English display name
    -- Encoding caveats:
    --   - Item names CAN contain commas/semicolons/colons in rare cases.
    --     Replace ; with ',' and : with '_' (lossy but rare and harmless
    --     for display).
    --   - Augment tag uses '/' as inner separator which is safe.
    -- Multiple instances of the same item id appear as separate entries
    -- with different (bag, idx) — augmented capes show up once per copy.
    for _, slot_key in ipairs(_OW_SIM_SLOT_KEYS) do
        local slot_id = _OW_SLOT_NAME_TO_ID[slot_key]
        if slot_id then
            local parts = {}
            for _, item in ipairs(pool) do
                if item.slots[slot_id] and (not job_id or item.jobs[job_id]) then
                    local safe_name = item.name:gsub(';', ','):gsub(':', '_')
                    local safe_tag  = (item.tag or ''):gsub(';', ','):gsub(':', '_')
                    table.insert(parts, string.format('%d@%d:%d:%s:%s',
                        item.id, item.bag, item.idx, safe_tag, safe_name))
                end
            end
            -- Send even when empty so python knows we considered the
            -- slot (vs. left it stale from a previous job/snapshot).
            local body = 'SIM_INV|SLOT|' .. slot_key .. '|' .. table.concat(parts, ';')
            -- UDP packets can't exceed ~64KB but slots typically have
            -- <100 items, so this is fine. If a freak edge case ever
            -- hits the limit, we'd switch to chunked sends.
            pcall(function() udp_inv:send(body) end)
        end
    end

    -- ── Rich tooltip data for non-equipped items ──────────────────────
    -- The SLOT stream above carries only id/bag/idx/short-tag/name, which
    -- makes the gear-selection tooltips thin next to the live equipment
    -- panel. Two extra streams fill them out to full cards:
    --   CARD : per UNIQUE item id — item level, equip level, jobs, and the
    --          description-derived stat lines (static per id, deduped).
    --   AUG  : per augmented COPY — the full augment line list (varies by
    --          (bag, idx); only sent for copies that actually have augs).
    -- Records are packed many-per-packet, separated by \x1e, with fields
    -- inside a record separated by \x1f. Neither byte appears in item
    -- text, so this needs no escaping and the whole snapshot stays a
    -- handful of packets. Each packet is flushed well under python's
    -- 16 KB recv buffer.
    local RS = string.char(30)   -- record separator (between cards/copies)
    local US = string.char(31)   -- unit separator (between fields)
    local MAX_PKT = 12000        -- flush threshold, safely under 16 KB

    -- CARD stream: one record per unique id in the pool.
    do
        local seen_id = {}
        local recs, buf_len = {}, 0
        local function flush()
            if #recs > 0 then
                local payload = 'SIM_INV|CARD|' .. table.concat(recs, RS)
                pcall(function() udp_inv:send(payload) end)
                recs, buf_len = {}, 0
            end
        end
        for _, item in ipairs(pool) do
            if not seen_id[item.id] then
                seen_id[item.id] = true
                local ilvl, lvl, jobs, stat_lines = _ow_sim_item_card(item.id)
                if ilvl then
                    local fields = { tostring(item.id), tostring(ilvl),
                                     tostring(lvl), jobs }
                    for _, sl in ipairs(stat_lines) do
                        fields[#fields + 1] = sl
                    end
                    local rec = table.concat(fields, US)
                    if buf_len + #rec + 1 > MAX_PKT then flush() end
                    recs[#recs + 1] = rec
                    buf_len = buf_len + #rec + 1
                end
            end
        end
        flush()
    end

    -- AUG stream: one record per augmented copy. Augment strings are the
    -- same ones the short tag is built from (already extdata-decoded
    -- above), with any leading marker glyph stripped. "Path: A"-style
    -- opaque augments are resolved to their real stat lines using the
    -- same tables the live equipment panel uses (ow_path_augments for
    -- REMA / Dynamis-D weapons, Unity_rank for Unity Concord gear,
    -- ow_unity_augments for JSE necks), so non-equipped tooltips show
    -- the actual stats instead of a bare path letter. Unresolved paths
    -- fall through as the raw "Path: A" string.
    do
        local recs, buf_len = {}, 0
        local function flush()
            if #recs > 0 then
                local payload = 'SIM_INV|AUG|' .. table.concat(recs, RS)
                pcall(function() udp_inv:send(payload) end)
                recs, buf_len = {}, 0
            end
        end
        -- Resolve a single cleaned augment string to one-or-more real
        -- lines (mirrors the equip_rich path-resolution).
        local function resolve_aug(item_id, s)
            local pkey = s:lower():match('^(path:%s*%a)')
            if not pkey then return { s } end
            local nkey = pkey:gsub('%s+', ' ')
            local resolved = ow_path_augments[item_id]
                             and ow_path_augments[item_id][nkey]
            if not resolved and Unity_rank and Unity_rank[item_id]
                    and type(Unity_rank[item_id].augments) == 'table' then
                resolved = Unity_rank[item_id].augments
            end
            if not resolved and type(ow_unity_augments[item_id]) == 'table' then
                resolved = ow_unity_augments[item_id]
            end
            if type(resolved) == 'table' and #resolved > 0 then
                local out = {}
                for _, rs in ipairs(resolved) do
                    if rs and rs ~= '' then out[#out + 1] = tostring(rs) end
                end
                if #out > 0 then return out end
            end
            return { s }   -- unresolved → keep the raw path
        end
        for _, item in ipairs(pool) do
            local al = item.augs
            if type(al) == 'table' and #al > 0 then
                local fields = { tostring(item.bag), tostring(item.idx) }
                for _, a in ipairs(al) do
                    local s = tostring(a):gsub('^[^%w%+%-]+', '')
                                         :gsub('^%s+', ''):gsub('%s+$', '')
                    if s ~= '' and s ~= 'none' then
                        for _, line in ipairs(resolve_aug(item.id, s)) do
                            if line ~= '' then fields[#fields + 1] = line end
                        end
                    end
                end
                if #fields > 2 then
                    local rec = table.concat(fields, US)
                    if buf_len + #rec + 1 > MAX_PKT then flush() end
                    recs[#recs + 1] = rec
                    buf_len = buf_len + #rec + 1
                end
            end
        end
        flush()
    end

    -- sim_state["equipment"] when sim activates, so the sim dropdowns
    -- start with the live-equipped items rather than empty. Format:
    --   SIM_INV|EQUIPPED|<slot>:<id>@<bag>:<idx>;<slot>:<id>@<bag>:<idx>;...
    -- Per slot we now include the exact (bag, idx) so augmented items
    -- equipped at sim-open time resolve to the correct instance.
    do
        local eq = windower.ffxi.get_items and windower.ffxi.get_items('equipment')
        if eq then
            local SLOT_NAMES = {
                'main','sub','range','ammo','head','neck',
                'left_ear','right_ear','body','hands',
                'left_ring','right_ring','back','waist','legs','feet'
            }
            local parts = {}
            for _, sn in ipairs(SLOT_NAMES) do
                local idx = eq[sn]
                local bag = eq[sn .. '_bag']
                local id  = 0
                local b   = 0
                local i   = 0
                if idx and idx ~= 0 and bag then
                    local item = windower.ffxi.get_items(bag, idx)
                    if item and item.id then
                        id = item.id
                        b  = bag
                        i  = idx
                    end
                end
                parts[#parts+1] = string.format('%s:%d@%d:%d', sn, id, b, i)
            end
            local body = 'SIM_INV|EQUIPPED|' .. table.concat(parts, ';')
            pcall(function() udp_inv:send(body) end)
        end
    end

    -- Augment fingerprints per (bag, idx). Lets python resolve nicknames
    -- and the lua-side compute path re-find an item by augment hash if
    -- it's been moved between bags. Format:
    --   SIM_INV|FP|<bag>:<idx>:<id>:<fingerprint>;<bag>:<idx>:<id>:<fp>;...
    -- Only entries with non-empty fingerprints are emitted (plain items
    -- without augments don't need this index).
    do
        local fp_parts = {}
        for _, item in ipairs(pool) do
            if item.fp and item.fp ~= '' then
                -- Encode pipes in the fingerprint as '~' to keep the
                -- line splittable. Augments don't usually contain pipes
                -- so this is harmless; it's a one-way escape since the
                -- fingerprint is opaque (used as a key, never displayed).
                local safe_fp = item.fp:gsub('|', '~')
                fp_parts[#fp_parts+1] = string.format('%d:%d:%d:%s',
                    item.bag, item.idx, item.id, safe_fp)
            end
        end
        if #fp_parts > 0 then
            local body = 'SIM_INV|FP|' .. table.concat(fp_parts, ';')
            pcall(function() udp_inv:send(body) end)
        end
    end

    -- Terminator so python can do an atomic swap.
    pcall(function() udp_inv:send('SIM_INV|END') end)
    _ow_inv_snap_last_sent = os.clock()
end

-- Public hook: flag the snapshot dirty. Called from inventory-change
-- packet handlers and from sim activation. The actual send happens on
-- the next prerender tick (rate-limited to 1 Hz max). Also invalidates
-- the id→(bag,idx) cache used by the sim compute path so a moved or
-- used item resolves to its new location on next stat compute.
function _ow_mark_inv_dirty()
    _ow_inv_snap_dirty = true
    _ow_inv_id_to_loc  = nil
end

-- Force the next inventory snapshot to send immediately, bypassing the
-- 1 Hz rate-limit gate. Used on sim activation and by the sim REFRESH
-- button so the EQUIPPED seed (and tooltip CARD/AUG data) resend on the
-- very next tick instead of waiting up to a second or for the next
-- inventory change — the cause of "sim opened but current gear didn't
-- load until I closed and reopened it."
function _ow_force_inv_resend()
    _ow_inv_snap_last_sent = 0
    _ow_inv_snap_dirty     = true
    _ow_inv_id_to_loc      = nil
end

-- ── BLU Spellsets engine ───────────────────────────────────────────────────
-- Equips a named Blue Magic loadout sent by the overlay's BLU Spellsets
-- panel (BLUSETS|equip rail message below). Preserve-traits algorithm,
-- modeled on the AzureSets addon: first remove equipped spells that are
-- not in the target set (one per step), then fill empty slots with the
-- missing target spells (one per step), with a delay between steps —
-- the client rejects rapid-fire BLU set changes. Each step re-reads the
-- live set, so external changes mid-run are tolerated.
--
-- Globals, not locals: the main chunk is at Lua 5.1's 200-local limit.
_ow_blusets_active = nil   -- { want={id=true}, name=str, tried={id=true} }

function _ow_blusets_step()
    local st = _ow_blusets_active
    if not st then return end
    local p = windower.ffxi.get_player()
    if not p or p.main_job ~= 'BLU' then
        ow_chat(123,
            '[OmniWatch] BLU spellset change aborted - main job is no longer BLU.')
        _ow_blusets_active = nil
        return
    end
    local data = windower.ffxi.get_mjob_data and windower.ffxi.get_mjob_data()
    local raw = (data and data.spells) or {}
    -- Remove phase: clear one equipped spell that isn't in the target
    -- set. pairs(), not ipairs() — the set table goes sparse the moment
    -- a middle slot is removed (same gap bug as the trait reader).
    for slot, sid in pairs(raw) do
        local n_slot = tonumber(slot)
        if n_slot and type(sid) == 'number' and sid ~= 0 and sid ~= 512
                and not st.want[sid] then
            windower.ffxi.remove_blue_magic_spell(n_slot)
            coroutine.schedule(_ow_blusets_step, 0.7)
            return
        end
    end
    -- Add phase: one missing target spell into the first empty slot.
    local have = {}
    for _, sid in pairs(raw) do
        if type(sid) == 'number' then have[sid] = true end
    end
    local empty
    for i = 1, 20 do
        local v = raw[i]
        if v == nil or v == 0 or v == 512 then
            empty = i
            break
        end
    end
    if empty then
        for sid in pairs(st.want) do
            if not have[sid] and not st.tried[sid] then
                -- One attempt per spell: if the client rejects the set
                -- (unlearned, level too low), skip rather than retry
                -- forever; it's reported as skipped at the end.
                st.tried[sid] = true
                windower.ffxi.set_blue_magic_spell(sid, empty)
                coroutine.schedule(_ow_blusets_step, 0.7)
                return
            end
        end
    end
    -- Nothing left to remove or add — done. Report anything attempted
    -- that still isn't equipped.
    local missing = {}
    for sid in pairs(st.want) do
        if not have[sid] then
            local sp = res.spells[sid]
            missing[#missing + 1] = (sp and (sp.english or sp.en))
                                    or ('#' .. tostring(sid))
        end
    end
    if #missing > 0 then
        ow_chat(123, '[OmniWatch] Spellset "' .. st.name
            .. '" set with ' .. #missing .. ' spell(s) skipped: '
            .. table.concat(missing, ', '))
    else
        ow_chat(207, '[OmniWatch] Spellset "' .. st.name
            .. '" equipped.')
    end
    _ow_blusets_active = nil
end

function _ow_blusets_start(setname, names_str)
    if _ow_blusets_active then
        ow_chat(123,
            '[OmniWatch] A BLU spellset change is already running ("'
            .. _ow_blusets_active.name .. '").')
        return
    end
    local p = windower.ffxi.get_player()
    if not p or p.main_job ~= 'BLU' then
        ow_chat(123,
            '[OmniWatch] Cannot equip a spellset - main job is not BLU.')
        return
    end
    -- Resolve names → spell ids via res.spells (BlueMagic only). Saved
    -- sets store names rather than ids so they survive resource-file
    -- renumbering and stay human-readable in the JSON.
    local by_name = {}
    for _, sp in pairs(res.spells) do
        if sp and sp.type == 'BlueMagic' then
            local nm = sp.english or sp.en
            if nm then by_name[nm:lower()] = sp.id end
        end
    end
    local want, unknown, count = {}, {}, 0
    for nm in (tostring(names_str) .. ';'):gmatch('([^;]*);') do
        nm = nm:match('^%s*(.-)%s*$')
        if nm ~= '' then
            local sid = by_name[nm:lower()]
            if sid then
                if not want[sid] then count = count + 1 end
                want[sid] = true
            else
                unknown[#unknown + 1] = nm
            end
        end
    end
    if #unknown > 0 then
        ow_chat(123,
            '[OmniWatch] Unknown spell name(s) skipped: '
            .. table.concat(unknown, ', '))
    end
    if count == 0 then
        ow_chat(123, '[OmniWatch] Spellset "'
            .. tostring(setname) .. '" resolved to no spells - nothing to do.')
        return
    end
    if count > 20 then
        ow_chat(123, '[OmniWatch] Spellset "'
            .. tostring(setname) .. '" has ' .. count
            .. ' spells (max 20). Trim it first.')
        return
    end
    ow_chat(207, '[OmniWatch] Equipping BLU spellset "'
        .. tostring(setname) .. '" (' .. count .. ' spells)...')
    _ow_blusets_active = { want = want, name = tostring(setname), tried = {} }
    _ow_blusets_step()
end

-- ── Call Trust: reconcile the party to a saved trust set ───────────────────
-- The robust approach is modelled on the Trusts addon by from20020516
-- (BSD-licensed): cast each trust with /ma, but PACE off the real `action`
-- event (a trust is only de-queued when its cast-complete packet fires),
-- read the trust LIMIT from key items, skip trusts on recast or unlearned,
-- and RECONCILE — release (/retr) any party trust that isn't in the set so
-- the party ends up matching the set exactly.
--
-- We resolve names against res.spells (type='Trust') for the spell id, so no
-- static roster is vendored and new trusts work automatically. Identity is
-- by spell id (not name), so reconcile is reliable. Names that don't resolve
-- are reported and skipped rather than mis-cast. The wire form is
-- CALLTRUST|<char>|<set name>|<Name;Name;...> (names in call order).
_OW_CALLTRUST_AFTERCAST = 3.0    -- pause after a cast completes, before next
_OW_CALLTRUST_RETR      = 1.25   -- between individual /retr releases
_OW_CALLTRUST_RETRALL   = 3.0    -- after /retr all, before the first call

_ow_calltrust_state = nil
-- { name=str, queue={ {id,english}, ... }, retr={names}, phase='retr'|'cast' }

function _ow_trust_norm(s)
    return (tostring(s or ''):lower():gsub('[^%a%d]', ''))
end

function _ow_trust_name_index()
    -- normalized english name -> { id, english } for every Trust-type spell.
    local idx = {}
    if res and res.spells then
        for sid, sp in pairs(res.spells) do
            if sp and sp.type == 'Trust' then
                local en = sp.english or sp.en
                if en and en ~= '' then
                    idx[_ow_trust_norm(en)] = { id = sp.id or sid, english = en }
                end
            end
        end
    end
    return idx
end

function _ow_trust_resolve(idx, nm)
    -- Exact normalized match first; then a '+uc' fallback so a DB display
    -- name that dropped the "(UC)" suffix still finds the res.spells entry.
    local n = _ow_trust_norm(nm)
    return idx[n] or idx[n .. 'uc']
end

function _ow_calltrust_party_trusts()
    -- list of { name } for trust party members (mob spawn_type 14).
    local out = {}
    local party = windower.ffxi.get_party and windower.ffxi.get_party()
    if party then
        for i = 1, 5 do
            local m = party['p' .. i]
            if m and m.mob and m.mob.spawn_type == 14 and m.name then
                out[#out + 1] = { name = m.name }
            end
        end
    end
    return out
end

function _ow_calltrust_limit()
    -- Trust call cap from key items: Magicite permit = 3, Rhapsody key items
    -- raise it to 4 / 5. Default 5 if key items can't be read (don't wrongly
    -- truncate; the game rejects any genuine over-call harmlessly).
    local limit = 0
    local ok, kis = pcall(windower.ffxi.get_key_items)
    if ok and type(kis) == 'table' then
        for _, v in pairs(kis) do
            if v == 2886 then limit = math.max(limit, 5)
            elseif v == 2884 then limit = math.max(limit, 4)
            elseif v == 2497 or v == 2499 or v == 2501 then
                limit = math.max(limit, 3)
            end
        end
    end
    if limit == 0 then limit = 5 end
    return limit
end

function _ow_calltrust_finish(word)
    local st = _ow_calltrust_state
    if st then
        ow_chat(207, '[OmniWatch] Trust set "'
            .. tostring(st.name) .. '" ' .. (word or 'done') .. '.')
    end
    _ow_calltrust_state = nil
end

function _ow_calltrust_cast()
    local st = _ow_calltrust_state
    if not st or st.phase ~= 'cast' then return end
    local q = st.queue
    if not q or #q == 0 then return end
    local nm = q[1].english
    local cast_name = nm
    if windower.to_shift_jis then
        local ok, s = pcall(windower.to_shift_jis, nm)
        if ok and s then cast_name = s end
    end
    windower.send_command('input /ma "' .. cast_name .. '" <me>')
    if _ow_cast_debug then
        ow_chat(207, '[OW] calltrust /ma "' .. nm .. '"')
    end
end

function _ow_calltrust_retr_step()
    local st = _ow_calltrust_state
    if not st or st.phase ~= 'retr' then return end
    local r = st.retr
    if r and #r > 0 then
        local nm = table.remove(r, 1)
        windower.send_command('input /retr ' .. nm)
        if _ow_cast_debug then
            ow_chat(207, '[OW] calltrust /retr ' .. nm)
        end
        coroutine.schedule(_ow_calltrust_retr_step, _OW_CALLTRUST_RETR)
    else
        st.phase = 'cast'
        if #st.queue > 0 then
            coroutine.schedule(_ow_calltrust_cast, _OW_CALLTRUST_RETR)
        else
            _ow_calltrust_finish('reconciled')
        end
    end
end

function _ow_calltrust_start(setname, names_str)
    if _ow_calltrust_state then
        ow_chat(123,
            '[OmniWatch] A trust call is already running.')
        return
    end
    local p = windower.ffxi.get_player and windower.ffxi.get_player()
    if not p then return end
    local idx = _ow_trust_name_index()
    local limit = _ow_calltrust_limit()
    local learned, recasts = nil, nil
    pcall(function() learned = windower.ffxi.get_spells() end)
    pcall(function() recasts = windower.ffxi.get_spell_recasts() end)

    -- Resolve the set's names → trust records, in call order, capped to limit.
    local desired, desired_ids, unknown = {}, {}, {}
    for nm in (tostring(names_str) .. ';'):gmatch('([^;]*);') do
        nm = nm:match('^%s*(.-)%s*$')
        if nm and nm ~= '' and #desired < limit then
            local rec = _ow_trust_resolve(idx, nm)
            if rec then
                desired[#desired + 1] = rec
                desired_ids[rec.id] = true
            else
                unknown[#unknown + 1] = nm
            end
        end
    end
    if #unknown > 0 then
        ow_chat(207, '[OmniWatch] Unknown trust(s) skipped: '
            .. table.concat(unknown, ', '))
    end
    if #desired == 0 then
        ow_chat(123, '[OmniWatch] Trust set "'
            .. tostring(setname) .. '" resolved to no trusts.')
        return
    end

    -- Reconcile: identify present trusts (by resolved spell id). Release the
    -- ones not in the set; keep the ones that are. Unresolvable present
    -- trusts are left alone (we can't safely identify them).
    local present = _ow_calltrust_party_trusts()
    local present_ids, retr = {}, {}
    for _, t in ipairs(present) do
        local rec = _ow_trust_resolve(idx, t.name)
        if rec then
            present_ids[rec.id] = true
            if not desired_ids[rec.id] then
                retr[#retr + 1] = t.name
            end
        end
    end

    -- Build the cast queue: desired trusts not already present, that are
    -- learned and off recast.
    local queue, skipped = {}, {}
    for _, rec in ipairs(desired) do
        if not present_ids[rec.id] then
            if learned and learned[rec.id] == false then
                skipped[#skipped + 1] = rec.english .. ' (not unlocked)'
            elseif recasts and (recasts[rec.id] or 0) > 0 then
                local secs = math.floor((recasts[rec.id] or 0) / 60)
                skipped[#skipped + 1] = rec.english .. ' (' .. secs .. 's)'
            else
                queue[#queue + 1] = rec
            end
        end
    end
    if #skipped > 0 then
        ow_chat(207, '[OmniWatch] Skipped: '
            .. table.concat(skipped, ', '))
    end

    _ow_calltrust_state = { name = tostring(setname), queue = queue,
                            retr = retr, phase = 'retr' }
    ow_chat(207, '[OmniWatch] Trust set "' .. tostring(setname)
        .. '": releasing ' .. #retr .. ', calling ' .. #queue .. '...')

    -- Release phase. If EVERY present trust is being released, use the single
    -- '/retr all'; otherwise release the unwanted ones one at a time so the
    -- wanted present trusts survive.
    if #retr > 0 and #retr == #present then
        windower.send_command('input /retr all')
        if _ow_cast_debug then
            ow_chat(207, '[OW] calltrust /retr all')
        end
        coroutine.schedule(function()
            local st = _ow_calltrust_state
            if not st then return end
            st.phase = 'cast'
            if #st.queue > 0 then
                _ow_calltrust_cast()
            else
                _ow_calltrust_finish('reconciled')
            end
        end, _OW_CALLTRUST_RETRALL)
    elseif #retr > 0 then
        _ow_calltrust_retr_step()
    else
        _ow_calltrust_state.phase = 'cast'
        if #queue > 0 then
            coroutine.schedule(_ow_calltrust_cast, 0.1)
        else
            _ow_calltrust_finish('already matches')
        end
    end
end

-- Cast pacing: de-queue a trust only when its cast actually completes, then
-- schedule the next call. Mirrors the Trusts addon's action conditions
-- (category 4 + matching spell id = done; category 8 / param 28787 with the
-- matching sub-param = interrupted/charging, so retry the same head).
windower.register_event('action', function(act)
    local st = _ow_calltrust_state
    if not st or st.phase ~= 'cast' then return end
    if not act or not act.actor_id then return end
    local p = windower.ffxi.get_player and windower.ffxi.get_player()
    if not p or act.actor_id ~= p.id then return end
    local q = st.queue
    if not q or #q == 0 then return end
    local head = q[1]
    if act.category == 4 and act.param == head.id then
        table.remove(q, 1)
        if #q > 0 then
            coroutine.schedule(_ow_calltrust_cast, _OW_CALLTRUST_AFTERCAST)
        else
            _ow_calltrust_finish('called')
        end
    elseif act.category == 8 and act.param == 28787
            and act.targets and act.targets[1]
            and act.targets[1].actions and act.targets[1].actions[1]
            and act.targets[1].actions[1].param == head.id then
        coroutine.schedule(_ow_calltrust_cast, _OW_CALLTRUST_AFTERCAST)
    end
end)

-- ── Inbound command socket (port 5011) ─────────────────────────────────────
-- Listens for python→lua messages. Drained on every prerender by
-- _ow_drain_inbound(). Three message families share this socket, all
-- pipe-encoded ASCII:
--
--   SIM_MODE|on               → _sim.set_active(true)
--   SIM_MODE|off              → _sim.set_active(false)
--   SIM|<key>|<value>         → _sim.set_value(key, value)
--   SIM|<key>|<value>|<sub>   → _sim.set_value(key, value, sub)
--   SIM|reset                 → _sim.set_value('reset', nil)
--   SETTING|<key>|<value>     → reserved for future schema-pushed settings
--
-- Bind is best-effort: if another instance is already listening, we
-- skip and log. The Sim panel and inbound features will silently no-op
-- in that case but the rest of OmniWatch keeps working.
local udp_cmd_in = nil
do
    local s = socket.udp()
    s:settimeout(0)    -- non-blocking; receive returns nil immediately if empty
    -- Bind an OS-assigned (ephemeral) port instead of fixed 5011 so a machine
    -- with 5011 reserved (WinNAT/Hyper-V/WSL/Docker) can't break inbound
    -- commands. Publish the actual port for the overlay to read.
    local ok_bind, err_bind = s:setsockname("127.0.0.1", 0)
    if ok_bind then
        udp_cmd_in = s
        local _, actual = s:getsockname()
        if actual then ow_write_lua_cmd_port(tonumber(actual)) end
    else
        ow_chat(123,
            '[OmniWatch] could not bind inbound command socket: ' .. tostring(err_bind))
    end
end

-- ── Inventory actions (overlay right-click menu) ───────────────────────────
-- Backing helpers for the INVACT messages the pygame overlay sends when
-- the user right-clicks an inventory item. Defined before the drain so
-- they're in scope as upvalues.

-- Drop the entire stack of <item_id> from the player's MAIN inventory
-- (bag 0). Resolves the slot from live data at call time (so a stale
-- overlay snapshot can't make us drop the wrong slot) and drops the
-- whole count in the first matching, droppable slot. No-op with a chat
-- notice if the item isn't in inventory (e.g. it's in storage/wardrobe,
-- which can't be dropped without moving it first). Destructive — only
-- reached via the deliberate right-click → "Drop item" click.
local function _ow_inv_drop_item_by_id(item_id)
    if not (windower.ffxi and windower.ffxi.get_items
            and windower.ffxi.drop_item) then return end
    local inv = windower.ffxi.get_items(0)   -- bag 0 = Inventory
    if type(inv) ~= 'table' then return end
    local maxslot = tonumber(inv.max) or 80
    for slot = 1, maxslot do
        local it = inv[slot]
        if type(it) == 'table' and it.id == item_id
                and (it.status == 0 or it.status == nil) then
            local cnt = tonumber(it.count) or 1
            windower.ffxi.drop_item(slot, cnt)
            local nm = (res and res.items and res.items[item_id]
                        and (res.items[item_id].name
                             or res.items[item_id].english
                             or res.items[item_id].en))
                       or ('#' .. tostring(item_id))
            ow_chat(207, '[OmniWatch] Dropped ' .. tostring(nm)
                .. (cnt > 1 and (' x' .. cnt) or ''))
            return
        end
    end
    ow_chat(123,
        '[OmniWatch] Drop: that item is not in your main inventory.')
end

-- Add <item_id> to the Treasury addon's per-character Drop list by
-- running its console command with the item's canonical name. Treasury
-- matches by name (wildcard), so we pass the exact resource name. If
-- Treasury's AutoDrop is enabled (the user's normal setup), Treasury
-- also drops any matching items already in inventory immediately. This
-- is the "auto-drop" action: persistent, not a one-shot.
local function _ow_inv_autodrop_by_id(item_id)
    local nm
    if res and res.items and res.items[item_id] then
        nm = res.items[item_id].name
             or res.items[item_id].english
             or res.items[item_id].en
    end
    if not nm or nm == '' then
        ow_chat(123,
            '[OmniWatch] Auto-drop: unknown item id ' .. tostring(item_id))
        return
    end
    -- Treasury console command (addon command, NOT a game slash command,
    -- so no leading '/'): 'tr drop add <name>'. Treasury resolves the
    -- name to item ids and saves it to this character's Drop list.
    windower.send_command('tr drop add ' .. nm)
    ow_chat(207, '[OmniWatch] Auto-drop -> Treasury: ' .. nm)
end

-- Drain helper: pulls all queued packets off udp_cmd_in and routes each
-- to the appropriate handler. Called from the prerender loop. Wrapped
-- in a single pcall so a malformed packet can't kill the addon.
-- ── NPC dialog "continue" arrow support ────────────────────────────────
-- FFXI marks NPC dialog / cutscenes with player status 4 (Event).
-- Polled ~2 Hz from prerender and reported as 'CSSTATE\t1|0'
-- (MB-tagged) over the chat stream; the overlay shows a pulsing
-- continue arrow at the end of the last chat line while the pinned
-- character is in this state. Globals: 200-local limit.
_ow_cs_last_sent = nil
_ow_cs_next_poll = 0
_ow_cs_next_refresh = 0

function _ow_poll_cs_state()
    local now = os.clock()
    if now < _ow_cs_next_poll then return end
    _ow_cs_next_poll = now + 0.5
    local p = windower.ffxi.get_player()
    local on = p ~= nil and p.status == 4
    if on ~= _ow_cs_last_sent or now >= _ow_cs_next_refresh then
        _ow_cs_last_sent = on
        _ow_cs_next_refresh = now + 2.0
        pcall(function()
            udp_chat:send(_OW_MB_TAG('CSSTATE\t' .. (on and '1' or '0')))
        end)
    end
end

-- ════════════════════════════════════════════════════════════════════
--  AutoRA — automated ranged attack  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Ported from AutoRA v3.0.0 (Banggugyangu). While ON, re-fires /shoot on
-- the current target after each ranged-attack action resolves, as long as
-- you're Engaged; halts automatically at 1000 TP. Driven entirely by the
-- hidden Developer settings toggle: Python pushes
-- SETTING|autora_enabled|true/false (see the SETTING handler in the
-- inbound drain), which calls _ow_autora_start / _ow_autora_stop. Acts
-- only on your own character. Globals (not locals) to stay clear of the
-- 200-local chunk cap.
_ow_autora_on        = false
_ow_autora_halt_tp   = true     -- stop automatically when TP >= stop_tp
_ow_autora_stop_tp   = 1000     -- TP threshold to halt at (1000..3000)
_ow_autora_delay     = 1.5      -- seconds between shots (after each RA)
_ow_autora_player_id = nil

function _ow_autora_shoot()
    windower.send_command('input /shoot <t>')
end

function _ow_autora_check()
    if not _ow_autora_on then return end
    local player = windower.ffxi.get_player()
    if not player or not player.target_index then return end
    if _ow_autora_halt_tp and player.vitals
            and player.vitals.tp >= _ow_autora_stop_tp then
        _ow_autora_on = false
        ow_chat(17, '[OmniWatch] AutoRA halted at '
            .. _ow_autora_stop_tp .. ' TP')
        return
    end
    if player.status == 1 then          -- 1 = Engaged
        _ow_autora_shoot()
    end
end

function _ow_autora_start()
    if _ow_autora_on then return end
    local player = windower.ffxi.get_player()
    _ow_autora_player_id = (player and player.id) or _ow_autora_player_id
    _ow_autora_on = true
    ow_chat(17, '[OmniWatch] AutoRA ON')
    _ow_autora_shoot()
end

function _ow_autora_stop()
    if not _ow_autora_on then return end
    _ow_autora_on = false
    ow_chat(17, '[OmniWatch] AutoRA OFF')
end

-- After one of OUR ranged attacks resolves (category 2), queue the next
-- shot. coroutine.schedule is OmniWatch's native delay primitive (no
-- dependency on the functions-lib :schedule method the original used).
ow_safe_register('action', function(act)
    if not _ow_autora_on then return end
    if not act or act.category ~= 2 then return end
    local pid = _ow_autora_player_id
    if not pid then
        local p = windower.ffxi.get_player()
        pid = p and p.id
        _ow_autora_player_id = pid
    end
    if pid and act.actor_id == pid then
        coroutine.schedule(_ow_autora_check, _ow_autora_delay)
    end
end)

-- ════════════════════════════════════════════════════════════════════
--  AllSeeingEye — reveal hidden entities  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Rewrites incoming 0x0E (NPC Update) packets whose status byte marks an
-- entity the server is hiding (2 dead/corpse, 6 appearing, 7 fading) so
-- the client renders it. Same byte rewrite as AllSeeingEye (Project Tako).
-- Uses a DIRECT register_event (not ow_safe_register): the modified packet
-- is returned to replace the original, and the safe wrapper discards return
-- values. Driven by SETTING|ase_* from the dev-menu box (default off).
_ow_ase_enabled   = false
_ow_ase_dead      = true
_ow_ase_appearing = true
_ow_ase_fading    = true

function _ow_ase_reveal(data)
    if #data < 43 then return nil end
    local status = data:byte(0x21)
    local on = (status == 2 and _ow_ase_dead)
            or (status == 6 and _ow_ase_appearing)
            or (status == 7 and _ow_ase_fading)
    if on then
        return data:sub(1, 32) .. '0' .. data:sub(34, 34)
               .. '0' .. data:sub(36, 41) .. '0' .. data:sub(43)
    end
    return nil
end

windower.register_event('incoming chunk', function(id, data)
    if id ~= 0x0E or not _ow_ase_enabled then return end
    local ok, res = pcall(_ow_ase_reveal, data)
    if ok then return res end
end)

-- ════════════════════════════════════════════════════════════════════
--  Scan Zone — packet scan  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Live half of ScanZone: inject an outgoing 0x16 entity-update request
-- for a target index, read the 0x0E reply, and forward the entity's
-- id / name / position / HP% / status to the overlay panel (SZSCAN| on
-- the gs channel). Driven by SCANZONE|scan|<index> from the overlay
-- (see the inbound drain). Ported from ScanZone (Project Tako); the
-- 0x0E field offsets are unchanged. Globals (not locals) to stay clear
-- of the 200-local chunk cap.
_ow_sz_scanning   = false
_ow_sz_scan_index = -1

function _ow_sz_hasbit(mask, b)     -- mask: unsigned byte; b: 1 / 4 / 8 ...
    return (math.floor((mask or 0) / b) % 2) == 1
end

function _ow_sz_u32(data, p)        -- read unsigned 32-bit LE at 1-indexed p
    local b1 = data:byte(p)     or 0
    local b2 = data:byte(p + 1) or 0
    local b3 = data:byte(p + 2) or 0
    local b4 = data:byte(p + 3) or 0
    return b1 + b2 * 256 + b3 * 65536 + b4 * 16777216
end

function _ow_scanzone_scan(index)
    index = tonumber(index)
    if not index then return end
    _ow_sz_scan_index = index
    _ow_sz_scanning   = true
    local lo = index % 256
    local hi = math.floor(index / 256)
    pcall(function()
        windower.packets.inject_outgoing(0x16,
            string.char(0x16, 0x08, 0x00, 0x00, lo, hi, 0x00, 0x00))
    end)
end

ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x0E then return end
    if not _ow_sz_scanning then return end
    local tindex = data:unpack('h', 0x08 + 1)
    if tindex ~= _ow_sz_scan_index then return end
    _ow_sz_scanning   = false
    _ow_sz_scan_index = -1

    local mask = data:byte(0x0A + 1) or 0
    local sid  = _ow_sz_u32(data, 0x04 + 1)
    local nm   = ''
    local x, y, z, hpp, status = nil, nil, nil, nil, nil

    if _ow_sz_hasbit(mask, 8) then              -- name present
        local maxn = #data - 0x34
        for i = 1, maxn do
            local b = data:byte(0x34 + i)
            if not b or b == 0 then break end
            nm = nm .. string.char(b)
        end
    end
    if _ow_sz_hasbit(mask, 1) then              -- position present
        local px, pz, py = data:unpack('fff', 0x0C + 1)
        x, z, y = px, pz, py                     -- packet order X, Z(h), Y
    end
    if _ow_sz_hasbit(mask, 4) then              -- vitals present
        hpp    = data:byte(0x1E + 1)             -- HP%
        status = data:byte(0x1E + 3)             -- status (skip anim byte)
    end

    -- SZSCAN|<index>|<id>|<name>|<x>|<y>|<z>|<hpp>|<status>
    local payload = string.format('SZSCAN|%d|%d|%s|%s|%s|%s|%s|%s',
        tindex, sid, nm,
        x   and string.format('%.1f', x) or '',
        y   and string.format('%.1f', y) or '',
        z   and string.format('%.1f', z) or '',
        hpp and tostring(hpp) or '',
        status and tostring(status) or '')
    if udp_gs then udp_gs:send(payload) end
end)

-- ════════════════════════════════════════════════════════════════════
--  Scan Zone — widescan radar  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Request a widescan (outgoing 0x0F4, Flags=1). The server streams a
-- 0x0F6 Mark Start, one 0x0F4 mob packet per spawned scannable entity
-- (Index/Level/Type/X-Y map offsets/Name), then a 0x0F6 Mark End. We
-- collect the mobs between the marks and stream them to the overlay
-- panel (SZWIDE| on the gs channel) for the radar. Server-authoritative:
-- only returns spawned entities within the char's widescan range.
_ow_sz_wide_capturing = false

function _ow_scanzone_widescan()
    pcall(function()
        local p = packets.new('outgoing', 0x0F4, {['Flags'] = 1})
        packets.inject(p)
    end)
end

ow_safe_register('incoming chunk', function(id, data)
    if id == 0x0F6 then                          -- widescan Mark
        local t = _ow_sz_u32(data, 0x04 + 1)     -- 1 = Start, 2 = End
        if t == 1 then
            _ow_sz_wide_capturing = true
            if udp_gs then udp_gs:send('SZWIDE|start') end
        elseif t == 2 then
            _ow_sz_wide_capturing = false
            if udp_gs then udp_gs:send('SZWIDE|end') end
        end
        return
    end
    if id ~= 0x0F4 then return end               -- widescan Mob
    if not _ow_sz_wide_capturing then return end
    local index = (data:byte(0x04 + 1) or 0)
                  + (data:byte(0x05 + 1) or 0) * 256
    local level = data:byte(0x06 + 1) or 0
    local mtype = data:byte(0x07 + 1) or 0       -- 0 Other / 1 Friendly / 2 Enemy
    local xoff  = data:unpack('h', 0x08 + 1)     -- signed map offsets
    local yoff  = data:unpack('h', 0x0A + 1)
    local nm = ''
    for i = 1, 16 do
        local b = data:byte(0x0C + i)
        if not b or b == 0 then break end
        nm = nm .. string.char(b)
    end
    if udp_gs then
        udp_gs:send(string.format('SZWIDE|m|%d|%d|%d|%d|%d|%s',
            index, mtype, level, xoff, yoff, nm))
    end
end)

-- ════════════════════════════════════════════════════════════════════
--  Scan Zone — track  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Widescan track: inject outgoing 0x0F5 with a target index and the
-- server streams 0x0F5 updates (world X/Z/Y floats, level, index,
-- status) until we send index 0. We forward each update to the overlay
-- (SZTRACK| on the gs channel) so the panel can show a live position +
-- distance. Driven by SCANZONE|track|<index> (0 = stop).
_ow_sz_track_index = 0

function _ow_scanzone_track(index)
    index = tonumber(index) or 0
    _ow_sz_track_index = index
    pcall(function()
        local p = packets.new('outgoing', 0x0F5, {['Index'] = index})
        packets.inject(p)
    end)
end

ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x0F5 then return end
    local x = data:unpack('f', 0x04 + 1)
    local z = data:unpack('f', 0x08 + 1)
    local y = data:unpack('f', 0x0C + 1)
    local level  = data:byte(0x10 + 1) or 0
    local tindex = (data:byte(0x12 + 1) or 0) + (data:byte(0x13 + 1) or 0) * 256
    local status = _ow_sz_u32(data, 0x14 + 1)   -- 1 Update / 2,3 Reset
    if udp_gs then
        udp_gs:send(string.format('SZTRACK|%d|%.1f|%.1f|%.1f|%d|%d',
            tindex, x, y, z, status, level))
    end
end)

-- ════════════════════════════════════════════════════════════════════
--  Scan Zone — live radar  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Player-centred situational radar built from the live mob array (world
-- coords, no calibration). While active we stream a throttled snapshot
-- of nearby entities (player-relative dx/dy in yalms) plus the player's
-- heading. The overlay draws us at centre with a facing arrow + compass.
-- Range-limited to the client's awareness (~50y) by nature of the array.
-- Toggled by SCANZONE|radar|on / off from the overlay (radar view).
_ow_sz_radar_on   = false
_ow_sz_radar_last = 0
local _OW_SZ_RADAR_HZ      = 5
local _OW_SZ_RADAR_RANGE   = 10000   -- yalms: effectively the whole zone --
                                     -- report everything the client has loaded
                                     -- (Mappy-style), not just a 50y bubble
local _OW_SZ_RADAR_MAX     = 1000    -- entity cap (keeps the datagram bounded;
                                     -- ~46 B each stays well under the 64 KB recv)

function _ow_scanzone_radar_set(on)
    _ow_sz_radar_on = on and true or false
end

function _ow_scanzone_radar_tick(now)
    if not _ow_sz_radar_on then return end
    if not udp_gs then return end
    now = now or os.clock()
    if (now - _ow_sz_radar_last) < (1.0 / _OW_SZ_RADAR_HZ) then return end
    _ow_sz_radar_last = now
    if not (windower.ffxi and windower.ffxi.get_mob_array) then return end
    local me = windower.ffxi.get_mob_by_target
               and windower.ffxi.get_mob_by_target('me')
    if not (me and me.x and me.y) then return end
    local heading = me.heading or 0
    local rng2 = _OW_SZ_RADAR_RANGE * _OW_SZ_RADAR_RANGE
    local parts, n = {}, 0
    for _, v in pairs(windower.ffxi.get_mob_array()) do
        if type(v) == 'table' and v.valid_target and v.x and v.y
                and v.name and v.name ~= ''
                and v.index and (not me.index or v.index ~= me.index) then
            local dx, dy = v.x - me.x, v.y - me.y
            if (dx * dx + dy * dy) <= rng2 then
                -- Classify: is_npc is the reliable PC flag (players are the
                -- only non-NPC entities). Among server entities, split by
                -- spawn_type -- 2 = static NPC, 16 = standard monster, 14 =
                -- trust; anything else (lamps, doors, clickable objects) is
                -- left in the catch-all "object" bucket (t = 0).
                local t = 0                       -- 0 = object / other
                if not v.is_npc then
                    t = 2                         -- PC (player)
                elseif v.spawn_type == 2 then
                    t = 1                         -- NPC (static / friendly)
                elseif v.spawn_type == 16 then
                    t = 3                         -- monster
                end
                local hpp = v.hpp or 0
                local nm  = v.name:gsub('[|;,]', ' ')
                if #nm > 24 then nm = nm:sub(1, 24) end
                n = n + 1
                parts[n] = string.format('%d,%d,%.1f,%.1f,%d,%s',
                    v.index, t, dx, dy, hpp, nm)
                if n >= _OW_SZ_RADAR_MAX then break end
            end
        end
    end
    udp_gs:send(string.format('SZRADAR|%.3f|%d|%s',
        heading, n, table.concat(parts, ';')))
end

ow_safe_register('prerender', function()
    _ow_scanzone_radar_tick(os.clock())
end)

-- Sortie Gallimaufry tracker: any chat-log line that awards "<n> gallimaufry"
-- is forwarded to the overlay, which sums it for the run. Robust to the exact
-- wording -- it just needs the amount immediately before the word.
ow_safe_register('incoming text', function(original, modified)
    local txt = modified or original
    if not txt or txt == '' then return end
    if txt:lower():find('gallimaufry', 1, true) then
        local num = txt:match('([%d,]+)%s*[Gg]allimaufry')
        if num then
            local n = tonumber((num:gsub(',', '')))
            if n and n > 0 and udp_gs then
                udp_gs:send('SORTIEGIL|' .. n)
            end
        end
    end
end)

-- âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
--  Scan Zone â Nyzul lamps  (dev-mode feature)
-- âââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââââ
-- Poll the five fixed Nyzul lamp indexes (0x2D4..0x2D8) with 0x16 entity
-- requests and read each lamp's lit bit + position from the 0x0E reply,
-- forwarding SZLAMP|<index>|<x>|<y>|<z>|<lit>|<name> to the overlay roster.
-- The lit bit is the (>>16)&1 of the entity flag word â the same field
-- NyzulBuddy2 (Uwu/Darkdoom) reads for runes/lamps. Driven by
-- SCANZONE|lamps|on / off from the overlay. Globals to stay clear of the
-- 200-local chunk cap.
_ow_sz_lamps_on   = false
_ow_sz_lamps_last = 0
_ow_sz_lamp_floor   = -1     -- last Nyzul floor we reset lamps for
_ow_sz_lamp_floor_t = 0      -- os.clock() of last reset (debounce fallback)
_OW_SZ_RUNE_LO = 0x2D2      -- Rune of Transfer (0x2D2 even / 0x2D3 odd floor)
_OW_SZ_LAMP_LO = 0x2D4
_OW_SZ_LAMP_HI = 0x2D8
_OW_SZ_LAMP_HZ = 2          -- passive get_mob_by_index reads per second

function _ow_scanzone_lamps_set(on)
    _ow_sz_lamps_on = on and true or false
    _ow_sz_lamp_floor = -1              -- force a fresh scan on the next floor msg
    if udp_gs then pcall(function() udp_gs:send('SZLAMP|clear') end) end
end

-- Passive discovery: read each lamp index straight from the client's entity
-- table (get_mob_by_index -- NO packet) and forward its position so the overlay
-- can pin it. Lit is sent as "-" here, meaning "position only, keep whatever
-- lit state you already have" -- the lit bit only rides the 0x0E flag word
-- (handled below, or on a manual Refresh). A lamp that isn't loaded yet (far
-- side of the floor) just returns nil until you get near it, so the set fills
-- in as you go through the floor once and then persists overlay-side.
function _ow_scanzone_lamps_tick(now)
    if not _ow_sz_lamps_on then return end
    now = now or os.clock()
    if (now - _ow_sz_lamps_last) < (1.0 / _OW_SZ_LAMP_HZ) then return end
    _ow_sz_lamps_last = now
    if not (windower.ffxi and windower.ffxi.get_mob_by_index) then return end
    for idx = _OW_SZ_RUNE_LO, _OW_SZ_LAMP_HI do
        local mob = windower.ffxi.get_mob_by_index(idx)
        if mob and mob.x and mob.y and udp_gs then
            local nm = (mob.name or ''):gsub('[|;,]', ' ')
            udp_gs:send(string.format('SZLAMP|%d|%.1f|%.1f|%s|-|%s',
                idx, mob.x, mob.y,
                mob.z and string.format('%.1f', mob.z) or '', nm))
        end
    end
end

-- Manual reconcile: a one-shot 0x16 entity-update request for the five lamp
-- indices, driven by the overlay's "Refresh Lamps" button (SCANZONE|lamps|
-- refresh). It pulls the current lit state for every lamp -- the way to catch
-- one a party member activated while you were out of range. This is the ONLY
-- injection left in the lamp path, and only when you press the button.
function _ow_scanzone_lamps_refresh()
    if not (windower.packets and windower.packets.inject_outgoing) then
        return
    end
    for idx = _OW_SZ_RUNE_LO, _OW_SZ_LAMP_HI do
        local lo = idx % 256
        local hi = math.floor(idx / 256)
        pcall(function()
            windower.packets.inject_outgoing(0x16,
                string.char(0x16, 0x08, 0x00, 0x00, lo, hi, 0x00, 0x00))
        end)
    end
end

ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x0E then return end
    if not _ow_sz_lamps_on then return end
    local tindex = data:unpack('h', 0x08 + 1)
    if tindex < _OW_SZ_RUNE_LO or tindex > _OW_SZ_LAMP_HI then return end
    local lit_field = '-'               -- '-' = flag word absent -> keep prior
    pcall(function()
        local pk = packets.parse('incoming', data)
        local f = pk and pk['_unknown4']
        if f and f > 0 then             -- flag word present -> trust this update
            lit_field = ((math.floor(f / 65536) % 2) == 1) and '1' or '0'
        end
    end)
    local mob = windower.ffxi.get_mob_by_index
                and windower.ffxi.get_mob_by_index(tindex)
    if not mob then return end          -- index empty on this floor -> no lamp here
    local nm = (mob.name or ''):gsub('[|;,]', ' ')
    local x, y, z = mob.x, mob.y, mob.z
    if udp_gs then
        udp_gs:send(string.format('SZLAMP|%d|%s|%s|%s|%s|%s',
            tindex,
            x and string.format('%.1f', x) or '',
            y and string.format('%.1f', y) or '',
            z and string.format('%.1f', z) or '',
            lit_field, nm))
    end
end)

-- New-floor detector. The 0x02A floor message carries the floor number in
-- param1 (the same signal NyzulBuddy2 keys off). On a floor change while lamp
-- mode is on, wipe the previous floor's lamps from the overlay and fire an
-- immediate re-scan so the roster reflects the lamps on THIS floor. Non-lamp
-- floors leave the 0x2D4..0x2D8 indexes unresolved, so the roster stays empty.
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x02A then return end
    if not _ow_sz_lamps_on then return end
    if (windower.ffxi.get_info().zone or 0) ~= 77 then return end   -- Nyzul Isle
    local floor = nil
    pcall(function()
        local pk = packets.parse('incoming', data)
        if pk then floor = pk['param1'] or pk['Param 1'] or pk['_param1'] end
    end)
    local nowc = os.clock()
    if floor ~= nil then
        if floor == _ow_sz_lamp_floor then return end   -- same floor, ignore
        _ow_sz_lamp_floor = floor
    else
        -- floor number unreadable: debounce so stray 0x02A msgs don't thrash
        if (nowc - _ow_sz_lamp_floor_t) < 1.5 then return end
    end
    _ow_sz_lamp_floor_t = nowc
    if udp_gs then pcall(function() udp_gs:send('SZLAMP|clear') end) end
    _ow_sz_lamps_last = 0                 -- allow the tick to fire right now
    _ow_scanzone_lamps_tick(nowc)
end)

ow_safe_register('prerender', function()
    _ow_scanzone_lamps_tick(os.clock())
end)

-- ════════════════════════════════════════════════════════════════════════
-- Nyzul progress tracker. Adapted from NyzulHelper by Glarin of Asura
-- (BSD-3-Clause) — copyright/credit retained. Parses Nyzul Isle's text
-- messages to track floor, time remaining, objective, restriction, floors
-- completed and potential tokens, and streams them to the overlay as
-- NYZUL|... for the Scan Zone panel's Nyzul section. Display/box code from
-- the original is dropped; the overlay renders the state.
--   Copyright © 2020, Glarin of Asura. Redistribution permitted under the
--   BSD 3-Clause terms shipped with NyzulHelper.
-- ════════════════════════════════════════════════════════════════════════
function _ow_nyzul_boot()
    pcall(require, 'strings')                 -- string.strip_format
    local function stripf(s)
        s = s or ''
        if s.strip_format then
            local ok, r = pcall(function() return s:strip_format() end)
            if ok and r then s = r end
        end
        return (s:gsub('[\x00-\x1F]', ''))
    end
    local function rnd(n) return math.floor((n or 0) + 0.5) end
    local function pfind(s, lit) return s:find(lit, 1, true) ~= nil end

    local zone_timer = 0
    local end_time = nil
    local has_armband = false
    local party_size = 1
    local objective = ''
    local obj_state = 'p'          -- p = pending, g = complete
    local restriction = ''
    local restr_state = 'w'        -- w = warn, b = failed
    local starting_floor = 0
    local current_floor = 0
    local completed = 0
    local floor_penalities = 0
    local potential_tokens = 0
    local last_send = 0

    local function reset()
        zone_timer = 0; end_time = nil; objective = ''; obj_state = 'p'
        restriction = ''; restr_state = 'w'; starting_floor = 0
        current_floor = 0; completed = 0; floor_penalities = 0
        potential_tokens = 0
    end
    local function set_timer(remaining)
        zone_timer = remaining
        end_time = os.time() + zone_timer
    end
    local function get_relative_floor()
        if current_floor < starting_floor then return current_floor + 100 end
        return current_floor
    end
    local function get_token_rate()
        local rate = 1
        if has_armband then rate = rate + .1 end
        if party_size > 3 then rate = rate - ((party_size - 3) * .1) end
        return rate
    end
    local function resync_values()
        if starting_floor == 0 then
            starting_floor = current_floor
            if zone_timer == 0 then set_timer(1800) end
        end
        local relative_floor = get_relative_floor()
        if (relative_floor - starting_floor) > completed then
            completed = relative_floor - starting_floor
        end
        floor_penalities = 0
    end
    local function get_token_penalty(rate)
        return rnd(117 * rate) * floor_penalities
    end
    local function calculate_tokens()
        local relative_floor = get_relative_floor()
        local rate = get_token_rate()
        local floor_bonus = 0
        if relative_floor > 1 then
            floor_bonus = (10 * math.floor((relative_floor - 1) / 5))
        end
        potential_tokens = potential_tokens
            + ((200 + floor_bonus) * rate) - get_token_penalty(rate)
    end

    local function send_state()
        if not udp_gs then return end
        local rem = zone_timer
        if end_time ~= nil then rem = end_time - os.time() end
        if rem < 0 then rem = 0 end
        -- The objective phrase is already cut clean at parse time (the
        -- trailing 0x7F formatting code is removed there). Do NOT run it back
        -- through stripf here: strip_format re-interprets that phrase and
        -- collapses it to a fragment like "." / "y ." -- which is exactly the
        -- corruption that survived the parse-side fix. Cut at any stray 0x7F
        -- and drop control bytes, but never strip_format the objective.
        local obj = objective
        local _oc = obj:find(string.char(0x7F), 1, true)
        if _oc then obj = obj:sub(1, _oc - 1) end
        obj = obj:gsub('%c', ''):gsub('[|]', ' ')
        local rst = stripf(restriction):gsub('[|]', ' ')
        pcall(function()
            udp_gs:send(string.format('NYZUL|%d|%d|%d|%d|%d|%s|%s|%s|%s',
                current_floor, math.floor(rem), completed,
                rnd(get_token_rate() * 100), rnd(potential_tokens),
                obj_state, restr_state, obj, rst))
        end)
    end

    ow_safe_register('zone change', function(new, old)
        if new == 72 and old == 77 then
            zone_timer = 0; has_armband = false
        else
            reset()
        end
        if new == 77 then
            local ok, pi = pcall(windower.ffxi.get_party_info)
            party_size = (ok and pi and pi.party1_count) or 1
        end
    end)

    ow_safe_register('incoming chunk', function(id, data)
        if id == 0x55 and (windower.ffxi.get_info().zone or 0) == 72 then
            local ki = windower.ffxi.get_key_items()
            if ki then
                for _, v in pairs(ki) do
                    if v == 797 then has_armband = true break end
                end
            end
        end
    end)

    ow_safe_register('incoming text', function(original, modified, mode)
        local info = windower.ffxi.get_info()
        if not info.logged_in or info.zone ~= 77 or original == '' then
            return
        end
        if mode == 123 then
            if pfind(original, 'Security field malfunction') then
                restriction = stripf(original); restr_state = 'b'
            elseif pfind(original, 'Time limit has been reduced') then
                set_timer(zone_timer - (tonumber(original:match('%d+')) or 0) * 60)
            elseif pfind(original, 'Potential token reward reduced') then
                floor_penalities = floor_penalities + 1
            end
        elseif (mode == 146 or mode == 148) and pfind(original, 'Earth time') then
            local multiplier = 1
            if pfind(original, 'minute') then multiplier = 60 end
            set_timer((tonumber(original:match('%d+')) or 0) * multiplier)
        elseif mode == 146 then
            if original:find('Floor %d+ objective complete. Rune of Transfer activated.') then
                completed = completed + 1
                obj_state = 'g'; restriction = ''; restr_state = 'w'
                calculate_tokens()
            end
        elseif mode == 148 then
            if pfind(original, 'Objective:') then
                if pfind(original, 'Commencing') then
                    objective = 'Complete on-site objectives'
                else
                    -- Capture everything after "Objective:". The phrase is
                    -- plain ASCII terminated by a 0x7F formatting code (cut
                    -- below); a fixed byte offset (old original:sub(11)) could
                    -- slice it wrong, so match the text instead.
                    local body = original:match('Objective:%s*(.+)')
                                 or original:sub(11)
                    -- A trailing FFXI formatting code (0x7F + a parameter
                    -- byte) terminates the readable phrase. strip_format
                    -- mangles it (collapsing the line to a fragment like
                    -- "y ."), so cut at the first 0x7F before anything else.
                    local _cut = body:find(string.char(0x7F), 1, true)
                    if _cut then body = body:sub(1, _cut - 1) end
                    -- These objective strings are plain ASCII followed by a
                    -- trailing 0x7F formatting code (cut above). Running
                    -- strip_format or auto-translate resolution over the plain
                    -- phrase mangled it (the ".", "y ." corruption captured in
                    -- nyzul_obj.log), so only resolve auto-translate when a real
                    -- AT marker (0xFD) is present, and never strip_format the
                    -- phrase -- just drop control bytes/braces and trim.
                    if _ow_resolve_outgoing_at
                            and body:find('\253', 1, true) then
                        local ok_at, r = pcall(_ow_resolve_outgoing_at, body)
                        if ok_at and r then body = r end
                    end
                    body = body:gsub('%c', ''):gsub('[{}]', '')
                    objective = (body:gsub('^%s*(.-)%s*$', '%1'))
                end
                obj_state = 'p'
            elseif pfind(original, 'archaic') then
                restriction = stripf(original)
            elseif original:find('Transfer complete. Welcome to Floor %d+.') then
                current_floor = tonumber(original:match('%d+')) or current_floor
                resync_values()
            end
        end
    end)

    ow_safe_register('prerender', function()
        local info = windower.ffxi.get_info()
        if not info.logged_in or info.zone ~= 77 then return end
        local now = os.clock()
        if (now - last_send) < 0.25 then return end
        last_send = now
        send_state()
    end)
end
_ow_nyzul_boot()

-- ════════════════════════════════════════════════════════════════════════
-- Omen progress tracker. Adapted from Omen by Braden, Sechs (BSD-3-Clause) —
-- copyright/credit retained. Parses Reisenjima Henge (zone 292) text mode 161
-- to track the floor objective, omen count, bonus-objective timer and the per-
-- slot bonus objectives, streaming them to the overlay as OMEN|... for the
-- Scan Zone panel's Omen section. Display/box and sound code from the original
-- is dropped; the overlay renders the state.
--   Copyright © 2017, Braden, Sechs. Redistribution permitted under the BSD
--   3-Clause terms shipped with Omen.
-- ════════════════════════════════════════════════════════════════════════
function _ow_omen_boot()
    local omens = "0"
    local obj_time = 0
    local end_time = nil
    local floor_obj = "Waiting for objectives..."
    local floor_clear = false
    local last_send = 0
    local objectives = {}

    local function reset_objectives()
        for i = 1, 10 do objectives[i] = {mes = 0, amt = 0, req = 0} end
        obj_time = 0
        floor_clear = false
    end
    reset_objectives()

    local messages = {
        [1]  = {id=1,  short="WS Damage",     check="%d+%su",
                init="%d: Reduce your foe's HP by %a*%s*%a*%s*%d+ using a single weapon skill.",
                eval="%d: You have reduced your foe's HP by %a*%s*%a*%s*%d+ using a single weapon skill."},
        [2]  = {id=2,  short="MB Damage",     check="%d+%su",
                init="%d: Reduce your foe's HP by %a*%s*%a*%s*%d+ using a single magic burst.",
                eval="%d: You have reduced your foe's HP by %a*%s*%a*%s*%d+ using a single magic burst."},
        [3]  = {id=3,  short="Non-MB Nuke",   check="%d+%su",
                init="%d: Reduce your foe's HP by %a*%s*%a*%s*%d+ using a single magic attack without performing a magic burst.",
                eval="%d: You have reduced your foe's HP by %a*%s*%a*%s*%d+ using a single magic attack without performing a magic burst."},
        [4]  = {id=4,  short="Melee Round",   check="%d+%si",
                init="%d: Reduce your foe's HP by %a*%s*%a*%s*%d+ in a single auto%-attack.",
                eval="%d: You have reduced your foe's HP by %a*%s*%a*%s*%d+ in a single auto%-attack."},
        [5]  = {id=5,  short="Kills",         check="%d+%sf",
                init="%d: Vanquish %d+ %a+.",
                eval="%d: You have vanquished %d+ %a+."},
        [6]  = {id=6,  short="Critical Hits", check="%d+%sc",
                init="%d: Deal %d+ critical %a+ to your foes.",
                eval="%d: You have dealt %d+ critical %a+ to your foes."},
        [7]  = {id=7,  short="Abilities",     check="%d+%sa",
                init="%d: Use %d+ %a+ on your foes.",
                eval="%d: You have used %d+ %a+ on your foes."},
        [8]  = {id=8,  short="Spells",        check="%d+%ss",
                init="%d: Cast %d+ %a+ on your foes.",
                eval="%d: You have cast %d+ %a+ on your foes."},
        [9]  = {id=9,  short="Magic Bursts",  check="%d+%sm",
                init="%d: Perform %d+ magic %a+ on your foes.",
                eval="%d: You have performed %d+ magic %a+ on your foes."},
        [10] = {id=10, short="Skillchains",   check="%d+%ss",
                init="%d: Execute %d+ %a+ using weapon %a+ on your foes!",
                eval="%d: You have executed %d+ %a+ using weapon %a+ on your foes!"},
        [11] = {id=11, short="All WS",        check="%d+%sw",
                init="%d: Use %d+ weapon %a+ on your foes.",
                eval="%d: You have used %d+ weapon %a+ on your foes."},
        [12] = {id=12, short="Physical WS",   check="%d+%sp",
                init="%d: Use %d+ physical weapon %a+ on your foes.",
                eval="%d: You have used %d+ physical weapon %a+ on your foes."},
        [13] = {id=13, short="Magic WS",      check="%d+%se",
                init="%d: Use %d+ elemental weapon %a+ on your foes.",
                eval="%d: You have used %d+ elemental weapon %a+ on your foes."},
        [14] = {id=14, short="500 HP Cures",  check="%d+%st",
                init="%d: Restore at least 500 HP %d+ %a+.",
                eval="%d: You have restored at least 500 HP %d+ %a+."},
    }
    local hide_words = {"Kin","Gin","Kei","Kyou","Fu","Ou","Craver",
                        "Gorger","Thinker","Treasure","Waiting"}

    local function sanitize(s) return (s or ''):gsub('[|;~]', ' ') end

    local function send_omen()
        if not udp_gs then return end
        local rem = obj_time
        if end_time ~= nil and obj_time >= 1 then rem = end_time - os.time() end
        if rem < 0 then rem = 0 end
        local hide = 0
        for _, wd in ipairs(hide_words) do
            if floor_obj:find(wd, 1, true) then hide = 1 break end
        end
        local parts = {}
        for i = 1, 10 do
            local o = objectives[i]
            if o and o.mes ~= 0 then
                local m = messages[o.mes]
                local short = (m and m.short) or ('Obj' .. i)
                local st = 'n'
                if o.amt == o.req then st = 'g'
                elseif rem < 1 and o.amt < o.req then st = 'b' end
                parts[#parts + 1] = string.format('%s~%d~%d~%s',
                    short, o.amt, o.req, st)
            end
        end
        pcall(function()
            udp_gs:send(string.format('OMEN|%s|%s|%d|%d|%d|%s',
                sanitize(floor_obj), tostring(omens), math.floor(rem),
                floor_clear and 1 or 0, hide, table.concat(parts, ';')))
        end)
    end

    ow_safe_register('zone change', function(zone)
        floor_obj = "Waiting for objectives..."
        reset_objectives()
    end)

    ow_safe_register('incoming text', function(original, modified, mode)
        if (windower.ffxi.get_info().zone or 0) ~= 292 then return end
        if mode ~= 161 then return end
        local slot = tonumber(original:match('^%d+'))
        local objective = slot and objectives[slot]
        if original:match('^%d') and objective then
            for _, v in pairs(messages) do
                if original:find(v.init) then
                    if objective.mes ~= v.id then objective.amt = 0 end
                    objective.mes = v.id
                    local mm = original:match(v.check)
                    if mm then objective.req = tonumber(mm:sub(1, -2)) or objective.req end
                elseif original:find(v.eval) then
                    local mm = original:match(v.check)
                    if mm then objective.amt = tonumber(mm:sub(1, -2)) or objective.amt end
                    if objective.mes == 0 then
                        objective.mes = v.id
                        objective.req = -1
                    end
                end
            end
            send_omen()
        elseif original:find('%d+ omen') then
            omens = original:match('%d+')
            send_omen()
        elseif original:find('You have %d+ seconds remaining.') then
            if obj_time == 0 then
                obj_time = tonumber(original:match('%d+')) or 0
                end_time = os.time() + obj_time
                send_omen()
            end
        elseif original:find('A spectral light flares up.', 1, true) then
            floor_clear = true
            send_omen()
        elseif original:find('A faint light twinkles into existence.', 1, true) then
            -- floor sub-clear chime in the original; sound omitted here
        elseif original:find('Vanquish', 1, true) or original:find('Open %d treasure portent') then
            local s1 = original:gsub(string.char(0x7f) .. '1', '')
            s1 = s1:gsub('%p', '')
            s1 = s1:gsub('(%s%a)', string.upper)
            floor_obj = s1:gsub('The', 'the')
            if floor_clear then reset_objectives() end
            send_omen()
        elseif original:find('The light shall come even if you fail to obey.', 1, true) then
            floor_obj = "Free Floor!"
            if floor_clear then reset_objectives() end
            send_omen()
        end
    end)

    ow_safe_register('prerender', function()
        if (windower.ffxi.get_info().zone or 0) ~= 292 then return end
        if obj_time < 1 then return end
        local now = os.clock()
        if (now - last_send) < 0.25 then return end
        last_send = now
        send_omen()
    end)
end
_ow_omen_boot()

-- ════════════════════════════════════════════════════════════════════
--  Synergy  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Packet engine for the Synergy furnace minigame, driven by the overlay's
-- DEV · Synergy panel. Detects a furnace session (trade 0x036 + the 0x05B
-- "begin" option), reads recipe / current / fewell / pressure / impurity /
-- leak / overload / furnace-HP state and streams it to the overlay
-- (SYNERGY| on the gs channel); feeds elements and runs furnace functions
-- on command (SYNERGY|feed|<elem> / SYNERGY|func|<name> from the inbound
-- drain) by injecting the same 0x01A poke + scripted 0x05B menu navigation
-- the standalone tool used.
--
-- Ported from the 'Synergy' addon (BSD-3-Clause, Copyright (c) 2016
-- Sebastien Gomez / "Colway"); the option-index map, poke + 0x05B menu-nav
-- sequence, and packet offsets are unchanged. Globals (not locals) to stay
-- clear of the 200-local chunk cap. Single-overlay build: the IPC mirroring
-- of the original is intentionally dropped.

_OW_SYN_ELEMENTS = {fire = 100, ice = 101, wind = 102, earth = 103,
                    thunder = 104, water = 105, light = 106, dark = 107}
_OW_SYN_FUNCS    = {thwack = 120, pressure = 121, repair_furnace = 122,
                    safety_lever = 123, recycle = 124, ['end'] = 110}
_OW_SYN_EQUIP    = {smock = 131}        -- Engraver's Touch (Goldsmith's Smock)
-- canonical element order for the pipe-packed payloads to the overlay
_OW_SYN_ORDER    = {'fire', 'ice', 'wind', 'earth',
                    'thunder', 'water', 'light', 'dark'}

_ow_syn_in        = false   -- in an active furnace session
_ow_syn_target    = {}      -- {Target id, Target Index, Zone id, Menu ID, Option Index}
_ow_syn_firstrun  = true    -- send the one-shot 0x016 on the first poke of a session
_ow_syn_armed     = false   -- a feed/func is mid-flight (waiting on the 0x034 reply)
_ow_syn_armed_ref = false   -- a re-fewell is mid-flight (waiting on the 0x034 reply)
_ow_syn_part1     = false   -- saw the trade (0x036) to a Synergy Furnace
_ow_syn_engineer  = false   -- resolved Synergy Engineer id (for re-fewell)
_ow_syn_overload  = false
_ow_syn_hp_last   = 0

function _ow_syn_send(payload)
    if udp_gs then pcall(function() udp_gs:send(payload) end) end
end

function _ow_syn_my_index()
    local me = windower.ffxi.get_player()
    if not me then return nil end
    for i, v in pairs(windower.ffxi.get_mob_array()) do
        if v and v.name == me.name then return i end
    end
    return nil
end

function _ow_synergy_inject_0x10f()
    pcall(function()
        local p = packets.new('outgoing', 0x10F)
        packets.inject(p)
    end)
end

function _ow_synergy_create_0x05B(target_id, target_index, option_index,
                                  zone_number, message, menu_id, unk1, unk2)
    pcall(function()
        local p = packets.new('outgoing', 0x05B)
        p['Target']            = target_id
        p['Option Index']      = option_index
        p['_unknown1']         = unk1
        p['Target Index']      = target_index
        p['Menu ID']           = menu_id
        p['Zone']              = zone_number
        p['Automated Message'] = message
        p['_unknown2']         = unk2
        packets.inject(p)
    end)
end

function _ow_synergy_poke(option_index)
    -- Feed / func: latch the option index, then poke the furnace (0x01A)
    -- when within 2 yalms. The 0x034 reply drives the 0x05B menu-nav.
    local ti = _ow_syn_target['Target Index']
    if not ti then return end
    local mob = windower.ffxi.get_mob_by_index(ti)
    if not mob or not mob.distance then return end
    local dist = math.sqrt(mob.distance)
    if dist <= 0 or dist >= 2 then
        ow_chat(123, '[OmniWatch] Synergy: furnace too far away')
        return
    end
    _ow_syn_target['Option Index'] = option_index
    _ow_syn_armed = true
    pcall(function()
        local p = packets.new('outgoing', 0x01A, {
            ['Target']       = _ow_syn_target['Target id'],
            ['Target Index'] = ti,
            ['Category']     = 0,
            ['Param']        = 0,
            ['_unknown1']    = 0})
        packets.inject(p)
    end)
    if _ow_syn_firstrun then
        local me = _ow_syn_my_index()
        if me then
            pcall(function()
                local p = packets.new('outgoing', 0x016,
                                      {['Target Index'] = me})
                packets.inject(p)
            end)
        end
        _ow_syn_firstrun = false
    end
end

function _ow_synergy_resolve_engineer()
    for _, v in pairs(windower.ffxi.get_mob_array()) do
        if v and v.name == 'Synergy Engineer' and v.distance
                and math.sqrt(v.distance) < 6 then
            _ow_syn_engineer = v.id
            return v
        end
    end
    return nil
end

function _ow_synergy_poke_engineer()
    local eng
    if _ow_syn_engineer then
        eng = windower.ffxi.get_mob_by_id(_ow_syn_engineer)
    end
    if not eng then eng = _ow_synergy_resolve_engineer() end
    if not eng then
        ow_chat(123, '[OmniWatch] Synergy: no engineer nearby')
        return
    end
    local dist = (eng.distance and math.sqrt(eng.distance)) or 999
    if dist <= 0 or dist >= 6 then
        ow_chat(123, '[OmniWatch] Synergy: engineer too far away')
        return
    end
    _ow_syn_armed_ref = true
    pcall(function()
        local p = packets.new('outgoing', 0x01A, {
            ['Target']       = eng.id,
            ['Target Index'] = eng.index,
            ['Category']     = 0,
            ['Param']        = 0,
            ['_unknown1']    = 0})
        packets.inject(p)
    end)
end

function _ow_synergy_clear()
    _ow_syn_in        = false
    _ow_syn_target    = {}
    _ow_syn_armed     = false
    _ow_syn_armed_ref = false
    _ow_syn_part1     = false
    _ow_syn_engineer  = false
    _ow_syn_overload  = false
    _ow_syn_send('SYNERGY|end')
end

-- Command entrypoints (called from the inbound drain) ------------------
function _ow_synergy_cmd_feed(name)
    local oi = _OW_SYN_ELEMENTS[name]
    if oi and _ow_syn_in then _ow_synergy_poke(oi) end
end

function _ow_synergy_cmd_func(name)
    if not _ow_syn_in then return end
    if name == 'smock' then
        _ow_synergy_poke(_OW_SYN_EQUIP.smock)
    else
        local oi = _OW_SYN_FUNCS[name]
        if oi then _ow_synergy_poke(oi) end
    end
end

function _ow_synergy_cmd_refewell()
    if _ow_syn_in then return end       -- re-fewell is a pre-session action
    _ow_synergy_inject_0x10f()
    _ow_synergy_poke_engineer()
end

function _ow_synergy_cmd_refresh()
    _ow_synergy_inject_0x10f()
end

-- Detection: trade to the furnace, then the 0x05B "begin" option (150)
-- latches the session target and flips us into in_synergy. ------------
ow_safe_register('outgoing chunk', function(id, data)
    if id == 0x036 then
        local ok, p = pcall(packets.parse, 'outgoing', data)
        if ok and p and windower.ffxi.get_mob_name then
            local nm = windower.ffxi.get_mob_name(p['Target'])
            if nm == 'Synergy Furnace' then
                _ow_syn_part1 = true
            end
        end
    elseif id == 0x05B and _ow_syn_part1 then
        local ok, p = pcall(packets.parse, 'outgoing', data)
        if ok and p and p['Option Index'] == 150 then
            _ow_syn_target['Target id']    = p['Target']
            _ow_syn_target['Target Index'] = p['Target Index']
            _ow_syn_target['Zone id']      = p['Zone']
            _ow_syn_target['Menu ID']      = (p['Menu ID'] or 0) - 3
            _ow_syn_part1    = false
            _ow_syn_in       = true
            _ow_syn_firstrun = true
            _ow_synergy_inject_0x10f()
            _ow_syn_send(string.format('SYNERGY|start|%s|%s|%s|%s',
                tostring(_ow_syn_target['Target id'] or 0),
                tostring(_ow_syn_target['Target Index'] or 0),
                tostring(_ow_syn_target['Zone id'] or 0),
                tostring(_ow_syn_target['Menu ID'] or 0)))
        end
    end
end)

-- 0x034: the furnace's menu-open reply. We BLOCK it (so the real menu UI
-- doesn't pop) and inject the scripted 0x05B nav that performs the latched
-- action. ow_safe_register swallows handler returns, so this one is a raw
-- register_event with its own pcall + a true return to block the packet.
windower.register_event('incoming chunk', function(id, data)
    if id ~= 0x034 then return end
    local blocked = false
    pcall(function()
        if _ow_syn_in and _ow_syn_armed then
            local t   = _ow_syn_target
            local tid, tix = t['Target id'], t['Target Index']
            local zone, menu = t['Zone id'], t['Menu ID']
            local oi  = t['Option Index']
            _ow_synergy_create_0x05B(tid, tix, 147, zone, true,  menu, 0, 0)
            _ow_synergy_create_0x05B(tid, tix, 143, zone, true,  menu, 0, 0)
            _ow_synergy_create_0x05B(tid, tix, 143, zone, true,  menu, 0, 0)
            _ow_synergy_create_0x05B(tid, tix, oi,  zone, true,  menu, 0, 0)
            _ow_synergy_create_0x05B(tid, tix, 143, zone, true,  menu, 0, 0)
            _ow_synergy_create_0x05B(tid, tix, 0,   zone, false, menu, 0, 0)
            _ow_syn_armed = false
            blocked = true
        elseif (not _ow_syn_in) and _ow_syn_armed_ref then
            local eng = _ow_syn_engineer
                        and windower.ffxi.get_mob_by_id(_ow_syn_engineer)
            if eng then
                local zone = windower.ffxi.get_info().zone
                _ow_synergy_create_0x05B(eng.id, eng.index, 3, zone, true,
                                         11001, 0, 0)
                _ow_synergy_create_0x05B(eng.id, eng.index, 8, zone, false,
                                         11001, 0, 0)
            end
            _ow_syn_armed_ref = false
            _ow_synergy_inject_0x10f()
            blocked = true
        end
    end)
    if blocked then return true end
end)

-- 0x05C: current fewell in the furnace + the player's fewell inventory.
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x05C or not _ow_syn_in or #data < 33 then return end
    local b33 = data:byte(33)
    if b33 == 0 and (data:byte(18) or 0) ~= 0 and (data:byte(19) or 0) ~= 0
            and (data:byte(20) or 0) ~= 0 then
        local off = {5, 7, 9, 11, 13, 15, 17, 19}      -- current (byte - 100)
        local c = {}
        for k = 1, 8 do c[k] = (data:byte(off[k]) or 100) - 100 end
        _ow_syn_send('SYNERGY|current|' .. table.concat(c, '|'))
    elseif (data:byte(6) or 0) == 0 and (data:byte(7) or 0) == 0
            and (data:byte(8) or 0) == 0 and b33 < 100 then
        local off = {5, 9, 13, 17, 21, 25, 29, 33}     -- fewell inv (byte % 128)
        local f = {}
        for k = 1, 8 do f[k] = (data:byte(off[k]) or 0) % 128 end
        _ow_syn_send('SYNERGY|fewell|' .. table.concat(f, '|'))
    end
end)

-- 0x113: fewell inventory via named packet fields (redundant with the 0x05C
-- inventory branch but more direct; pcall-guarded against res drift).
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x113 then return end
    local ok, p = pcall(packets.parse, 'incoming', data)
    if not ok or not p then return end
    local f = {p['Syngery Fewell (Fire)'],      p['Syngery Fewell (Ice)'],
               p['Syngery Fewell (Wind)'],      p['Syngery Fewell (Earth)'],
               p['Syngery Fewell (Lightning)'], p['Syngery Fewell (Water)'],
               p['Syngery Fewell (Light)'],     p['Syngery Fewell (Dark)']}
    for k = 1, 8 do f[k] = tonumber(f[k]) or 0 end
    _ow_syn_send('SYNERGY|fewell|' .. table.concat(f, '|'))
end)

-- 0x038: elemental leak (toggle). Type ef81..ef88 -> leaking element + the
-- element that fixes it. The "no longer leaking" text clears it.
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x038 then return end
    local ok, p = pcall(packets.parse, 'incoming', data)
    if not ok or not p then return end
    local v = p['Type']
    local leak, fix = '', ''
    if     v == 'ef81' then leak, fix = 'fire',    'ice'
    elseif v == 'ef82' then leak, fix = 'ice',     'wind'
    elseif v == 'ef83' then leak, fix = 'wind',    'earth'
    elseif v == 'ef84' then leak, fix = 'earth',   'thunder'
    elseif v == 'ef85' then leak, fix = 'thunder', 'water'
    elseif v == 'ef86' then leak, fix = 'water',   'fire'
    elseif v == 'ef87' then leak, fix = 'light',   'dark'
    elseif v == 'ef88' then leak, fix = 'dark',    'light'
    end
    if leak ~= '' then
        _ow_syn_send('SYNERGY|leak|' .. leak .. '|' .. fix)
    end
end)

-- 0x028: action packet. Category 7 by the furnace toggles overload; 3 / 11
-- clear it.
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x028 or not _ow_syn_in then return end
    local ok, p = pcall(packets.parse, 'incoming', data)
    if not ok or not p then return end
    if p['Actor'] ~= _ow_syn_target['Target id'] then return end
    local cat = p['Category']
    if cat == 7 then
        _ow_syn_overload = not _ow_syn_overload
    elseif cat == 3 or cat == 11 then
        _ow_syn_overload = false
    end
    _ow_syn_send('SYNERGY|overload|' .. (_ow_syn_overload and '1' or '0'))
end)

-- 0x04F: synergy session ended.
ow_safe_register('incoming chunk', function(id, data)
    if id == 0x04F and _ow_syn_in then
        _ow_synergy_clear()
    end
end)

-- Incoming text: recipe ("Difficulty:" line), pressure / impurity, leak
-- clear, and claim expiry. The recipe symbols are encoded as the two bytes
-- 0xEF 0x1F..0x26 (fire..dark) followed by the needed amount in ASCII; we
-- scan for them directly so we don't depend on Windower's string library
-- (which OmniWatch deliberately doesn't load).
ow_safe_register('incoming text', function(original, modified)
    local new = modified or original or ''
    if new:find('Difficulty:') then
        local map = {[0x1F] = 'fire', [0x20] = 'ice',  [0x21] = 'wind',
                     [0x22] = 'earth', [0x23] = 'thunder', [0x24] = 'water',
                     [0x25] = 'light', [0x26] = 'dark'}
        local need = {fire = 0, ice = 0, wind = 0, earth = 0,
                      thunder = 0, water = 0, light = 0, dark = 0}
        local i, n = 1, #new
        while i < n do
            if new:byte(i) == 0xEF and map[new:byte(i + 1)] then
                local elem = map[new:byte(i + 1)]
                local j = i + 2
                while j <= n and new:byte(j) == 0x20 do j = j + 1 end
                local sign = ''
                if j <= n and (new:byte(j) == 0x2D or new:byte(j) == 0x2B) then
                    if new:byte(j) == 0x2D then sign = '-' end
                    j = j + 1
                end
                local num = ''
                while j <= n do
                    local b = new:byte(j)
                    if b >= 0x30 and b <= 0x39 then
                        num = num .. string.char(b); j = j + 1
                    else break end
                end
                need[elem] = tonumber(sign .. num) or 0
                i = j
            else
                i = i + 1
            end
        end
        local out = {}
        for _, e in ipairs(_OW_SYN_ORDER) do out[#out + 1] = need[e] end
        _ow_syn_send('SYNERGY|recipe|' .. table.concat(out, '|'))
    end
    if new:find('Internal pressure:') then
        local _, _, pres  = new:find('Internal pressure: (%d+) Pz/Im')
        local _, _, ratio = new:find('Impurity ratio: (%d+)%%')
        _ow_syn_send('SYNERGY|data|' .. (pres or '0') .. '|' .. (ratio or '0'))
    end
    if new:find('elemental power is no longer leaking') then
        _ow_syn_send('SYNERGY|leak||')
    end
    if new:find('Your claim over the synergy furnace has expired')
            or new:find('Your claim to the synergy furnace has been relinquished') then
        if _ow_syn_in then _ow_synergy_clear() end
    end
end)

-- Furnace HP%: streamed ~2 Hz while in a session (the panel draws a bar).
ow_safe_register('prerender', function()
    if not _ow_syn_in then return end
    local now = os.clock()
    if now - (_ow_syn_hp_last or 0) < 0.5 then return end
    _ow_syn_hp_last = now
    local ti  = _ow_syn_target['Target Index']
    local hpp = 0
    if ti then
        local mob = windower.ffxi.get_mob_by_index(ti)
        if mob and mob.hpp then hpp = mob.hpp end
    end
    _ow_syn_send('SYNERGY|hp|' .. tostring(hpp))
end)

-- ════════════════════════════════════════════════════════════════════
--  Craft  (dev-mode feature)
-- ════════════════════════════════════════════════════════════════════
-- Embedded auto-synthesis engine driven by the overlay's DEV · Craft panel.
-- The panel owns the recipe database (recipes.json) and hands us a recipe's
-- crystal + ingredient short-names per Make; we resolve them to item ids via
-- `res`, auto-pull the crystal and every ingredient out of any enabled bag
-- into inventory, build the 0x096 synthesis packet (incl. the obfuscation
-- hash the server requires) and inject it on a coroutine-scheduled delay
-- loop. Food auto-eat, Ionis/imagery support, a jiggle keypress, HQ-crystal
-- substitution and put-to-bag are all included. Driven by CRAFT|... from the
-- inbound drain; emits CRAFT|status / queue / result / msg back on the gs
-- channel.
--
-- Ported from the 'craft' addon (BSD-3-Clause, Copyright (c) 2017 Mojo;
-- recipes provided by BG-Wiki). The hash, the 0x096 build, the bag-pull /
-- sort-block sequence and the support-NPC menu nav are unchanged; the
-- Windower-library helpers it used (strings :format, Q queues, S sets,
-- res:name()/res:filter()) are rewritten to plain Lua since OmniWatch
-- doesn't load those libs. coroutine.schedule/sleep is OmniWatch's native
-- delay primitive (same as autora / blusets / calltrust).

_OW_CRAFT_EXCEPTIONS = {
    ['Geo Crystal'] = 6509,
    ['Fire Card'] = 9764, ['Ice Card'] = 9765, ['Wind Card'] = 9766,
    ['Earth Card'] = 9767, ['Lightning Card'] = 9768, ['Water Card'] = 9769,
    ['Light Card'] = 9770, ['Dark Card'] = 9771,
}
_OW_CRAFT_CLUSTERS = {
    ['Fire Crystal'] = 'Fire Cluster', ['Ice Crystal'] = 'Ice Cluster',
    ['Wind Crystal'] = 'Wind Cluster', ['Earth Crystal'] = 'Earth Cluster',
    ['Lightng. Crystal'] = 'Lightning Cluster', ['Water Crystal'] = 'Water Cluster',
    ['Light Crystal'] = 'Light Cluster', ['Dark Crystal'] = 'Dark Cluster',
}
_OW_CRAFT_HQCRYSTAL = {
    ['Fire Crystal'] = 'Inferno Crystal', ['Ice Crystal'] = 'Glacier Crystal',
    ['Wind Crystal'] = 'Cyclone Crystal', ['Earth Crystal'] = 'Terra Crystal',
    ['Lightng. Crystal'] = 'Plasma Crystal', ['Water Crystal'] = 'Torrent Crystal',
    ['Light Crystal'] = 'Aurora Crystal', ['Dark Crystal'] = 'Twilight Crystal',
}
_OW_CRAFT_SUPPORT_NPCS = {
    {name = "Orechiniel", zone = 230, menu = 650, buff = 240},
    {name = "Greubaque", zone = 231, menu = 628, buff = 237},
    {name = "Ulycille", zone = 231, menu = 623, buff = 236},
    {name = "Azima", zone = 234, menu = 122, buff = 242},
    {name = "Fatimah", zone = 235, menu = 302, buff = 238},
    {name = "Wise Owl", zone = 237, menu = 103, buff = 237},
    {name = "Kipo-Opo", zone = 238, menu = 10015, buff = 243},
    {name = "Lih Pituu", zone = 241, menu = 10018, buff = 241},
    {name = "Terude-Harude", zone = 241, menu = 10013, buff = 239},
    {name = "Fleuricette", zone = 256, menu = 1201, buff = 512},
    {name = "Quiri-Aliri", zone = 257, menu = 1201, buff = 512},
}

_ow_craft_queue    = {}
_ow_craft_busy     = false
_ow_craft_paused   = false
_ow_craft_delay    = 24
_ow_craft_skipdel  = false
_ow_craft_cond     = {move = false, sort = false, crystal = false,
                      support = false, item = false}
_ow_craft_appr     = {}
_ow_craft_inv      = {}
_ow_craft_food     = false
_ow_craft_support  = false
_ow_craft_jiggle   = false
_ow_craft_hqsynth  = false
_ow_craft_display  = false
_ow_craft_injected = false
_ow_craft_delta    = false
_ow_craft_name2id  = nil
_ow_craft_bags     = nil

function _ow_craft_emit(payload)
    if udp_gs then pcall(function() udp_gs:send(payload) end) end
end

function _ow_craft_notice(msg)
    ow_chat(100, '[craft] ' .. tostring(msg))
    _ow_craft_emit('CRAFT|msg|' .. tostring(msg))
end

function _ow_craft_emit_status()
    _ow_craft_emit(string.format('CRAFT|status|%d|%s|%s|%s|%s|%s|%d|%s|%s',
        _ow_craft_delay,
        _ow_craft_paused and '1' or '0',
        _ow_craft_display and '1' or '0',
        _ow_craft_food and tostring(_ow_craft_food) or '',
        _ow_craft_support and '1' or '0',
        _ow_craft_jiggle and tostring(_ow_craft_jiggle) or '',
        #_ow_craft_queue,
        _ow_craft_hqsynth and '1' or '0',
        _ow_craft_busy and '1' or '0'))
end

function _ow_craft_emit_queue()
    _ow_craft_emit('CRAFT|queue|' .. tostring(#_ow_craft_queue))
end

function _ow_craft_split(s, sep)
    local out = {}
    if not s then return out end
    local start = 1
    while true do
        local i = s:find(sep, start, true)
        if not i then out[#out + 1] = s:sub(start); break end
        out[#out + 1] = s:sub(start, i - 1)
        start = i + #sep
    end
    return out
end

function _ow_craft_build_maps()
    if _ow_craft_name2id and _ow_craft_bags then return end
    local m = {}
    for id, v in pairs(res.items) do
        if type(v) == 'table' then
            if v.en  and m[v.en:lower()]  == nil then m[v.en:lower()]  = id end
            if v.enl and m[v.enl:lower()] == nil then m[v.enl:lower()] = id end
        end
    end
    _ow_craft_name2id = m
    local b = {}
    for _, v in pairs(res.bags) do
        if type(v) == 'table' and v.command and v.id ~= nil then
            local nm = (v.en or v.name or v.command or '')
            local cmd = v.command or ''
            local excl = nm:match('Inventory') or nm:match('Temporary')
                or nm:match('Wardrobe') or cmd:match('inventory')
                or cmd:match('temporary') or cmd:match('wardrobe')
            if not excl then b[cmd] = v.id end
        end
    end
    _ow_craft_bags = b
end

function _ow_craft_item_id(name)
    if not name then return nil end
    if _OW_CRAFT_EXCEPTIONS[name] then return _OW_CRAFT_EXCEPTIONS[name] end
    _ow_craft_build_maps()
    return _ow_craft_name2id[name:lower()]
end

function _ow_craft_has_buff(player, buff_id)
    if not (player and player.buffs) then return false end
    for _, b in pairs(player.buffs) do
        if b == buff_id then return true end
    end
    return false
end

function _ow_craft_hash(crystal, item, count)
    local c = ((crystal % 6506) % 4238) % 4096
    local m = (c + 1) * 6 + 77
    local b = (c + 1) * 42 + 31
    local m2 = (8 * c + 26) + (item - 1) * (c + 35)
    return (m * item + b + m2 * (count - 1)) % 127
end

function _ow_craft_busy_wait(block, timeout, message)
    local start = os.time()
    while _ow_craft_cond[block] and ((os.time() - start) < timeout) do
        coroutine.sleep(0.1)
    end
    if os.time() - start >= timeout then
        _ow_craft_cond[block] = false
        return string.format("Timed out - %s", message)
    else
        _ow_craft_inv = windower.ffxi.get_items()
    end
end

function _ow_craft_check_bag(bag, id)
    if not _ow_craft_inv['enabled_' .. bag] then return false end
    local contents = _ow_craft_inv[bag]
    local maxb = _ow_craft_inv['max_' .. bag] or 0
    for index = 1, maxb do
        local c = contents and contents[index]
        if c and c.id == id then
            _ow_craft_cond['sort'] = true
            _ow_craft_cond['move'] = true
            windower.ffxi.get_item(_ow_craft_bags[bag], index, c.count)
            return true
        end
    end
    return false
end

function _ow_craft_check_bags(id)
    if (_ow_craft_inv['count_inventory'] or 0)
            == (_ow_craft_inv['max_inventory'] or 0) then
        return false
    end
    _ow_craft_build_maps()
    for bag, _ in pairs(_ow_craft_bags) do
        if _ow_craft_check_bag(bag, id) then return true end
    end
    return false
end

function _ow_craft_fetch_ingredient(ingredient)
    local id = _ow_craft_item_id(ingredient)
    if not id then return string.format("Unknown item %s", ingredient) end
    local contents = _ow_craft_inv['inventory']
    local maxi = _ow_craft_inv['max_inventory'] or 0
    for index = 1, maxi do
        if _ow_craft_appr[index] == nil then _ow_craft_appr[index] = 0 end
        local c = contents and contents[index]
        if c and c.id == id and c.count > _ow_craft_appr[index] then
            _ow_craft_appr[index] = _ow_craft_appr[index] + 1
            return id, index
        end
    end
    if _ow_craft_check_bags(id) then
        local status = _ow_craft_busy_wait('move', 10,
            string.format('moving %s', ingredient))
        if status then return status
        else return _ow_craft_fetch_ingredient(ingredient) end
    end
    if _OW_CRAFT_CLUSTERS[ingredient] then
        local cluster = _OW_CRAFT_CLUSTERS[ingredient]
        local _, cindex = _ow_craft_fetch_ingredient(cluster)
        if cindex then
            _ow_craft_cond['sort'] = true
            _ow_craft_cond['item'] = id
            local start = os.time()
            windower.chat.input(string.format('/item "%s" <me>', cluster))
            local status = _ow_craft_busy_wait('item', 10,
                string.format('using %s', cluster))
            if status then return status end
            local rem = 4 - (os.time() - start)
            if rem > 0 then coroutine.sleep(rem) end
            _ow_craft_inv = windower.ffxi.get_items()
            return _ow_craft_fetch_ingredient(ingredient)
        end
    end
    return string.format("Unable to locate %s", ingredient)
end

function _ow_craft_build_synth(crystal_name, ingredients)
    local pl = windower.ffxi.get_player()
    if not pl or pl.status ~= 0 then return "You can't craft at the moment" end
    _ow_craft_inv = windower.ffxi.get_items()
    _ow_craft_appr = {}
    local p = packets.new('outgoing', 0x096)
    local crystal = crystal_name
    if _ow_craft_hqsynth and _OW_CRAFT_HQCRYSTAL[crystal] then
        crystal = _OW_CRAFT_HQCRYSTAL[crystal]
    end
    local cid, cindex = _ow_craft_fetch_ingredient(crystal)
    if not cindex then return cid end
    p['Crystal'] = cid
    p['Crystal Index'] = cindex
    p['Ingredient count'] = #ingredients
    for i, ing in ipairs(ingredients) do
        local iid, iindex = _ow_craft_fetch_ingredient(ing)
        if not iindex then return iid end
        p[string.format('Ingredient %d', i)] = iid
        p[string.format('Ingredient Index %d', i)] = iindex
    end
    p['_unknown1'] = _ow_craft_hash(p['Crystal'], p['Ingredient 1'],
                                    p['Ingredient count'])
    return p
end

function _ow_craft_issue_synth(item)
    local p = _ow_craft_build_synth(item.crystal, item.ingredients)
    if type(p) == 'string' then
        _ow_craft_skipdel = true
        _ow_craft_cond['sort'] = false
        return string.format("%s - %s", item.name or '?', p)
    else
        packets.inject(p)
        _ow_craft_cond['sort'] = false
    end
end

function _ow_craft_repeat()
    windower.chat.input('/lastsynth')
end

function _ow_craft_put_items(bag, id)
    local src = _ow_craft_inv['inventory']
    local dst = _ow_craft_inv[bag]
    local empty = {}
    for index = 1, (_ow_craft_inv['max_' .. bag] or 0) do
        if dst[index] and dst[index].count == 0 then empty[index] = true end
    end
    local idx = next(empty, nil)
    for index = 1, (_ow_craft_inv['max_inventory'] or 0) do
        if src[index] and src[index].id == id and idx then
            windower.ffxi.put_item(_ow_craft_bags[bag], index, src[index].count)
            dst[idx].id = id
            dst[idx].count = src[index].count
            src[index].id = 0
            src[index].count = 0
            idx = next(empty, idx)
            _ow_craft_delta = true
        end
    end
end

function _ow_craft_put(item)
    _ow_craft_cond['sort'] = true
    _ow_craft_delta = false
    _ow_craft_inv = windower.ffxi.get_items()
    if item.bag and item.bag ~= '' then
        local bag = item.bag
        if not _ow_craft_inv['enabled_' .. bag] then
            _ow_craft_cond['sort'] = false
            return string.format("bag %s disabled", bag)
        end
        _ow_craft_put_items(bag, item.id)
    else
        _ow_craft_build_maps()
        for bag, _ in pairs(_ow_craft_bags) do
            if _ow_craft_inv['enabled_' .. bag] then
                _ow_craft_put_items(bag, item.id)
            end
        end
    end
    if _ow_craft_delta then
        _ow_craft_delta = false
        _ow_craft_busy_wait('move', 10,
            string.format('moving %s', item.name or '?'))
    end
    _ow_craft_cond['sort'] = false
    coroutine.sleep(3.5)
    _ow_craft_skipdel = true
end

function _ow_craft_validate(npcs)
    local zone = windower.ffxi.get_info()['zone']
    local valid = false
    for _, npc in pairs(npcs) do
        if zone == npc.zone then
            valid = true
            local mob = windower.ffxi.get_mob_by_name(npc.name)
            if mob and mob.distance and math.sqrt(mob.distance) < 6 then
                return mob, npc
            end
        end
    end
    if valid then _ow_craft_notice("Too far away from NPC") end
end

function _ow_craft_poke_npc()
    local mob, npc = _ow_craft_validate(_OW_CRAFT_SUPPORT_NPCS)
    if npc and mob then
        local pl = windower.ffxi.get_player()
        if _ow_craft_has_buff(pl, npc.buff) then return end
        _ow_craft_cond['support'] = true
        local p = packets.new('outgoing', 0x01A, {
            ['Target'] = mob.id, ['Target Index'] = mob.index,
            ['Category'] = 0, ['Param'] = 0, ['_unknown1'] = 0})
        packets.inject(p)
        return _ow_craft_busy_wait('support', 10, "getting crafting buff")
    end
end

function _ow_craft_jiggle_now()
    windower.send_command(string.format('setkey %s down', _ow_craft_jiggle))
    coroutine.sleep(0.25)
    windower.send_command(string.format('setkey %s up', _ow_craft_jiggle))
end

function _ow_craft_consume_food()
    local pl = windower.ffxi.get_player()
    if _ow_craft_has_buff(pl, 251) then return end
    _ow_craft_inv = windower.ffxi.get_items()
    local _, index = _ow_craft_fetch_ingredient(_ow_craft_food)
    if index then
        windower.chat.input(string.format('/item "%s" <me>', _ow_craft_food))
        coroutine.sleep(3.5)
    else
        _ow_craft_notice(string.format("Unable to consume %s", _ow_craft_food))
    end
end

function _ow_craft_check_queue()
    if #_ow_craft_queue > 0 then
        if not _ow_craft_paused then
            if _ow_craft_jiggle then _ow_craft_jiggle_now() end
            if _ow_craft_support then
                _ow_craft_poke_npc()
                coroutine.sleep(2)
            end
            if _ow_craft_food then _ow_craft_consume_food() end
            local item = table.remove(_ow_craft_queue, 1)
            _ow_craft_emit_queue()
            local msg
            if item.kind == 'make' then
                msg = _ow_craft_issue_synth(item)
            elseif item.kind == 'repeat' then
                msg = _ow_craft_repeat()
            elseif item.kind == 'put' then
                msg = _ow_craft_put(item)
            end
            if msg then _ow_craft_notice(msg) end
            if _ow_craft_skipdel then
                coroutine.schedule(_ow_craft_check_queue, 0)
                _ow_craft_skipdel = false
            else
                coroutine.schedule(_ow_craft_check_queue, _ow_craft_delay)
            end
        end
    else
        _ow_craft_busy = false
        _ow_craft_emit_status()
    end
end

function _ow_craft_process_queue()
    if not _ow_craft_busy then
        _ow_craft_busy = true
        coroutine.schedule(_ow_craft_check_queue, 0)
    end
    _ow_craft_emit_status()
end

function _ow_craft_command(sub, arg)
    if sub == 'make' then
        local parts = _ow_craft_split(arg, '|')
        local count = tonumber(parts[1]) or 1
        local name = parts[2] or '?'
        local crystal = parts[3] or ''
        local ings = _ow_craft_split(parts[4] or '', ';')
        while #ings > 0 and ings[#ings] == '' do ings[#ings] = nil end
        for _ = 1, count do
            _ow_craft_queue[#_ow_craft_queue + 1] =
                {kind = 'make', name = name, crystal = crystal, ingredients = ings}
        end
        _ow_craft_notice(string.format('Queued %d x %s', count, name))
        _ow_craft_process_queue()
    elseif sub == 'repeat' then
        local count = tonumber(arg) or 1
        for _ = 1, count do
            _ow_craft_queue[#_ow_craft_queue + 1] = {kind = 'repeat'}
        end
        _ow_craft_notice(string.format('Queued %d repeat(s)', count))
        _ow_craft_process_queue()
    elseif sub == 'put' then
        local parts = _ow_craft_split(arg, '|')
        local name = parts[1] or ''
        local bag = parts[2]
        local id = _ow_craft_item_id(name)
        if not id then
            _ow_craft_notice(string.format('Unknown item %s', name))
            return
        end
        if bag and bag ~= '' then
            bag = bag:lower()
            _ow_craft_build_maps()
            if not _ow_craft_bags[bag] then
                _ow_craft_notice(string.format('Unknown bag %s', bag))
                return
            end
        end
        _ow_craft_queue[#_ow_craft_queue + 1] =
            {kind = 'put', id = id, name = name, bag = bag}
        _ow_craft_notice(string.format('Queued put %s', name))
        _ow_craft_process_queue()
    elseif sub == 'stop' or sub == 'clear' then
        _ow_craft_queue = {}
        _ow_craft_notice('Cleared queue')
        _ow_craft_emit_status()
    elseif sub == 'pause' then
        _ow_craft_paused = true
        _ow_craft_notice('Paused')
        _ow_craft_emit_status()
    elseif sub == 'resume' then
        if _ow_craft_paused then
            _ow_craft_paused = false
            _ow_craft_busy = false
            _ow_craft_process_queue()
        end
        _ow_craft_notice('Resumed')
        _ow_craft_emit_status()
    elseif sub == 'delay' then
        local n = tonumber(arg)
        if n then
            _ow_craft_delay = math.max(17, n)
            _ow_craft_notice(string.format('Delay %d', _ow_craft_delay))
        end
        _ow_craft_emit_status()
    elseif sub == 'food' then
        if arg == '' then
            _ow_craft_food = false
        else
            local id = _ow_craft_item_id(arg)
            if id and res.items[id] then
                _ow_craft_food = res.items[id].en or arg
            else
                _ow_craft_food = arg
            end
        end
        _ow_craft_emit_status()
    elseif sub == 'support' then
        _ow_craft_support = (arg == '1')
        _ow_craft_emit_status()
    elseif sub == 'jiggle' then
        _ow_craft_jiggle = (arg ~= '' and arg) or false
        _ow_craft_emit_status()
    elseif sub == 'hq' then
        _ow_craft_hqsynth = (arg == '1')
        _ow_craft_emit_status()
    elseif sub == 'display' then
        _ow_craft_display = (arg == '1')
        _ow_craft_emit_status()
    elseif sub == 'status' then
        _ow_craft_emit_status()
    end
end

-- block the outgoing 0x3A bag-sort while we're moving items (raw register
-- + return true to actually block; ow_safe_register swallows returns).
windower.register_event('outgoing chunk', function(id, data)
    if id == 0x3A and _ow_craft_cond['sort'] then
        return true
    end
end)

-- support buff: when we poked a support NPC, answer its 0x34 menu-open with
-- the support option and block the menu (raw register for the same reason).
windower.register_event('incoming chunk', function(id, data)
    if id ~= 0x34 or not _ow_craft_cond['support'] then return end
    local blocked = false
    pcall(function()
        local mob, npc = _ow_craft_validate(_OW_CRAFT_SUPPORT_NPCS)
        if mob and npc then
            local p = packets.new('outgoing', 0x5B, {
                ['Target'] = mob.id, ['Option Index'] = 1,
                ['Target Index'] = mob.index, ['Automated Message'] = false,
                ['Zone'] = windower.ffxi.get_info()['zone'],
                ['Menu ID'] = npc.menu})
            packets.inject(p)
            _ow_craft_cond['support'] = false
            blocked = true
        end
    end)
    if blocked then return true end
end)

-- non-blocking observers: 0x1D clears the move gate, 0x20 clears the
-- cluster-use item gate.
ow_safe_register('incoming chunk', function(id, data)
    if id == 0x1D then _ow_craft_cond['move'] = false end
end)
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x20 then return end
    local ok, p = pcall(packets.parse, 'incoming', data)
    if ok and p and p['Item'] == _ow_craft_cond['item'] then
        _ow_craft_cond['item'] = false
    end
end)

-- mark our own injected synths so the result hook only fires for them; also
-- the optional packet display.
ow_safe_register('outgoing chunk', function(id, data, modified, injected)
    if id == 0x096 and injected then
        _ow_craft_injected = true
    end
    if id == 0x096 and _ow_craft_display then
        local ok, p = pcall(packets.parse, 'outgoing', data)
        if ok and p then
            ow_chat(100, string.format(
                '[craft] synth: crystal=%s ing#=%s',
                tostring(p['Crystal']), tostring(p['Ingredient count'])))
        end
    end
end)

-- synthesis result (0x06F) for our injected synths -> chat + overlay.
ow_safe_register('incoming chunk', function(id, data)
    if id ~= 0x06F or not _ow_craft_injected then return end
    local ok, p = pcall(packets.parse, 'incoming', data)
    if not ok or not p then return end
    local r = p['Result']
    if r == 0 or r == 2 then
        local ent = res.items[p['Item']]
        local item = ent and (ent.english or ent.en) or '?'
        local count = p['Count'] or 1
        _ow_craft_emit(string.format('CRAFT|result|ok|%s|%s',
            tostring(item), tostring(count)))
        if count > 1 then
            ow_chat(121, string.format(
                'You synthesized: %s x%d.', item, count))
        else
            ow_chat(121, string.format(
                'You synthesized: %s.', item))
        end
        _ow_craft_injected = false
    elseif r == 1 or r == 5 then
        _ow_craft_emit('CRAFT|result|fail||')
        ow_chat(121,
            'Your synthesis has failed and your crystal is lost.')
        _ow_craft_injected = false
    end
end)

do  -- scope SkillUp+AH engine locals out of the main chunk
-- ════════════════════════════════════════════════════════════════════════
--  SkillUp engine  (standalone port of smd111's GearSwap "skillup.lua";
--  original by Arcon / Byrth / Mote et al.)
--
--  SkillUp is a GearSwap data file; its cast loop runs through GearSwap's
--  precast/filtered_action/aftercast hooks (cancel_spell / equip). OmniWatch
--  is a standalone Windower addon, so that pipeline is reimplemented here:
--  every cast goes out as `input /ma` (or `/ja`/`/item`), completion /
--  interruption is detected via the `action` event (category 4 = done,
--  category 8 / param 28787 = interrupted), and all the precast decisions
--  (low-MP skip+rest, Blue Unbridled Learning/Wisdom, wind/string instrument
--  swap, Summoning call→Favor/Siphon→Release, Ninjutsu tool unpack, optional
--  Trust / skill-up Item / Geo-Refresh) are applied BEFORE each cast.
--
--  Hardened against the original's two "random stop" bugs:
--    1. `(count % #spells)+1` divides by zero the instant the spell list
--       empties (Ninjutsu tools depleting, deleted spells) -> Lua error ->
--       chain dies. Here every advance guards #spells > 0.
--    2. Resting forever when the MP-full check never matches. Here we wake on
--       vitals.mpp >= 100, and a watchdog re-kicks the loop if it ever stalls.
--
--  Driven by SKILLUP|... (inbound drain) and //ow su ... ; emits
--  SKILLUP|status|... back to the panel. Skillups counted from action
--  message 38; skill levels / caps from the 0x062 packet.
-- ════════════════════════════════════════════════════════════════════════

_ow_su = {
    running=false, type='None', spells={}, idx=1,
    shutdown=false, logoff=false, stoptype='Stop',
    use_trust=false, use_item=false, use_geo=false,
    total=0, ups={}, skill={}, skipped={},
    pending=nil,            -- spell id currently in flight
    phase='idle',           -- 'idle' | 'cast' | 'smn'  (summoning sub-dance)
    resting=false,
    last_action=0,          -- os.clock() of last progress (watchdog)
    epoch=0,                -- bumped on every start/stop to invalidate stale schedules
}

_OW_SU_BLU_UL  = { ['Harden Shell']=true, ['Pyric Bulwark']=true, ['Carcharian Verve']=true }
_OW_SU_ITEMS   = { 5889, 5890, 5891, 5892 }
_OW_SU_SKILLID = { Healing=33, Enhancing=34, Summoning=38, Ninjutsu=39,
                   Singing=40, Blue=43, Geomancy=44 }
_OW_SU_AFTERCAST = 3.0
_OW_SU_WATCHDOG  = 18.0     -- if no progress in this many seconds, re-kick

_ow_su_wind_inst   = 'Cornette'
_ow_su_string_inst = 'Lamia Harp'

-- Ninja tool -> packed-tool item id (used to /item-unpack when out).
_OW_SU_NIN_TOOLS = {
    ['Shihei']=5314, ['Uchitake']=5308, ['Tsurara']=5309, ['Kawahori-Ogi']=5310,
    ['Makibishi']=5311, ['Hiraishin']=5312, ['Mizu-Deppo']=5313, ['Jusatsu']=5315,
    ['Kaginawa']=5316, ['Sairui-Ran']=5317, ['Kodoku']=5318, ['Shinobi-Tabi']=5319,
    ['Sanjaku-Tenugui']=5417, ['Soshi']=5734, ['Ranka']=6265, ['Furusumi']=6266,
    ['Kabenro']=5863, ['Jinko']=5864, ['Ryuno']=5865, ['Mokujin']=5866,
    ['Chonofuda']=5869, ['Inoshishinofuda']=5867, ['Shikanofuda']=5868,
}

local function _ow_su_player() return windower.ffxi.get_player and windower.ffxi.get_player() or nil end
local function _ow_su_pet()    return windower.ffxi.get_mob_by_target and windower.ffxi.get_mob_by_target('pet') or nil end
local function _ow_su_buffs(p) local s={} if p and p.buffs then for _,b in ipairs(p.buffs) do s[b]=true end end return s end
local function _ow_su_emit(payload) if udp_gs then pcall(function() udp_gs:send(payload) end) end end

local function _ow_su_rate()
    local now, total = os.clock(), 0
    for ts, pts in pairs(_ow_su.ups) do
        if now - ts > 3600 then _ow_su.ups[ts] = nil else total = total + pts end
    end
    return total
end

function _ow_su_emit_status()
    local s = _ow_su
    _ow_su_emit(string.format('SKILLUP|status|%s|%d|%.1f|%.1f|%s|%s|%s|%s',
        s.type, s.running and 1 or 0, _ow_su_rate()/10, (s.total or 0)/10,
        s.use_trust and '1' or '0', s.use_geo and '1' or '0',
        s.use_item and '1' or '0', s.stoptype))
end

-- ── spell helpers ─────────────────────────────────────────────────────────
local function _ow_su_spell_valid(v, p)
    if not (v and v.levels and v.targets) then return false end
    local lvl_ok = (v.levels[p.main_job_id] and v.levels[p.main_job_id] <= p.main_job_level)
                or (v.levels[p.sub_job_id]  and v.levels[p.sub_job_id]  <= p.main_job_level)
    if not lvl_ok or not v.targets.Self then return false end
    local nm = v.en or ''
    if nm:match('^Teleport') or nm:match('^Warp') or nm:match('^Tractor')
        or nm == 'Retrace' or nm == 'Escape' or nm:match('^Geo%-')
        or nm == 'Sacrifice' or nm == 'Odin' or nm == 'Alexander'
        or nm:match('^Recall') then return false end
    return true
end

local function _ow_su_rec(name) return res.spells:with('en', name) end

local function _ow_su_spell_usable(name)
    local rec = _ow_su_rec(name); if not rec then return false end
    local known = windower.ffxi.get_spells()[rec.id]
    local rc = windower.ffxi.get_spell_recasts()
    return known and (not rc or (rc[rec.recast_id] or 0) == 0)
end

local function _ow_su_ja_ready(id)
    local ar = windower.ffxi.get_ability_recasts()
    return ar and (ar[id] or 1) == 0
end

function _ow_su_check_cap()
    local sk, t = _ow_su.skill, _ow_su.type
    if t=='Healing' or t=='Enhancing' or t=='Blue' or t=='Summoning' then
        return sk[t..' Magic Capped'] == true
    elseif t=='Ninjutsu' then return sk['Ninjutsu Capped'] == true
    elseif t=='Geomancy' then return sk['Geomancy Capped']==true and sk['Handbell Capped']==true
    elseif t=='Singing' then
        return sk['Singing Capped']==true and sk['Stringed Instrument Capped']==true
           and sk['Wind Instrument Capped']==true
    end
    return false
end

-- ── lifecycle ─────────────────────────────────────────────────────────────
function _ow_su_stop(reason)
    _ow_su.running = false
    _ow_su.pending = nil
    _ow_su.phase   = 'idle'
    _ow_su.epoch   = (_ow_su.epoch or 0) + 1     -- invalidate any pending schedules
    ow_chat(207, '[skillup] ' .. tostring(reason or 'stopped'))
    if _ow_su.logoff then windower.send_command('wait 3.0;input /logout')
    elseif _ow_su.shutdown then windower.send_command('wait 3.0;input /shutdown') end
    _ow_su_emit_status()
end

-- guarded advance: empties never cause `% 0`; an empty list stops cleanly.
local function _ow_su_advance()
    local n = #_ow_su.spells
    if n == 0 then _ow_su_stop('spell list empty'); return false end
    _ow_su.idx = (_ow_su.idx % n) + 1
    return true
end

local function _ow_su_progress() _ow_su.last_action = os.clock() end

-- safe scheduler that no-ops if the run has moved on (epoch changed)
local function _ow_su_sched(fn, delay)
    local e = _ow_su.epoch
    coroutine.schedule(function()
        if _ow_su.running and _ow_su.epoch == e then pcall(fn) end
    end, delay)
end

-- ── ninja tools: return a tool item name to /item-unpack, or nil ──────────
local function _ow_su_nin_unpack(name)
    local tmap = gearswap and gearswap.tool_map
    if not tmap or not tmap[name] then return nil end
    local tool = tmap[name].en
    local id = _OW_SU_NIN_TOOLS[tool]
    if not id then return nil end
    local item = res.items[id] and res.items[id].en
    if not item then return nil end
    local inv = windower.ffxi.get_items and windower.ffxi.get_items('inventory')
    -- if a packed tool is on hand, /item it to unpack
    if inv then
        for _, it in ipairs(inv) do
            if it.id == id and (it.count or 0) > 0 then return item end
        end
    end
    return nil
end

-- ── the cast step ─────────────────────────────────────────────────────────
function _ow_su_cast_current()
    if not _ow_su.running then return end
    local ok, err = pcall(_ow_su_cast_current_impl)
    if not ok then
        ow_chat(123, '[skillup] cast error: ' .. tostring(err))
        -- don't die: let the watchdog re-kick
    end
end

function _ow_su_cast_current_impl()
    if _ow_su_check_cap() then _ow_su_stop('skill capped') return end
    if #_ow_su.spells == 0 then _ow_su_stop('no spells') return end
    local p = _ow_su_player(); if not p then _ow_su_sched(_ow_su_cast_current, 2.0) return end
    _ow_su.phase = 'cast'

    local name = _ow_su.spells[_ow_su.idx]
    local rec  = _ow_su_rec(name)
    if not rec then if _ow_su_advance() then _ow_su_sched(_ow_su_cast_current, 0.5) end return end
    local buffs = _ow_su_buffs(p)
    local mp    = (p.vitals and p.vitals.mp) or 0

    -- Singing: equip the instrument for whichever skill still isn't capped.
    if _ow_su.type == 'Singing' then
        if not _ow_su.skill['Stringed Instrument Capped'] then
            windower.send_command('input /equip range "'.._ow_su_string_inst..'"')
        elseif not _ow_su.skill['Wind Instrument Capped'] then
            windower.send_command('input /equip range "'.._ow_su_wind_inst..'"')
        end
    end

    -- Ninjutsu: unpack a tool if we're out, then retry.
    if _ow_su.type == 'Ninjutsu' then
        local item = _ow_su_nin_unpack(name)
        if item then
            windower.send_command('input /item "'..item..'" <me>')
            _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, 2.0); return
        end
    end

    -- Blue: Unbridled Learning(81)/Wisdom(254) for UL-only spells.
    if _OW_SU_BLU_UL[name] and not buffs[491] and not buffs[492] then
        if _ow_su_ja_ready(81) then
            windower.send_command('input /ja "Unbridled Learning" <me>')
            _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, 2.0); return
        elseif _ow_su_ja_ready(254) then
            windower.send_command('input /ja "Unbridled Wisdom" <me>')
            _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, 2.0); return
        end
    end

    -- Low MP: skip; if everything's been skipped, rest until full.
    if (rec.mp_cost or 0) + 25 > mp then
        if _ow_su.skipped[name] then
            _ow_su.skipped = {}; _ow_su.resting = true
            windower.send_command('input /heal on')
            _ow_su_progress(); _ow_su_sched(_ow_su_rest_check, 3.0); return
        end
        _ow_su.skipped[name] = true
        if _ow_su_advance() then _ow_su_sched(_ow_su_cast_current, 0.3) end
        return
    end

    -- Optional helpers (between casts): Moogle trust / skill-up item / Geo-Refresh.
    if _ow_su.use_trust and (p.in_combat == false or true) then
        local moogle = res.spells[931]
        if moogle and _ow_su_spell_usable(moogle.en) and name ~= moogle.en then
            local party = windower.ffxi.get_party()
            if party and (party.party1_count or 1) == 1 then
                windower.send_command('input /ma "'..moogle.en..'" <me>')
                _ow_su.pending = moogle.id; _ow_su_progress(); return
            end
        end
    end
    if _ow_su.use_item and not buffs[251] then
        local inv = windower.ffxi.get_items and windower.ffxi.get_items('inventory')
        if inv then
            for _, id in ipairs(_OW_SU_ITEMS) do
                local has=false
                for _, it in ipairs(inv) do if it.id==id and (it.count or 0)>0 then has=true break end end
                if has and res.items[id] then
                    windower.send_command('input /item "'..res.items[id].en..'" <me>')
                    _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, 4.0); return
                end
            end
        end
    end

    if not _ow_su_spell_usable(name) then
        if _ow_su_advance() then _ow_su_sched(_ow_su_cast_current, 0.5) end
        return
    end

    local cast_name = name
    if windower.to_shift_jis then
        local ok, sj = pcall(windower.to_shift_jis, name); if ok and sj then cast_name = sj end
    end
    _ow_su.pending = rec.id
    _ow_su_progress()
    windower.send_command('input /ma "'..cast_name..'" <me>')
end

-- Summoning sub-dance: after the avatar/spirit lands, Favor/Siphon then Release.
function _ow_su_smn_after(spell_en)
    _ow_su.phase = 'smn'
    local is_spirit = spell_en:find('Spirit') ~= nil
    if is_spirit and _ow_su_ja_ready(232) then
        windower.send_command('input /ja "Elemental Siphon" <me>')
    elseif (not is_spirit) and _ow_su_ja_ready(250) then
        windower.send_command('input /ja "Avatar\'s Favor" <me>')
    end
    _ow_su_progress()
    _ow_su_sched(_ow_su_smn_release, 4.0)
end

function _ow_su_smn_release()
    if _ow_su_pet() then windower.send_command('input /ja "Release" <me>') end
    _ow_su.phase = 'cast'
    _ow_su_progress()
    if _ow_su_advance() then _ow_su_sched(_ow_su_cast_current, _OW_SU_AFTERCAST) end
end

-- ── cast pacing via the action event ──────────────────────────────────────
windower.register_event('action', function(act)
    if not _ow_su.running or not _ow_su.pending then return end
    if not act or not act.actor_id then return end
    local p = _ow_su_player(); if not p or act.actor_id ~= p.id then return end
    if act.category == 4 and act.param == _ow_su.pending then
        local done = _ow_su.spells[_ow_su.idx]
        _ow_su.pending = nil; _ow_su.skipped = {}; _ow_su_progress()
        if _ow_su.type == 'Summoning' then
            _ow_su_smn_after(done or '')
        else
            if _ow_su_advance() then _ow_su_sched(_ow_su_cast_current, _OW_SU_AFTERCAST) end
        end
    elseif act.category == 8 and act.param == 28787
            and act.targets and act.targets[1] and act.targets[1].actions
            and act.targets[1].actions[1]
            and act.targets[1].actions[1].param == _ow_su.pending then
        _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, _OW_SU_AFTERCAST)
    end
end)

-- ── skill levels (0x062) ──────────────────────────────────────────────────
windower.register_event('incoming chunk', function(id, data)
    if id == 0x062 then
        local ok, pkt = pcall(function() return packets.parse('incoming', data) end)
        if ok and pkt then
            _ow_su.skill = pkt
            if _ow_su.running and _ow_su_check_cap() then _ow_su_stop('skill capped') end
            _ow_su_emit_status()
        end
    end
end)

-- ── resting: wake on full MP (mpp) ────────────────────────────────────────
function _ow_su_rest_check()
    if not (_ow_su.running and _ow_su.resting) then return end
    local p = _ow_su_player()
    local mpp = p and p.vitals and p.vitals.mpp or 0
    if mpp >= 100 then
        _ow_su.resting = false
        windower.send_command('input /heal off')
        _ow_su_progress(); _ow_su_sched(_ow_su_cast_current, 1.0)
    else
        _ow_su_sched(_ow_su_rest_check, 3.0)
    end
end

-- ── skillup counter (action message id 38 on you) ─────────────────────────
windower.register_event('action message',
    function(actor_id, target_id, ai, ti, message_id, p1, p2, p3)
        local p = _ow_su_player()
        if message_id == 38 and p and target_id == p.id then
            _ow_su.total = (_ow_su.total or 0) + (p2 or 0)
            _ow_su.ups[os.clock()] = (p2 or 0)
            _ow_su_progress()
            _ow_su_emit_status()
        end
    end)

-- ── watchdog: if running but no progress for a while, re-kick the loop ─────
windower.register_event('prerender', function()
    if not _ow_su.running or _ow_su.resting then return end
    if (os.clock() - (_ow_su.last_action or 0)) > _OW_SU_WATCHDOG then
        _ow_su.pending = nil
        _ow_su_progress()
        _ow_su_sched(_ow_su_cast_current, 0.1)
    end
end)

-- ── start / commands ──────────────────────────────────────────────────────
function _ow_su_start(skilltype)
    local norm
    for _, v in ipairs({'Healing','Geomancy','Enhancing','Ninjutsu','Singing','Blue','Summoning'}) do
        if v:lower() == tostring(skilltype):lower() then norm = v end
    end
    if not norm then ow_chat(123,'[skillup] unknown skill: '..tostring(skilltype)) return end
    local p = _ow_su_player(); if not p then return end
    local sid = _OW_SU_SKILLID[norm]
    local known = windower.ffxi.get_spells()
    local list = {}
    for _, v in pairs(res.spells) do
        if v.skill == sid and known[v.id] and _ow_su_spell_valid(v, p) then list[#list+1] = v.en end
    end
    if #list == 0 then ow_chat(123,'[skillup] current job can not use '..norm..' spells') return end
    _ow_su.type=norm; _ow_su.spells=list; _ow_su.idx=1; _ow_su.skipped={}
    _ow_su.resting=false; _ow_su.phase='cast'; _ow_su.pending=nil
    _ow_su.running=true; _ow_su.epoch=(_ow_su.epoch or 0)+1; _ow_su_progress()
    ow_chat(207,'[skillup] '..norm..': '..#list..' spells')
    _ow_su_emit_status()
    _ow_su_sched(_ow_su_cast_current, 0.5)
end

function _ow_su_command(rest)
    local a = {}
    for tok in (tostring(rest)..'|'):gmatch('([^|]*)|') do a[#a+1] = tok end
    local cmd = (a[1] or ''):lower()
    if cmd == 'start' then _ow_su_start(a[2] or '')
    elseif cmd == 'stop' or cmd == 'skillstop' then _ow_su_stop('stopped')
    elseif cmd == 'after' then
        local m = (a[2] or 'stop'):lower()
        _ow_su.shutdown=(m=='shutdown'); _ow_su.logoff=(m=='logoff')
        _ow_su.stoptype=(m=='shutdown' and 'Shutdown') or (m=='logoff' and 'Logoff') or 'Stop'
        _ow_su_emit_status()
    elseif cmd == 'toggle' then
        local w=(a[2] or ''):lower()
        if w=='trust' then _ow_su.use_trust=not _ow_su.use_trust
        elseif w=='geo' then _ow_su.use_geo=not _ow_su.use_geo
        elseif w=='item' then _ow_su.use_item=not _ow_su.use_item end
        _ow_su_emit_status()
    elseif cmd == 'inst' then
        local which=(a[2] or ''):lower()
        if which=='wind' and a[3] and a[3]~='' then _ow_su_wind_inst=a[3]
        elseif which=='string' and a[3] and a[3]~='' then _ow_su_string_inst=a[3] end
        _ow_su_emit_status()
    elseif cmd == 'status' then _ow_su_emit_status() end
end

-- ════════════════════════════════════════════════════════════════════════
--  Auction House engine
--  Owns the item DB (res.items) for the panel's Buy search, builds the bid
--  packet (outgoing 0x04E, Type 0x0E) and reads the result (incoming 0x04C,
--  Type 0x0E -> Buy Status). Buy loop per queued item: bid at `start`; on a
--  win count it and re-bid at the same price; on a loss raise by `inc`; stop
--  the item once it would exceed `max`; advance through the queue; all bids
--  spaced by `throttle` to respect the server. A pending-timeout watchdog
--  keeps it from hanging if the server never answers.
--
--  Requires being in an Auction House zone (the menu is opened for you via
--  an injected incoming 0x04C). Driven by AH|... (drain) and //ow ah ;
--  Buy Status: 0x01 Success | 0x02 Placing(pending) | 0xC5 Failed | 0xE5 Cannot Bid
-- ════════════════════════════════════════════════════════════════════════
_ow_ah = {
    running=false, throttle=8.0, queue={}, qi=1,
    pending=false, pend_time=0, epoch=0, spoof_menu=true,
}

local function _ow_ah_emit(payload)
    if udp_gs then pcall(function() udp_gs:send(payload) end) end
end

-- AH city zones; bids only go out from one of these (Ivaar's AuctionHelper).
local _OW_AH_ZONES = {}
for _, _z in ipairs({'Bastok Mines','Bastok Markets','Norg',"Southern San d'Oria",
        "Port San d'Oria",'Rabao','Windurst Woods','Windurst Walls','Kazham',
        'Lower Jeuno',"Ru'Lude Gardens",'Port Jeuno','Upper Jeuno',
        'Aht Urhgan Whitegate','Al Zahbi','Nashmau','Tavnazian Safehold',
        'Western Adoulin','Eastern Adoulin'}) do _OW_AH_ZONES[_z] = true end

local function _ow_ah_in_zone()
    local info = windower.ffxi.get_info and windower.ffxi.get_info()
    if not (info and info.zone) then return false end
    local z = res.zones[info.zone]
    return (z and _OW_AH_ZONES[z.en]) and true or false
end

-- Spoof the AH menu open so bids work without clicking the counter NPC
-- (inject an incoming 0x04C Type 0x02, exactly as AuctionHelper does).
local function _ow_ah_open_menu()
    -- Spoof the AH menu-open (inject an incoming 0x04C Type 0x02) so buy/sell
    -- work without clicking the counter NPC -- you only need to be standing in
    -- an AH city. GATED to AH-city zones and throttled to once / 3s, exactly
    -- like Ivaar's Auctioneer: faking the menu OUTSIDE an AH city is what
    -- desyncs the client ('search failed'); inside one the server accepts the
    -- AH packets with no NPC. Use OmniWatch's own search (not the game AH
    -- menu) while this is on. Disable with //ow ah spoofmenu off.
    if not _ow_ah.spoof_menu then return end
    if not _ow_ah_in_zone() then return end
    local now = os.clock()
    if _ow_ah.menu_t and now - _ow_ah.menu_t < 3 then return end
    _ow_ah.menu_t = now
    local o = string.char(0x4C, 0x1E, 0, 0, 0x02, 0, 0x01) .. string.rep('\0', 53)
    pcall(function() windower.packets.inject_incoming(0x4C, o) end)
end

-- Ask the server for our sale slots WITHOUT opening the AH NPC: spoof the
-- menu, then send the WORK_CHECK (0x04E Cmd 0x0A, AucWorkIndex 0xFF = all
-- slots). The server replies with the 0x04C Cmd 0x0A boxes our existing
-- handler already parses. Throttled so a chatty UI can't spam the server.
local function _ow_ah_check_sales()
    if not (_ow_ah.spoof_menu and _ow_ah_in_zone()) then return end
    local now = os.clock()
    if _ow_ah.sales_t and now - _ow_ah.sales_t < 1.5 then return end
    _ow_ah.sales_t = now
    _ow_ah_open_menu()
    local req = string.char(0x4E, 0x1E, 0, 0, 0x0A, 0xFF, 0, 0) .. string.rep('\0', 52)
    pcall(function() windower.packets.inject_outgoing(0x4E, req) end)
end

function _ow_ah_emit_status()
    _ow_ah_emit('AH|status|' .. (_ow_ah.running and '1' or '0'))
end

-- epoch-guarded scheduler: stale callbacks from a prior run no-op.
local function _ow_ah_sched(fn, delay)
    local e = _ow_ah.epoch
    coroutine.schedule(function()
        if _ow_ah.running and _ow_ah.epoch == e then pcall(fn) end
    end, delay)
end

-- build + inject a bid (single by default; stack flag reserved for later).
local function _ow_ah_send_bid(item_id, price, stack)
    -- Raw byte build + inject_outgoing (the same proven mechanism as the
    -- working sell path) so a Windower packet-lib field rename can't silently
    -- zero the bid the way it just blanked the sale-slot names. Layout matches
    -- live 0x04E captures + Ivaar's Auctioneer: Type@0x04, work-index@0x05,
    -- Price(u32)@0x08, Item(u16)@0x0C, single@0x10. The work-index is the
    -- first empty sale slot (what the live client and Auctioneer send),
    -- falling back to 0x07 only when all 7 slots are in use.
    local slot = 0x07
    for i = 0, 6 do
        local sl = _ow_ah.sales and _ow_ah.sales[i]
        if not sl or not sl.status or sl.status == 'Empty' then slot = i; break end
    end
    local pr = math.floor(tonumber(price) or 0)
    local it = math.floor(tonumber(item_id) or 0)
    local single = stack and 0 or 1
    local trans = string.char(0x4E, 0x1E, 0, 0)
              .. string.char(0x0E, slot, 0, 0)
              .. string.char(pr % 256, math.floor(pr / 256) % 256,
                             math.floor(pr / 65536) % 256,
                             math.floor(pr / 16777216) % 256)
              .. string.char(it % 256, math.floor(it / 256) % 256)
              .. string.char(0, 0)
              .. string.char(single)
              .. string.rep('\0', 43)
    local ok, err = pcall(function()
        windower.packets.inject_outgoing(0x4E, trans)
    end)
    if not ok then
        _ow_ah_emit('AH|result|bid packet error: ' .. tostring(err))
    end
end

-- Map the panel's AH-style subcategories onto Windower res fields so a picked
-- category returns real items: weapon subcats -> res.skills (it.skill), armor
-- subcats -> equip slots (it.slots), Shield -> shield_size, else loose match.
local _OW_AH_SKILLCAT = {
    Archery=true, Axe=true, Club=true, Dagger=true, ['Great Axe']=true,
    ['Great Katana']=true, ['Great Sword']=true, Katana=true, Marksmanship=true,
    Polearm=true, Scythe=true, Staff=true, Sword=true, ['Hand-to-Hand']=true,
    Throwing=true,
}
local _OW_AH_SLOTCAT = {
    Head={'Head'}, Neck={'Neck'}, Body={'Body'}, Hands={'Hands'},
    Waist={'Waist'}, Legs={'Legs'}, Feet={'Feet'}, Back={'Back'},
    Earring={'Left Ear', 'Right Ear'}, Ring={'Left Ring', 'Right Ring'},
    Ammo={'Ammo'}, Instruments={'Range'},
}

-- test slot `slot_id` against it.slots, whether it's a numeric bitmask or a set
local function _ow_ah_has_slot(slots, slot_id)
    if type(slots) == 'number' then
        return math.floor(slots / (2 ^ slot_id)) % 2 >= 1
    elseif type(slots) == 'table' then
        for k, v in pairs(slots) do
            if k == slot_id or v == slot_id then return true end
        end
    end
    return false
end

-- resolve a category once into a fast per-item predicate (or nil = no filter)
-- Categories were removed from the panel; AH search is by item name only.
local function _ow_ah_make_filter(category)
    if not category or category == '' then return nil end
    local c = category:lower()
    return function(it)
        return it.en ~= nil and it.en:lower():find(c, 1, true) ~= nil
    end
end

function _ow_ah_search(query, category)
    query = (query or ''):lower()
    category = category or ''
    if query == '' and category == '' then
        _ow_ah_emit('AH|items||'); return
    end
    local catf = _ow_ah_make_filter(category)
    local out = {}
    for _, it in pairs(res.items) do
        local en = it.en
        if en and en ~= '' then
            local m = (query == '' or en:lower():find(query, 1, true) ~= nil)
            if m and (not catf or catf(it))
               and not (it.flags and it.flags['No Auction']) then
                out[#out + 1] = tostring(it.id) .. '~' .. en .. '~'
                    .. tostring(it.level or 0) .. '~' .. tostring(it.stack or 1)
            end
        end
    end
    table.sort(out, function(a, b)
        return (a:match('~([^~]*)') or '') < (b:match('~([^~]*)') or '')
    end)
    -- No fixed count cap; trim only to keep the datagram under the
    -- receiver's 64 KB buffer (rows are ~25 bytes each).
    local used, keep = #query + 16, #out
    for i = 1, #out do
        used = used + #out[i] + 1
        if used > 60000 then keep = i - 1; break end
    end
    for i = #out, keep + 1, -1 do out[i] = nil end
    _ow_ah_emit('AH|items|' .. query .. '|' .. table.concat(out, '|'))
end

-- Resolve a comma-separated list of item ids (sent by the panel's category
-- browser) to name/level/stack rows, replying in the same AH|items format the
-- search uses so the result list renders them identically.
function _ow_ah_resolve(idstr)
    local out = {}
    for tok in (tostring(idstr) .. ','):gmatch('([^,]*),') do
        local id = tonumber(tok)
        if id and res.items then
            local it = res.items[id]
            if it and it.en and it.en ~= ''
               and not (it.flags and it.flags['No Auction']) then
                out[#out + 1] = tostring(id) .. '~' .. it.en .. '~'
                    .. tostring(it.level or 0) .. '~' .. tostring(it.stack or 1)
            end
        end
    end
    table.sort(out, function(a, b)
        return (a:match('~([^~]*)') or '') < (b:match('~([^~]*)') or '')
    end)
    local used, keep = 16, #out
    for i = 1, #out do
        used = used + #out[i] + 1
        if used > 60000 then keep = i - 1; break end
    end
    for i = #out, keep + 1, -1 do out[i] = nil end
    _ow_ah_emit('AH|items||' .. table.concat(out, '|'))
end

-- resolve a bid response (called from the 0x04C handler with the raw status)
function _ow_ah_on_result(status)
    if status == 0x02 then return end          -- Placing: wait for the real result
    local q = _ow_ah.queue[_ow_ah.qi]
    _ow_ah.pending = false
    if status == 0x01 then                      -- Success
        if q then
            q.bought = (q.bought or 0) + 1
            q.status = string.format('%d/%d', q.bought, q.qty or 0)
            _ow_ah_emit(string.format('AH|result|BOUGHT %s  (%d/%d) at %d gil',
                q.name, q.bought, q.qty or 0, q.bid or 0))
            _ow_ah_emit(string.format('AH|txn|%s|%d|%d',
                q.name, q.bid or 0, os.time()))
        end
        _ow_ah_sched(_ow_ah_step, _ow_ah.throttle + math.random())
    elseif status == 0xC5 then                  -- Failed / outbid
        if q then
            q.bid = (q.bid or 0) + (q.inc or 0)
            if q.bid > (q.max or 0) then
                _ow_ah_emit(string.format('AH|result|%s hit max %d gil, moving on',
                    q.name, q.max or 0))
            else
                _ow_ah_emit(string.format('AH|result|%s outbid, raising to %d gil',
                    q.name, q.bid))
            end
        end
        _ow_ah_sched(_ow_ah_step, _ow_ah.throttle + math.random())
    elseif status == 0xE5 then                  -- Cannot Bid
        _ow_ah_emit('AH|result|cannot bid - at an AH with the menu open? gil? (stopped)')
        _ow_ah_stop()
    else
        _ow_ah_emit(string.format('AH|result|unexpected bid status 0x%02X (stopped)',
            status or 0))
        _ow_ah_stop()
    end
end

-- drive the next bid (skips finished / maxed-out items, ends when queue done)
function _ow_ah_step()
    if not _ow_ah.running or _ow_ah.pending then return end
    local q = _ow_ah.queue[_ow_ah.qi]
    while q and ((q.bought or 0) >= (q.qty or 0) or (q.bid or 0) > (q.max or 0)) do
        if (q.bought or 0) >= (q.qty or 0) then
            _ow_ah_emit(string.format('AH|result|done %s (%d/%d)',
                q.name, q.bought or 0, q.qty or 0))
        end
        _ow_ah.qi = _ow_ah.qi + 1
        q = _ow_ah.queue[_ow_ah.qi]
    end
    if not q then
        _ow_ah_emit('AH|result|queue complete')
        _ow_ah_stop(); return
    end
    _ow_ah.pending = true
    _ow_ah.pend_time = os.clock()
    _ow_ah_emit(string.format('AH|result|bidding %s at %d gil...', q.name, q.bid or 0))
    _ow_ah_send_bid(q.id, q.bid or 0, q.stack)
end

function _ow_ah_buy(throttle, itemstr)
    _ow_ah.throttle = math.max(3.0, tonumber(throttle) or 8.0)
    _ow_ah.queue = {}
    for entry in (tostring(itemstr) .. ';'):gmatch('([^;]*);') do
        if entry ~= '' then
            local f = {}
            for v in (entry .. '~'):gmatch('([^~]*)~') do f[#f+1] = v end
            local id = tonumber(f[1])
            if id then
                local nm = (res.items[id] and res.items[id].en)
                           or ('item ' .. tostring(id))
                _ow_ah.queue[#_ow_ah.queue + 1] = {
                    id = id, name = nm, qty = tonumber(f[2]) or 1,
                    start = tonumber(f[3]) or 0, max = tonumber(f[4]) or 0,
                    inc = tonumber(f[5]) or 0, bid = tonumber(f[3]) or 0,
                    bought = 0, stack = (tonumber(f[6]) == 1), status = '',
                }
            end
        end
    end
    if #_ow_ah.queue == 0 then _ow_ah_emit('AH|result|nothing queued') return end
    if not _ow_ah_in_zone() then
        _ow_ah_emit('AH|result|not in an Auction House city - move to an AH and retry')
        return
    end
    _ow_ah_open_menu()
    _ow_ah.running = true
    _ow_ah.qi = 1
    _ow_ah.pending = false
    _ow_ah.epoch = (_ow_ah.epoch or 0) + 1
    _ow_ah_emit_status()
    _ow_ah_emit('AH|result|** stand in an AH city -- the counter is auto-opened **')
    _ow_ah_emit(string.format('AH|result|starting %d item(s), throttle %.1fs',
        #_ow_ah.queue, _ow_ah.throttle))
    _ow_ah_sched(_ow_ah_step, 1.0)
end

function _ow_ah_stop()
    _ow_ah.running = false
    _ow_ah.pending = false
    _ow_ah.sell = nil
    _ow_ah.epoch = (_ow_ah.epoch or 0) + 1
    _ow_ah_emit_status()
    _ow_ah_emit('AH|result|stopped')
end

-- bid result: incoming 0x04C, Type 0x0E (offset 0x04 = Type, 0x06 = Buy Status)
windower.register_event('incoming chunk', function(id, data)
    if id ~= 0x04C then return end
    if not (_ow_ah.running and _ow_ah.pending) then return end
    if data:byte(5) ~= 0x0E then return end
    _ow_ah_on_result(data:byte(7))
end)

-- pending-timeout watchdog: never hang waiting on a missing response.
windower.register_event('prerender', function()
    if _ow_ah.running and _ow_ah.pending and _ow_ah.pend_time then
        if (os.clock() - _ow_ah.pend_time) > math.max(12, _ow_ah.throttle + 8) then
            _ow_ah_emit('AH|result|no AH response (timeout) - stopped')
            _ow_ah_stop()
        end
    end
end)

-- ── selling (2-step handshake) + sale box + sellable inventory ────────────
-- sale-stat (AuctionHelper): 0=Empty, 0x03=On auction,
-- 0x0A/0x0C/0x15=Sold, 0x0B/0x0D/0x16=Not Sold.
_ow_ah.sales = {}        -- [0..6] -> {status, item, count, price, ts}
_ow_ah.sell  = nil       -- pending sell -> {item_id, single, price, index}

local _OW_AH_SALESTAT = {
    [0x03]='On auction', [0x0A]='Sold', [0x0C]='Sold', [0x15]='Sold',
    [0x0B]='Not Sold', [0x0D]='Not Sold', [0x16]='Not Sold',
}

local function _ow_ah_u16(v)
    return string.char(v % 256, math.floor(v / 256) % 256)
end
local function _ow_ah_u32(v)
    return string.char(v % 256, math.floor(v / 256) % 256,
                       math.floor(v / 65536) % 256, math.floor(v / 16777216) % 256)
end

local function _ow_ah_emit_sales()
    local parts = {}
    for slot = 0, 6 do
        local s = _ow_ah.sales[slot]
        if s and s.status and s.status ~= 'Empty' then
            local nm = (s.item and res.items[s.item] and res.items[s.item].en) or ''
            parts[#parts + 1] = string.format('%d~%s~%s~%d~%d~%d',
                slot, s.status, nm, s.count or 0, s.price or 0, s.ts or 0)
        else
            parts[#parts + 1] = string.format('%d~Empty~~0~0~0', slot)
        end
    end
    _ow_ah_emit('AH|sales|' .. table.concat(parts, '|'))
end

local function _ow_ah_empty_slot()
    for slot = 0, 6 do
        local s = _ow_ah.sales[slot]
        if not s or s.status == 'Empty' then return slot end
    end
    return nil
end

local function _ow_ah_find_index(item_id, want)
    local inv = windower.ffxi.get_items(0)
    if not inv then return nil end
    for ind, it in ipairs(inv) do
        if it and it.id == item_id and (it.count or 0) >= want
           and (it.status == 0 or it.status == nil) then
            return ind
        end
    end
    return nil
end

-- emit the sellable inventory (distinct ids, summed counts) for the panel
function _ow_ah_inv()
    local inv = windower.ffxi.get_items(0)
    if not inv then _ow_ah_emit('AH|inv|') return end
    local totals = {}
    for _, it in ipairs(inv) do
        if it and it.id and it.id > 0 and (it.status == 0 or it.status == nil) then
            local r = res.items[it.id]
            local noah = r and r.flags
                and (r.flags['No Auction'] or r.flags['No auction'])
            if r and r.en and r.en ~= '' and not noah then
                totals[it.id] = (totals[it.id] or 0) + (it.count or 0)
            end
        end
    end
    local parts = {}
    for id, cnt in pairs(totals) do
        local r = res.items[id]
        parts[#parts + 1] = string.format('%d~%s~%d~%d', id, r.en, cnt, r.stack or 1)
    end
    table.sort(parts, function(a, b)
        return (a:match('~([^~]*)') or '') < (b:match('~([^~]*)') or '')
    end)
    _ow_ah_emit('AH|inv|' .. table.concat(parts, '|'))
end

-- send the sell request (0x04E Type 0x04)
function _ow_ah_sell(item_id, single, price)
    if not _ow_ah_in_zone() then
        _ow_ah_emit('AH|result|not in an Auction House city'); return
    end
    _ow_ah_open_menu()
    local r = res.items[item_id]
    if not r then _ow_ah_emit('AH|result|unknown item'); return end
    local want = (single == 1) and 1 or (r.stack or 1)
    local index = _ow_ah_find_index(item_id, want)
    if not index then
        _ow_ah_emit(string.format('AH|result|no %s of %s in inventory',
            single == 1 and 'single' or 'stack', r.en)); return
    end
    _ow_ah.sell = {item_id = item_id, single = single, price = price, index = index}
    local trans = string.char(0x4E, 0x1E, 0, 0)
              .. string.char(0x04, 0, 0, 0)
              .. _ow_ah_u32(price)
              .. _ow_ah_u16(index)
              .. _ow_ah_u16(item_id)
              .. string.char(single)
              .. string.rep('\0', 43)
    pcall(function() windower.packets.inject_outgoing(0x4E, trans) end)
    _ow_ah_emit(string.format('AH|result|listing %s %s at %d gil...',
        single == 1 and 'single' or 'stack', r.en, price))
end

-- confirm a successful sell (0x04E Type 0x0B) into an empty slot
local function _ow_ah_sell_confirm(slot)
    local sl = _ow_ah.sell
    if not sl then return end
    local trans = string.char(0x4E, 0x1E, 0, 0)
              .. string.char(0x0B, slot, 0, 0)
              .. _ow_ah_u32(sl.price)
              .. _ow_ah_u16(sl.index)
              .. string.char(0, 0)
              .. string.char(sl.single)
              .. string.rep('\0', 43)
    pcall(function() windower.packets.inject_outgoing(0x4E, trans) end)
end

-- sell response (Type 0x04) + sale-slot updates (Types 0x0A/0x0B/0x0C/0x0D/0x10)
windower.register_event('incoming chunk', function(id, data)
    if id ~= 0x04C then return end
    local t = data:byte(5)                       -- Type at offset 0x04
    if t == 0x04 then
        if not _ow_ah.sell then return end
        if data:byte(7) == 1 then                -- Success at offset 0x06
            local slot = _ow_ah_empty_slot()
            local fee = data:byte(9) + data:byte(10) * 256
                      + data:byte(11) * 65536 + data:byte(12) * 16777216
            local items = windower.ffxi.get_items()
            local gil = (items and items.gil) or 0
            local r = res.items[_ow_ah.sell.item_id]
            if slot and gil >= fee then
                _ow_ah_sell_confirm(slot)
                _ow_ah_emit(string.format(
                    'AH|result|LISTED %s for %d gil (fee %d, slot %d)',
                    r and r.en or 'item', _ow_ah.sell.price, fee, slot + 1))
            elseif not slot then
                _ow_ah_emit('AH|result|no empty sale slot (all 7 in use)')
            else
                _ow_ah_emit(string.format('AH|result|not enough gil for the %d fee', fee))
            end
        else
            _ow_ah_emit('AH|result|sell rejected by server')
        end
        _ow_ah.sell = nil
    elseif t == 0x0A or t == 0x0B or t == 0x0D then
        if data:byte(7) == 1 then
            local slot = data:byte(6)            -- Slot at offset 0x05
            local st = data:byte(0x15)           -- Sale status at offset 0x14
            if slot and slot <= 6 then
                if st == 0 then
                    _ow_ah.sales[slot] = {status = 'Empty'}
                elseif #data >= 0x3C then
                    -- Read GP_AUC_BOX fields at their absolute offsets instead
                    -- of via packets.parse: the Windower field names there can
                    -- shift with a lib update, which blanks the sale-slot item
                    -- names. Offsets verified against live 0x04C captures.
                    _ow_ah.sales[slot] = {
                        status = _OW_AH_SALESTAT[st] or 'On auction',
                        item  = data:byte(0x29) + data:byte(0x2A) * 256,   -- ItemNo @0x28
                        count = data:byte(0x2B),                           -- ItemQuantity @0x2A
                        price = data:byte(0x2D) + data:byte(0x2E) * 256     -- Price @0x2C
                              + data:byte(0x2F) * 65536 + data:byte(0x30) * 16777216,
                        ts    = data:byte(0x39) + data:byte(0x3A) * 256     -- TimeStamp @0x38
                              + data:byte(0x3B) * 65536 + data:byte(0x3C) * 16777216,
                    }
                else
                    _ow_ah.sales[slot] = {status = _OW_AH_SALESTAT[st] or 'On auction'}
                end
                _ow_ah_emit_sales()
            end
        end
    elseif t == 0x0C or t == 0x10 then
        if data:byte(7) == 1 then
            local slot = data:byte(6)
            if slot and slot <= 6 then
                _ow_ah.sales[slot] = {status = 'Empty'}
                _ow_ah_emit_sales()
            end
        end
    end
end)

-- ── dev packet capture: dump raw AH packets so we can decode the
-- price-history (GP_AUC_PARAM_TRANS fragments) + on-sale quantity that
-- the server actually sends.  //ow ah log on|off   writes logs/ah_capture.log
_ow_ah.capture = false   -- false | 'ah' (0x04C/0x04E) | 'all' (every packet)
_ow_ah.capcount = 0
_ow_ah.capbuf = {}       -- buffered capture lines; flushed in batches

local function _ow_ah_hexdump(s)
    local t = {}
    for i = 1, #s do t[i] = string.format('%02X', s:byte(i)) end
    return table.concat(t, ' ')
end

-- Flush buffered capture lines to disk in ONE batched write. Per-packet
-- disk I/O (open/write/close on Windower's thread) added enough latency
-- to stall the game's AH search/menu packets, so we buffer instead.
local function _ow_ah_capflush()
    local b = _ow_ah.capbuf
    if not b or #b == 0 then return end
    pcall(function()
        local f = io.open(ow_user_config_dir() .. '/ah_capture.log', 'a')
        if not f then return end
        f:write(table.concat(b))
        f:close()
        _ow_ah.capbuf = {}
    end)
end

local function _ow_ah_caplog(dir, id, data)
    -- Cheap path only: build the text and buffer it. No disk I/O here.
    local b = _ow_ah.capbuf
    if not b then b = {}; _ow_ah.capbuf = b end
    local cmd = data:byte(5) or 0          -- Command (offset 0x04)
    local res = data:byte(7) or 0          -- Result  (offset 0x06, S->C)
    -- Tag the AH channel so it stands out amid all-packet noise; seq + ms
    -- let a capture line be tied to a //ow ah mark dropped in-game.
    local tag = (id == 0x04C or id == 0x04E) and '*AH* ' or '     '
    _ow_ah.capcount = (_ow_ah.capcount or 0) + 1
    b[#b + 1] = string.format('[%s.%03d #%d] %s%-4s 0x%03X len=%-3d Cmd=0x%02X Res=0x%02X\n  %s\n',
        os.date('%H:%M:%S'), math.floor((os.clock() % 1) * 1000),
        _ow_ah.capcount, tag, dir, id, #data, cmd, res, _ow_ah_hexdump(data))
    if #b >= 400 then _ow_ah_capflush() end
end

windower.register_event('incoming chunk', function(id, data)
    local m = _ow_ah.capture
    if m == 'all' or (m and id == 0x04C) then _ow_ah_caplog('S->C', id, data) end
end)
windower.register_event('outgoing chunk', function(id, data)
    local m = _ow_ah.capture
    if m == 'all' or (m and id == 0x04E) then _ow_ah_caplog('C->S', id, data) end
end)

-- ── item info for hover tooltips (what am I buying/selling) ───────────────
-- jobs/slots are Windower Sets at runtime (keys = numeric ids). Doing
-- arithmetic on the Set crashed; iterate it instead. Accept a number too.
local function _ow_ah_set_ids(v)
    local out = {}
    if type(v) == 'table' then
        for k, val in pairs(v) do
            if val and type(k) == 'number' then out[#out + 1] = k end
        end
    elseif type(v) == 'number' then
        for i = 0, 31 do
            if math.floor(v / (2 ^ i)) % 2 >= 1 then out[#out + 1] = i end
        end
    end
    table.sort(out)
    return out
end

local function _ow_ah_jobs_str(jobs)
    local ids = _ow_ah_set_ids(jobs)
    if #ids == 0 then return '' end
    if #ids >= 20 then return 'All Jobs' end
    local names = {}
    for _, jid in ipairs(ids) do
        local j = res.jobs and res.jobs[jid]
        names[#names + 1] = (j and (j.ens or j.en)) or ('?' .. jid)
    end
    return table.concat(names, ' ')
end

local function _ow_ah_slots_str(slots)
    local ids = _ow_ah_set_ids(slots)
    if #ids == 0 then return '' end
    local out = {}
    for _, sid in ipairs(ids) do
        local s = res.slots and res.slots[sid]
        out[#out + 1] = (s and (s.en or s.ens)) or ('slot' .. sid)
    end
    return table.concat(out, '/')
end

local function _ow_ah_races_str(races)
    local ids = _ow_ah_set_ids(races)
    if #ids == 0 then return '' end
    if #ids >= 8 then return 'All Races' end
    local names = {}
    for _, rid in ipairs(ids) do
        local r = res.races and res.races[rid]
        names[#names + 1] = (r and (r.ens or r.en)) or ('?' .. rid)
    end
    return table.concat(names, ' ')
end

local function _ow_ah_targets_str(targets)
    if type(targets) ~= 'table' then return '' end
    local out = {}
    for k, v in pairs(targets) do
        if v and type(k) == 'string' then out[#out + 1] = k end
    end
    return table.concat(out, '/')
end

function _ow_ah_iteminfo(id)
    id = tonumber(id)
    local it = id and res.items[id]
    if not it then return end
    -- Full in-game stat text (DMG/Delay/bonuses/WS/effects/flavor), keyed by
    -- item id, from Windower's item_descriptions resource -- covers EVERY item,
    -- not just ones you own. res.item_descriptions lazy-loads on first access.
    local desc = nil
    pcall(function()
        local d = res.item_descriptions and res.item_descriptions[id]
        if d and d.en and d.en ~= '' then desc = d.en end
    end)
    local lines = {}
    lines[#lines + 1] = it.en or ('item ' .. tostring(id))
    -- line 2: (Category/Skill) Races Lv.X
    local l2 = '(' .. (it.category or '?') .. ')'
    local sk = it.skill and it.skill > 0 and res.skills and res.skills[it.skill]
    if sk and sk.en then l2 = l2 .. ' ' .. sk.en end
    local races = _ow_ah_races_str(it.races)
    if races ~= '' then l2 = l2 .. ' ' .. races end
    if it.level and it.level > 0 then l2 = l2 .. ' Lv.' .. it.level end
    lines[#lines + 1] = l2
    -- usable jobs
    local jobs = _ow_ah_jobs_str(it.jobs)
    if jobs ~= '' then lines[#lines + 1] = jobs end
    if desc then
        -- full stat block (preferred): split the description into lines,
        -- sanitising the emit separators out of each.
        for line in (desc .. '\n'):gmatch('([^\n]*)\n') do
            line = line:gsub('[~|\r]', ' '):gsub('%s+$', '')
            if line ~= '' then lines[#lines + 1] = line end
        end
    else
        -- fallback to res.items numbers when no description text exists
        if it.damage and it.delay and it.delay > 0 then
            lines[#lines + 1] = string.format('DMG:%d  Delay:%d  (DPS %.1f)',
                it.damage, it.delay, it.damage * 60 / it.delay)
        elseif it.damage and it.damage > 0 then
            lines[#lines + 1] = 'DMG:' .. it.damage
        elseif it.defense and it.defense > 0 then
            lines[#lines + 1] = 'DEF:' .. it.defense
        end
    end
    -- equip slot (structural; not in the description text)
    local slots = _ow_ah_slots_str(it.slots)
    if slots ~= '' then lines[#lines + 1] = 'Slot: ' .. slots end
    -- usable cast/target only when there's no description (desc covers usables)
    if not desc then
        if it.cast_time and it.cast_time > 0 then
            lines[#lines + 1] = string.format('Cast: %ds', it.cast_time)
        end
        local tgt = _ow_ah_targets_str(it.targets)
        if tgt ~= '' and tgt ~= 'Self' then lines[#lines + 1] = 'Target: ' .. tgt end
    end
    -- stack + id
    if (it.stack or 1) > 1 then lines[#lines + 1] = 'Stacks to ' .. it.stack end
    lines[#lines + 1] = 'Item #' .. id
    _ow_ah_emit('AH|info|' .. id .. '|' .. table.concat(lines, '~'))
end

-- ---------------------------------------------------------------------------
--  Puppetmaster attachment engine
--  Builds the automaton parts catalogue from Windower resources, reads the
--  live loadout via get_mjob_data(), and equips a named set with the native
--  windower.ffxi.set_attachment / reset_attachments calls (paced, like the
--  AutoControl addon by Ricky Gall). Drives the overlay's PUP Attachments
--  panel over the inventory channel. PUP main only; pet must be despawned.
-- ---------------------------------------------------------------------------
do
    local PUP_JOB    = 18
    local STEP_DELAY = 0.6          -- seconds between attachment writes
    local catalog    = nil          -- { heads=, frames=, atts= } cache
    local queue      = {}           -- pending equip steps
    local busy       = false

    local function emit(payload)
        pcall(function() udp_inv:send(_OW_MB_TAG(payload)) end)
    end

    local function each_automaton(fn)
        local ok = pcall(function()
            for id, it in pairs(res.items:category('Automaton')) do fn(id, it) end
        end)
        if not ok then
            for id, it in pairs(res.items) do
                if type(it) == 'table' and it.category == 'Automaton' then fn(id, it) end
            end
        end
    end

    -- Classify an Automaton-category item by name (head / frame / attachment).
    local function kind_of(name)
        local low = (name or ''):lower()
        if low:find('head', 1, true)  then return 'head'  end
        if low:find('frame', 1, true) then return 'frame' end
        return 'att'
    end

    local function build_catalog()
        local heads, frames, atts = {}, {}, {}
        each_automaton(function(id, it)
            local nm = it.name or it.en or ('item ' .. id)
            local rec = { id = id, name = nm }
            local k = kind_of(nm)
            if     k == 'head'  then heads[#heads + 1]   = rec
            elseif k == 'frame' then frames[#frames + 1] = rec
            else                     atts[#atts + 1]     = rec end
        end)
        local byname = function(a, b) return a.name < b.name end
        table.sort(heads, byname)
        table.sort(frames, byname)
        table.sort(atts, byname)
        catalog = { heads = heads, frames = frames, atts = atts }
        return catalog
    end

    local function emit_section(tag, list)
        local parts = { 'PUPATT', 'cat', tag }
        for _, r in ipairs(list) do parts[#parts + 1] = r.id .. '=' .. r.name end
        emit(table.concat(parts, '|'))
    end

    local function emit_catalog()
        local c = catalog or build_catalog()
        emit_section('head',  c.heads)
        emit_section('frame', c.frames)
        emit_section('att',   c.atts)
        emit('PUPATT|cat|end')
    end

    local function emit_current()
        local pl = windower.ffxi.get_player()
        if not pl or pl.main_job_id ~= PUP_JOB or not windower.ffxi.get_mjob_data then
            emit('PUPATT|current|none')
            return
        end
        local d = windower.ffxi.get_mjob_data()
        if not d then emit('PUPATT|current|none'); return end
        local a = d.attachments or {}
        local parts = { 'PUPATT', 'current', tostring(d.head or 0), tostring(d.frame or 0) }
        for i = 1, 12 do parts[#parts + 1] = tostring(a[i] or 0) end
        emit(table.concat(parts, '|'))
    end

    local function pet_is_out()
        local pet = windower.ffxi.get_mob_by_target('pet')
        return pet ~= nil and pet.id ~= nil and pet.id ~= 0
    end

    local function step()
        local sstep = table.remove(queue, 1)
        if not sstep then
            busy = false
            emit('PUPATT|status|Equip complete.')
            coroutine.schedule(emit_current, 0.5)
            return
        end
        pcall(function()
            if sstep.kind == 'reset' then
                windower.ffxi.reset_attachments()
            elseif sstep.kind == 'head' or sstep.kind == 'frame' then
                windower.ffxi.set_attachment(sstep.id)
            else
                windower.ffxi.set_attachment(sstep.id, sstep.slot)
            end
        end)
        coroutine.schedule(step, STEP_DELAY)
    end

    local function guard()
        local pl = windower.ffxi.get_player()
        if not pl or pl.main_job_id ~= PUP_JOB then
            emit('PUPATT|status|Switch to PUP main to change attachments.')
            return false
        end
        if pet_is_out() then
            emit('PUPATT|status|Despawn your automaton first, then try again.')
            return false
        end
        return true
    end

    local function equip(ids)
        if not guard() then return end
        if busy then emit('PUPATT|status|Still applying the previous set...'); return end
        queue = { { kind = 'reset' } }
        local head, frame = tonumber(ids[1]) or 0, tonumber(ids[2]) or 0
        if head  > 0 then queue[#queue + 1] = { kind = 'head',  id = head  } end
        if frame > 0 then queue[#queue + 1] = { kind = 'frame', id = frame } end
        for slot = 1, 12 do
            local aid = tonumber(ids[2 + slot]) or 0
            if aid > 0 then queue[#queue + 1] = { kind = 'att', id = aid, slot = slot } end
        end
        busy = true
        emit('PUPATT|status|Applying set...')
        coroutine.schedule(step, 0.2)
    end

    local function clear_all()
        if not guard() then return end
        pcall(function() windower.ffxi.reset_attachments() end)
        emit('PUPATT|status|Attachments cleared.')
        coroutine.schedule(emit_current, 0.5)
    end

    -- Global entry point routed from the //ow dispatcher.
    function _ow_pupatt_command(rest)
        local a = {}
        for tok in (tostring(rest) .. '|'):gmatch('([^|]*)|') do a[#a + 1] = tok end
        local cmd = (a[1] or ''):lower()
        if cmd == 'catalog' then
            build_catalog(); emit_catalog()
        elseif cmd == 'current' then
            emit_current()
        elseif cmd == 'equip' then
            local ids = {}
            for i = 2, 15 do ids[i - 1] = a[i] end
            equip(ids)
        elseif cmd == 'clear' then
            clear_all()
        elseif cmd == 'sync' then
            build_catalog(); emit_catalog()
            coroutine.schedule(emit_current, 0.3)
        end
    end
end

-- ---------------------------------------------------------------------------
--  Bard song-set singer
--  Drives a saved rotation from the overlay's BRD Loadouts tab: fires the
--  toggled job abilities (Clarion Call / Troubadour / Nightingale / Soul
--  Voice), then sings each song in listed order, timing the next cast off the
--  incoming 0x028 magic-finish action packet (category 4, actor = me, param =
--  the song's spell id). A timeout -> retry -> skip fallback keeps it from
--  stalling on a missed packet or an interrupt. Marcato'd songs get the JA
--  first. Dummy/FullLength/Cheer steps are sent to GearSwap as their *Lock*
--  variants so the mode is held for the whole rotation instead of auto-
--  resetting between casts. BRD main or sub only.
-- ---------------------------------------------------------------------------
-- ── BRD song-gear (OmniWatch self-equip) config ─────────────────────────────
-- Optional path for bards who do NOT run a GearSwap that exposes
-- ExtraSongsMode (Selindrile/Mote style). When source == 'omniwatch' the
-- singer equips a configured gear set per song mode itself (via
-- windower.ffxi.set_equip) instead of handing the mode to GearSwap. Kept in
-- its OWN per-character file so the //ow setup wizard's user_config rewrite
-- can never clobber it.
--
-- UNTESTED: the addon author uses Selindrile's GearSwap (source =
-- 'gearswap'), so this self-equip path ships unverified. Default 'gearswap'
-- preserves the original behavior exactly.
function ow_brd_songgear_path()
    return ow_user_config_dir() .. '/brd_songgear.lua'
end

function ow_load_brd_songgear()
    local cfg = nil
    local ok, chunk = pcall(loadfile, ow_brd_songgear_path())
    if ok and chunk then
        local ok2, data = pcall(chunk)
        if ok2 and type(data) == 'table' then cfg = data end
    end
    if type(cfg) ~= 'table' then cfg = {} end
    cfg.source = (type(cfg.source) == 'string') and cfg.source:lower() or 'gearswap'
    if cfg.source ~= 'omniwatch' then cfg.source = 'gearswap' end
    if type(cfg.sets) ~= 'table' then cfg.sets = {} end
    return cfg
end

function ow_save_brd_songgear(cfg)
    ow_ensure_user_config_dir()
    local f = io.open(ow_brd_songgear_path(), 'w')
    if not f then return false end
    local src = (cfg and cfg.source == 'omniwatch') and 'omniwatch' or 'gearswap'
    f:write('-- OmniWatch BRD song-gear config (//ow brdgear ...)\n')
    f:write('-- source: gearswap (default) or omniwatch (self-equip; UNTESTED)\n')
    f:write('return {\n')
    f:write(string.format('    source = %q,\n', src))
    f:write('    sets = {\n')
    local SLOT_ORDER = { 'main','sub','range','ammo','head','body','hands',
        'legs','feet','neck','waist','left_ear','right_ear','left_ring',
        'right_ring','back' }
    local seen = {}
    local function emit_mode(m)
        local set = cfg and cfg.sets and cfg.sets[m]
        if type(set) ~= 'table' then return end
        seen[m] = true
        f:write(string.format('        %s = {\n', m))
        local emitted = {}
        for _, sl in ipairs(SLOT_ORDER) do
            local v = set[sl]
            if type(v) == 'string' and v ~= '' then
                emitted[sl] = true
                f:write(string.format('            %-11s = %q,\n', sl, v))
            end
        end
        for k, v in pairs(set) do
            if not emitted[k] and type(v) == 'string' and v ~= '' then
                f:write(string.format('            [%q] = %q,\n', tostring(k), v))
            end
        end
        f:write('        },\n')
    end
    for _, m in ipairs({ 'none','dummy','fulllength','cheer' }) do emit_mode(m) end
    if cfg and type(cfg.sets) == 'table' then
        for m, _ in pairs(cfg.sets) do if not seen[m] then emit_mode(m) end end
    end
    f:write('    },\n')
    f:write('}\n')
    f:close()
    return true
end

function ow_write_brd_songgear_template_if_missing()
    local existing = io.open(ow_brd_songgear_path(), 'r')
    if existing then existing:close(); return false end
    ow_ensure_user_config_dir()
    local f = io.open(ow_brd_songgear_path(), 'w')
    if not f then return false end
    f:write([==[-- OmniWatch BRD song-gear config
--
-- source:
--   'gearswap'  (default) hand each song mode to your GearSwap via
--               `gs c set extrasongsmode <mode>` (Lock variant). Use this if
--               you run a Selindrile/Mote-style BRD GearSwap.
--   'omniwatch' OmniWatch equips the per-mode 'sets' below itself, so
--               dummy / fulllength / cheer work WITHOUT any GearSwap.
--               UNTESTED -- the addon author uses GearSwap, so verify it does
--               what you expect before relying on it.
--
-- 'sets' is only used when source = 'omniwatch'. Each mode maps a slot to the
-- exact in-game (English) item name. List only the slots that change for that
-- mode -- commonly just the instrument in 'range'; unlisted slots keep what
-- you are already wearing. Your gear when the rotation started is restored
-- when singing finishes or is stopped.
-- Slots: main sub range ammo head body hands legs feet neck waist
--        left_ear right_ear left_ring right_ring back
-- Items are matched by name to the first copy found in your bags; augment-
-- specific copies are not distinguished.
return {
    source = 'gearswap',
    sets = {
        -- dummy      = { range = 'Daurdabla' },
        -- fulllength = { range = 'Daurdabla' },
        -- cheer      = { range = 'Marsyas' },
        -- none       = { range = 'Gjallarhorn' },
    },
}
]==])
    f:close()
    return true
end

do
    local BRD_JOB = 10
    -- Timing knobs. SETTLE is the gap after a song's cast FINISHES
    -- (category-4 action) before the next /ma; songs chain back-to-back in
    -- game so 0.3 is enough not to outrun the client. JA_DELAY / MARCATO_DELAY
    -- are the waits after a job ability (Nightingale/Troubadour/Soul Voice)
    -- and after Marcato: FFXI enforces a ~1-second lockout between job
    -- abilities, so 1.0 is the practical floor -- lower and chained JAs at the
    -- start of a rotation can get dropped. If you see a JA skipped on higher
    -- latency, nudge these back to 1.1-1.2.
    local SETTLE, JA_DELAY, MARCATO_DELAY, MODE_DELAY, SONG_TIMEOUT, MAX_RETRY =
        0.3, 1.3, 1.3, 0.5, 9.0, 2
    local IDLE_MODE = 'none'   -- extrasongsmode restored after a rotation/stop
    local st = { active = false, steps = {}, idx = 1, wait_sid = nil,
                 wait_idx = 0, retries = 0, skip_dummies = false, token = 0 }
    -- Push run state to the overlay so its Sing/Stop button is a true
    -- toggle (flips back when a rotation finishes or stops on its own).
    local function push_state(s)
        pcall(function()
            if _G._ow_udp_inv and _OW_MB_TAG then
                _G._ow_udp_inv:send(_OW_MB_TAG('BRDSET|state|' .. s))
            end
        end)
    end
    local song_ids, song_buffs = nil, nil

    local function emit_chat(msg) ow_chat(121, '[BRD] ' .. msg) end

    -- BRD song-gear self-equip (source == 'omniwatch'); see
    -- ow_load_brd_songgear. st.song_gear holds the config for the current
    -- rotation; st.song_equip_snap holds the pre-rotation equipment to put
    -- back when singing ends. UNTESTED path (author uses GearSwap).
    local _SONG_EQUIP_SLOTS = {
        main = 0, sub = 1, range = 2, ranged = 2, ammo = 3, head = 4,
        body = 5, hands = 6, legs = 7, feet = 8, neck = 9, waist = 10,
        left_ear = 11, ear1 = 11, right_ear = 12, ear2 = 12,
        left_ring = 13, ring1 = 13, right_ring = 14, ring2 = 14, back = 15,
    }
    local _SONG_SLOT_NAMES = {
        'main','sub','range','ammo','head','body','hands','legs','feet',
        'neck','waist','left_ear','right_ear','left_ring','right_ring','back',
    }

    local function song_gear_source()
        return (st.song_gear and st.song_gear.source) or 'gearswap'
    end

    local function song_equip_one(slot_name, item_name)
        if not (windower.ffxi and windower.ffxi.set_equip) then return end
        local slot_id = _SONG_EQUIP_SLOTS[tostring(slot_name):lower()]
        if not slot_id then return end
        if type(item_name) ~= 'string' or item_name == '' then return end
        local item = res.items and (res.items:with('en', item_name)
                                     or res.items:with('enl', item_name))
        local iid = item and item.id
        if not iid then
            emit_chat('song gear: item not found - "' .. item_name .. '".')
            return
        end
        local loc = (type(_ow_get_item_loc) == 'function') and _ow_get_item_loc(iid) or nil
        if not loc then
            emit_chat('song gear: "' .. item_name .. '" not in your bags.')
            return
        end
        pcall(windower.ffxi.set_equip, slot_id, loc.idx, loc.bag)
    end

    local function song_equip_set(mode)
        local sets = st.song_gear and st.song_gear.sets
        local set = sets and sets[tostring(mode):lower()]
        if type(set) ~= 'table' then return end
        for slot_name, item_name in pairs(set) do
            song_equip_one(slot_name, item_name)
        end
    end

    local function song_snapshot_equip()
        local snap = nil
        pcall(function()
            local items = windower.ffxi.get_items and windower.ffxi.get_items()
            local eq = items and items.equipment
            if not eq then return end
            snap = {}
            for _, sl in ipairs(_SONG_SLOT_NAMES) do
                snap[sl] = { idx = tonumber(eq[sl]) or 0,
                             bag = tonumber(eq[sl .. '_bag']) or 0 }
            end
        end)
        return snap
    end

    local function song_restore_equip()
        local snap = st.song_equip_snap
        if not snap or not (windower.ffxi and windower.ffxi.set_equip) then return end
        for _, sl in ipairs(_SONG_SLOT_NAMES) do
            local loc = snap[sl]
            local slot_id = _SONG_EQUIP_SLOTS[sl]
            if slot_id and loc and (tonumber(loc.idx) or 0) > 0 then
                pcall(windower.ffxi.set_equip, slot_id, loc.idx, loc.bag)
            end
        end
    end

    local function build_song_ids()
        song_ids = {}
        for id, sp in pairs(res.spells) do
            if type(sp) == 'table' and sp.name then song_ids[sp.name] = id end
        end
    end

    local function build_song_buffs()
        song_buffs = {}
        for _, sp in pairs(res.spells) do
            if type(sp) == 'table' and sp.type == 'BardSong' and sp.status then
                song_buffs[sp.status] = true
            end
        end
    end

    local function active_song_count()
        local pl = windower.ffxi.get_player()
        if not pl or not pl.buffs then return 0 end
        if not song_buffs then build_song_buffs() end
        local n = 0
        for _, b in ipairs(pl.buffs) do if song_buffs[b] then n = n + 1 end end
        return n
    end

    local function ja(name) windower.chat.input('/ja "' .. name .. '" <me>') end
    local function ma(name) windower.chat.input('/ma "' .. name .. '" <me>') end

    local do_step, song_timeout    -- forward declarations

    do_step = function()
        if not st.active then return end
        local step = st.steps[st.idx]
        if not step then
            st.active = false
            if song_gear_source() == 'omniwatch' then
                song_restore_equip()
            else
                windower.send_command('gs c set extrasongsmode ' .. IDLE_MODE)
            end
            push_state('idle')
            emit_chat('Rotation complete.')
            return
        end
        if step.kind == 'ja' then
            ja(step.name)
            st.idx = st.idx + 1
            coroutine.schedule(do_step, JA_DELAY)
        elseif step.kind == 'mode' then
            -- Keep the panel labels (none/dummy/fulllength/cheer) as-is, but
            -- send the *Lock* variant to GearSwap for dummy/fulllength/cheer so
            -- the mode is held for the whole rotation. The BRD.lua resets
            -- ExtraSongsMode after any non-Lock cast, which desyncs a multi-
            -- song rotation and drops a song. 'none' has no Lock variant and
            -- needs no hold, so it is sent unchanged.
            local _ml = tostring(step.mode):lower()
            if song_gear_source() == 'omniwatch' then
                -- OmniWatch owns equipment: equip the configured set for this
                -- mode itself, no GearSwap dependency. UNTESTED path.
                song_equip_set(_ml)
            else
                local _send_mode = step.mode
                if _ml == 'dummy' or _ml == 'fulllength' or _ml == 'cheer' then
                    _send_mode = _ml .. 'lock'
                end
                windower.send_command('gs c set extrasongsmode ' .. _send_mode)
            end
            st.idx = st.idx + 1
            coroutine.schedule(do_step, MODE_DELAY)
        elseif step.kind == 'marcato' then
            ja('Marcato')
            st.idx = st.idx + 1
            coroutine.schedule(do_step, MARCATO_DELAY)
        else
            -- (Dummy-skip removed: dummies are always cast now. The old
            -- "skip dummies when >4 songs up" guard was dropping a step and
            -- leaving 3 songs instead of 4 in overwrite rotations.)
            local sid = song_ids and song_ids[step.name]
            if not sid then
                emit_chat('Unknown song "' .. tostring(step.name) .. '" - skipped.')
                st.idx = st.idx + 1
                return do_step()
            end
            st.wait_sid = sid
            st.wait_idx = st.idx
            ma(step.name)
            local tok, widx = st.token, st.idx
            coroutine.schedule(function() song_timeout(tok, widx) end, SONG_TIMEOUT)
        end
    end

    song_timeout = function(tok, widx)
        if not st.active or st.token ~= tok then return end
        if st.wait_idx ~= widx or st.wait_sid == nil then return end
        if st.retries < MAX_RETRY then
            st.retries = st.retries + 1
            emit_chat('No finish for "' .. st.steps[widx].name
                      .. '" - retry ' .. st.retries .. '.')
            st.wait_sid = nil
            do_step()
        else
            emit_chat('Skipping "' .. st.steps[widx].name
                      .. '" after ' .. MAX_RETRY .. ' retries.')
            st.retries = 0
            st.wait_sid = nil
            st.idx = st.idx + 1
            do_step()
        end
    end

    windower.register_event('action', function(act)
        if not st.active or not st.wait_sid then return end
        if act.category == 4 then
            local pl = windower.ffxi.get_player()
            if pl and act.actor_id == pl.id and act.param == st.wait_sid then
                st.wait_sid = nil
                st.retries = 0
                st.idx = st.idx + 1
                coroutine.schedule(do_step, SETTLE)
            end
        end
    end)

    -- Global entry point routed from the BRDSET| rail (overlay Sing/Stop).
    function _ow_brdset_command(rest)
        local a = {}
        for tok in (tostring(rest) .. '|'):gmatch('([^|]*)|') do a[#a + 1] = tok end
        local cmd = (a[1] or ''):lower()
        if cmd == 'stop' then
            if st.active then
                st.active = false
                st.token = st.token + 1
                if song_gear_source() == 'omniwatch' then
                    song_restore_equip()
                else
                    windower.send_command('gs c set extrasongsmode ' .. IDLE_MODE)
                end
                push_state('idle')
                emit_chat('Singing stopped.')
            end
            return
        end
        if cmd ~= 'sing' then return end
        local pl = windower.ffxi.get_player()
        if not pl or (pl.main_job_id ~= BRD_JOB and pl.sub_job_id ~= BRD_JOB) then
            emit_chat('Switch to BRD (main or sub) to sing.')
            push_state('idle')
            return
        end
        if st.active then
            emit_chat('Already singing - stop first.')
            return
        end
        if not song_ids then build_song_ids() end
        local steps = {}
        if a[3] == '1' then steps[#steps + 1] = { kind = 'ja', name = 'Clarion Call' } end
        if a[5] == '1' then steps[#steps + 1] = { kind = 'ja', name = 'Troubadour' } end
        if a[4] == '1' then steps[#steps + 1] = { kind = 'ja', name = 'Nightingale' } end
        if a[2] == '1' then steps[#steps + 1] = { kind = 'ja', name = 'Soul Voice' } end
        local last_mode = nil
        for i = 6, #a do
            local tok = a[i]
            if tok ~= '' then
                local nm, mode, mar = tok:match('^(.-)%^(.-)%^(.-)$')
                if nm and nm ~= '' then
                    if mode == nil or mode == '' then mode = 'fulllength' end
                    if mode ~= last_mode then
                        steps[#steps + 1] = { kind = 'mode', mode = mode }
                        last_mode = mode
                    end
                    if mar == '1' then steps[#steps + 1] = { kind = 'marcato' } end
                    steps[#steps + 1] =
                        { kind = 'song', name = nm, dummy = (mode == 'dummy') }
                end
            end
        end
        if #steps == 0 then emit_chat('Set is empty.'); push_state('idle'); return end
        st.steps = steps
        st.idx = 1
        st.retries = 0
        st.wait_sid = nil
        st.token = st.token + 1
        st.skip_dummies = false   -- dummy-skip removed; always cast dummies
        st.song_gear = ow_load_brd_songgear()   -- per-rotation: picks up edits
        st.song_equip_snap = nil
        if st.song_gear.source == 'omniwatch' then
            st.song_equip_snap = song_snapshot_equip()
        end
        st.active = true
        push_state('singing')
        emit_chat('Singing ' .. #steps .. ' step(s)...')
        do_step()
    end
end

function _ow_ah_command(rest)
    local a = {}
    for tok in (tostring(rest) .. '|'):gmatch('([^|]*)|') do a[#a+1] = tok end
    local cmd = (a[1] or ''):lower()
    if cmd == 'search' then
        _ow_ah_search(a[2] or '', a[3] or '')
    elseif cmd == 'resolve' then
        _ow_ah_resolve(a[2] or '')
    elseif cmd == 'buy' then
        _ow_ah_buy(a[2], a[3])
    elseif cmd == 'stop' then
        _ow_ah_stop()
    elseif cmd == 'sell' then
        _ow_ah_sell(tonumber(a[2]), tonumber(a[3]) or 1, tonumber(a[4]) or 0)
    elseif cmd == 'inv' then
        _ow_ah_inv()
    elseif cmd == 'sales' then
        _ow_ah_check_sales()   -- refresh from server (async boxes arrive + re-emit)
        _ow_ah_emit_sales()    -- send the current cache immediately
    elseif cmd == 'info' then
        _ow_ah_iteminfo(a[2])
    elseif cmd == 'mark' then
        -- Drop a labelled marker into the capture stream so a given action
        -- (e.g. "view price history") ties to the packets it produced.
        local label = table.concat(a, ' ', 2)
        if label == '' then label = '(unlabeled)' end
        if _ow_ah.capture then
            local b = _ow_ah.capbuf
            if not b then b = {}; _ow_ah.capbuf = b end
            _ow_ah.capcount = (_ow_ah.capcount or 0) + 1
            b[#b + 1] = string.format('\n==== MARK %s.%03d #%d: %s ====\n',
                os.date('%H:%M:%S'), math.floor((os.clock() % 1) * 1000),
                _ow_ah.capcount, label)
            if windower and windower.add_to_chat then
                ow_chat(207, '[OmniWatch][AH] mark: ' .. label)
            end
        elseif windower and windower.add_to_chat then
            ow_chat(167, '[OmniWatch][AH] start capture first: //ow ah log on')
        end
    elseif cmd == 'log' then
        local on = (a[2] or ''):lower()
        -- 'on' now captures EVERYTHING (the price history is not on the AH
        -- channel, so AH-only mode misses it). 'ah' stays as an explicit opt-in.
        if on == 'off' then _ow_ah.capture = false
        elseif on == 'ah' then _ow_ah.capture = 'ah'
        elseif on == 'on' or on == 'all' then _ow_ah.capture = 'all'
        else _ow_ah.capture = _ow_ah.capture and false or 'all' end
        local where = ow_user_config_dir() .. '/ah_capture.log'
        if _ow_ah.capture then
            pcall(function()
                ow_ensure_user_config_dir()
                local f = io.open(where, 'a')
                if f then
                    f:write(string.format('==== capture started %s ====\n',
                        os.date('%Y-%m-%d %H:%M:%S')))
                    f:close()
                end
            end)
        end
        if _ow_ah.capture then
            _ow_ah.capcount = 0
            _ow_ah.capbuf = {}
        else
            _ow_ah_capflush()
        end
        local mode = (_ow_ah.capture == 'all') and 'ALL packets' or 'AH only'
        local msg = 'AH packet capture ' .. (_ow_ah.capture
            and (mode .. ' -> ' .. where)
            or ('OFF (' .. tostring(_ow_ah.capcount or 0) .. ' packets captured)'))
        if windower and windower.add_to_chat then
            ow_chat(207, '[OmniWatch] ' .. msg)
            if _ow_ah.capture then
                ow_chat(207, '[OmniWatch] before each action: //ow ah mark <label>  (e.g. //ow ah mark view price history)')
            end
        end
        _ow_ah_emit('AH|result|' .. msg)
    elseif cmd == 'spoofmenu' then
        _ow_ah.spoof_menu = ((a[2] or ''):lower() == 'on')
        _ow_ah_emit('AH|result|menu-open spoof '
            .. (_ow_ah.spoof_menu and 'ON (risky)' or 'OFF'))
    elseif cmd == 'status' then
        _ow_ah_emit_status()
    end
end


end  -- close SkillUp+AH engine scope (Lua 200-local cap)

local function _ow_drain_inbound()
    if not udp_cmd_in then return end
    local guard = 64    -- max packets per drain (defensive)
    while guard > 0 do
        guard = guard - 1
        local data, err = udp_cmd_in:receive()
        if not data then break end       -- 'timeout' = empty queue, normal exit

        -- Split first field (header) off; rest is per-message payload.
        local sep = data:find('|', 1, true)
        local head = sep and data:sub(1, sep - 1) or data
        local rest = sep and data:sub(sep + 1) or ''

        if head == 'SIM_MODE' then
            if _sim then
                local turning_on = (rest == 'on')
                _sim.set_active(turning_on)
                -- When sim turns on, send a fresh inventory snapshot at
                -- the next prerender tick. Reset the 1 Hz snapshot gate so
                -- the EQUIPPED seed fires immediately rather than waiting
                -- up to a second (the cause of "current gear didn't load
                -- until I reopened sim").
                if turning_on and _ow_force_inv_resend then
                    _ow_force_inv_resend()
                end
                -- When sim turns OFF, force the live-stats path to fully
                -- recompute on its next tick. The 1 Hz live gate only
                -- recomputes when a signature CHANGES; right after closing
                -- sim while idle, live gear/buffs haven't changed since
                -- before sim, so the gate would see "no change" and leave
                -- the stale SIM stats on the panel until something moved
                -- (which is why it only fixed itself on reopen). Invalidate
                -- the signature caches so every check trips → full resend of
                -- real stats + equipment immediately.
                if not turning_on then
                    _ow_stats_last_full    = nil   -- trips the 30s force-full
                    _ow_stats_last_job     = nil   -- trips the job check
                    _ow_stats_last_hastesig = nil  -- trips the haste check
                    _ow_stats_last_buffsig = nil   -- trips the any-buff check
                    _ow_stats_last_blusetsig = nil -- trips the BLU set-spell check
                    -- (last_stats_send is a file-local declared after this
                    -- function, so we can't reset it here — but the next
                    -- 1 Hz tick is at most ~1s away and the invalidated
                    -- signatures above force it to a full recompute then.)
                    if _ow_mark_inv_dirty then
                        _ow_mark_inv_dirty()       -- re-push live equipment
                    end
                end
            end
        elseif head == 'SIM_IMPORT' then
            -- Import a named set from an arbitrary gear file into the sim.
            -- Wire form: SIM_IMPORT|<filepath>|<setpath>
            -- Filepath may contain spaces/backslashes but not '|'. Setpath
            -- is the trailing field (everything after the first '|' in the
            -- payload, split once more at the LAST '|' so a setpath can't be
            -- confused with a path that contains '|' — paths shouldn't).
            local s1 = rest:find('|', 1, true)
            if s1 and _sim and _sim.import_set then
                local fpath = rest:sub(1, s1 - 1)
                local spath = rest:sub(s1 + 1)
                local ok_imp, err_imp = pcall(_sim.import_set, fpath, spath)
                if not ok_imp then
                    ow_chat(123,
                        '[OmniWatch] sim import error: ' .. tostring(err_imp))
                elseif err_imp == true and _sim.get_equipment then
                    -- Import landed in the lua sim state. Echo the resolved
                    -- equipment back to python so the sim WINDOW (which is
                    -- rendered from python's sim_state, not the lua state)
                    -- actually shows the imported set. Without this the
                    -- import succeeds silently lua-side and the window keeps
                    -- displaying live gear -- the "it sent but doesn't show"
                    -- symptom.
                    --   SIM_INV|IMPORTED|<slot>:<id>;<slot>:<id>;...
                    -- id 0 = explicit empty slot; augmented items are id-only.
                    local eq = _sim.get_equipment()
                    if type(eq) == 'table' then
                        local parts = {}
                        for slot, val in pairs(eq) do
                            local id = 0
                            if type(val) == 'number' then
                                id = val
                            elseif type(val) == 'table' then
                                id = tonumber(val.id) or 0
                            end
                            parts[#parts+1] = string.format('%s:%d',
                                tostring(slot), id)
                        end
                        local body = 'SIM_INV|IMPORTED|' ..
                            table.concat(parts, ';')
                        pcall(function() udp_inv:send(body) end)
                    end
                end
            end
        elseif head == 'SIM' then
            -- rest is "<key>" or "<key>|<value>" or "<key>|<value>|<sub>"
            local p1, p2, p3 = nil, nil, nil
            local s1 = rest:find('|', 1, true)
            if s1 then
                p1 = rest:sub(1, s1 - 1)
                local tail = rest:sub(s1 + 1)
                local s2 = tail:find('|', 1, true)
                if s2 then
                    p2 = tail:sub(1, s2 - 1)
                    p3 = tail:sub(s2 + 1)
                else
                    p2 = tail
                end
            else
                p1 = rest
            end
            if p1 == 'refresh' then
                -- Sim REFRESH button: re-sync from live gear + force a
                -- full stats recompute. Resend the inventory snapshot (the
                -- EQUIPPED seed only repopulates empty slots, so in-progress
                -- picks are preserved) and invalidate the stats signature
                -- caches so the next stats tick recomputes and resends —
                -- same caches the sim-off path trips.
                if _ow_force_inv_resend then _ow_force_inv_resend() end
                _ow_stats_last_full      = nil
                _ow_stats_last_job       = nil
                _ow_stats_last_hastesig  = nil
                _ow_stats_last_buffsig   = nil
                _ow_stats_last_blusetsig = nil
            elseif _sim and p1 then
                _sim.set_value(p1, p2, p3)
            end
        elseif head == 'SCANZONE' then
            -- Overlay packet-scan request: SCANZONE|scan|<index>
            local s1  = rest:find('|', 1, true)
            local sub = s1 and rest:sub(1, s1 - 1) or rest
            local arg = s1 and rest:sub(s1 + 1) or ''
            if sub == 'scan' then
                _ow_scanzone_scan(arg)
            elseif sub == 'wide' then
                _ow_scanzone_widescan()
            elseif sub == 'track' then
                _ow_scanzone_track(arg)
            elseif sub == 'radar' then
                _ow_scanzone_radar_set(arg == 'on')
            elseif sub == 'lamps' then
                if arg == 'refresh' then
                    _ow_scanzone_lamps_refresh()
                else
                    _ow_scanzone_lamps_set(arg == 'on')
                end
            end
        elseif head == 'SYNERGY' then
            -- DEV Synergy panel commands: SYNERGY|feed|<elem> /
            -- SYNERGY|func|<name> / SYNERGY|refewell / SYNERGY|end /
            -- SYNERGY|refresh
            local s1  = rest:find('|', 1, true)
            local sub = s1 and rest:sub(1, s1 - 1) or rest
            local arg = s1 and rest:sub(s1 + 1) or ''
            if sub == 'feed' then
                _ow_synergy_cmd_feed(arg)
            elseif sub == 'func' then
                _ow_synergy_cmd_func(arg)
            elseif sub == 'refewell' then
                _ow_synergy_cmd_refewell()
            elseif sub == 'end' then
                _ow_synergy_cmd_func('end')
            elseif sub == 'refresh' then
                _ow_synergy_cmd_refresh()
            end
        elseif head == 'CRAFT' then
            -- DEV Craft panel commands: make / repeat / put / stop /
            -- pause / resume / delay / food / support / jiggle / hq /
            -- display / status. Payload after the sub is feature-specific.
            local s1  = rest:find('|', 1, true)
            local sub = s1 and rest:sub(1, s1 - 1) or rest
            local arg = s1 and rest:sub(s1 + 1) or ''
            _ow_craft_command(sub, arg)
        elseif head == 'SKILLUP' then
            -- DEV SkillUp panel: start|<skill> / stop / after|<mode> /
            -- toggle|<trust|geo|item> / inst|<wind|string>|<name> / status
            _ow_su_command(rest)
        elseif head == 'AH' then
            -- DEV Auction House: search|<q>|<cat> / buy|<throttle>|<items>
            -- / stop / status
            _ow_ah_command(rest)
        elseif head == 'SETTING' then
            -- Forwarded from Python's settings menu via the
            -- apply_setting_side_effects path (any setting flagged
            -- applies="lua" or "both" lands here). Wire form:
            --   SETTING|<key>|<value>
            -- value arrives as "true" / "false" for bool settings or
            -- a stringified value for others.
            local sep2 = rest:find('|', 1, true)
            local skey = sep2 and rest:sub(1, sep2 - 1) or rest
            local sval = sep2 and rest:sub(sep2 + 1) or ''
            if skey:sub(1, 3) == 'sc_' and OW_Skillchains
                    and OW_Skillchains.set_setting then
                -- Strip the sc_ prefix — the Skillchains module's
                -- internal keys are 'track_sc', 'show_props', etc.
                -- (no namespace prefix; that's only on the python side
                -- to avoid colliding with other settings). Boolean
                -- conversion: anything that isn't literally 'true' is
                -- treated as false.
                local internal_key = skey:sub(4)
                local lv = (sval or ''):lower()
                local bool_val = (lv == 'true' or lv == '1')
                pcall(OW_Skillchains.set_setting, internal_key, bool_val)
            end
            if skey == 'autora_enabled' then
                local on = ((sval or ''):lower() == 'true')
                           or (sval == '1')
                if on then _ow_autora_start() else _ow_autora_stop() end
            end
            if skey == 'autora_stop_tp' then
                local n = tonumber(sval)
                if n then
                    if n < 1000 then n = 1000
                    elseif n > 3000 then n = 3000 end
                    _ow_autora_stop_tp = n
                end
            end
            if skey == 'autora_ignore_tp' then
                local ig = ((sval or ''):lower() == 'true')
                           or (sval == '1')
                _ow_autora_halt_tp = not ig
            end
            if skey == 'ase_enabled' then
                _ow_ase_enabled = ((sval or ''):lower() == 'true')
                                  or (sval == '1')
            end
            if skey == 'ase_dead' then
                _ow_ase_dead = ((sval or ''):lower() == 'true')
                               or (sval == '1')
            end
            if skey == 'ase_appearing' then
                _ow_ase_appearing = ((sval or ''):lower() == 'true')
                                    or (sval == '1')
            end
            if skey == 'ase_fading' then
                _ow_ase_fading = ((sval or ''):lower() == 'true')
                                 or (sval == '1')
            end
            if skey == 'fisher_catch_limit' then
                if _ow_fisher_set_opt then
                    _ow_fisher_set_opt('catch_limit', tonumber(sval) or 0)
                end
            end
            if skey == 'fisher_bait' then
                if _ow_fisher_set_bait then _ow_fisher_set_bait(sval or '') end
            end
            if skey == 'fisher_catch' then
                if _ow_fisher_set_catch then _ow_fisher_set_catch(sval or '') end
            end
            if skey == 'fisher_debug' then
                if _ow_fisher_set_opt then
                    _ow_fisher_set_opt('debug_messages',
                        ((sval or ''):lower() == 'true') or (sval == '1'))
                end
            end
            if skey:match('^fisher_opt_') and _ow_fisher_set_opt then
                _ow_fisher_set_opt(skey:sub(12), tonumber(sval) or 0)
            end
            if skey == 'fisher_enabled' then
                -- Drives the embedded Fisher engine (this addon).
                local on = ((sval or ''):lower() == 'true')
                           or (sval == '1')
                if on then
                    if _ow_fisher_start then _ow_fisher_start() end
                else
                    if _ow_fisher_stop then _ow_fisher_stop() end
                end
            end
            -- Other SETTING keys: no handler yet. Left for future
            -- schema-pushed settings.
        elseif head == 'CFGWIZ' then
            -- Config wizard messages from the pygame overlay. rest is
            -- one of:
            --   "save|<dotted_path>=<int>,<dotted_path>=<int>,..."
            --   "cancel"     (overlay closed without saving)
            --   "skip"       (mark complete, leave values unchanged)
            local sep2 = rest:find('|', 1, true)
            local action = sep2 and rest:sub(1, sep2 - 1) or rest
            local payload = sep2 and rest:sub(sep2 + 1) or ''
            if action == 'save' then
                -- Parse dotted-path=int pairs into ow_user_config.
                -- Reset the bards/corsairs sections first so removed
                -- ally entries actually disappear (overlay sends only
                -- what currently exists in its state). The player
                -- section gets reset too so a stale unity_rank can't
                -- linger after the user clears it via Skip; if the
                -- overlay didn't send player.unity_rank we backfill
                -- it to 1 below.
                ow_user_config.bards = {self = {}}
                ow_user_config.corsairs = {self = {}}
                ow_user_config.geomancers = {self = {}}
                ow_user_config.player = {}
                for pair in payload:gmatch('[^,]+') do
                    local eq = pair:find('=', 1, true)
                    if eq then
                        local path = pair:sub(1, eq - 1)
                        local v    = tonumber(pair:sub(eq + 1)) or 0
                        -- Walk dotted path (a.b.c) creating tables as needed.
                        local cur = ow_user_config
                        local last_key = nil
                        for seg in path:gmatch('[^.]+') do
                            if last_key then
                                cur[last_key] = cur[last_key] or {}
                                cur = cur[last_key]
                            end
                            last_key = seg
                        end
                        if last_key then cur[last_key] = v end
                    end
                end
                -- Ensure all PW_BARD_FAMILY_KEYS exist on self (overlay
                -- might emit a sparse set if a family had value 0; this
                -- guarantees the validator doesn't have to repair).
                for _, fk in ipairs(PW_BARD_FAMILY_KEYS) do
                    if ow_user_config.bards.self[fk] == nil then
                        ow_user_config.bards.self[fk] = 0
                    end
                end
                if ow_user_config.corsairs.self.phantom_roll == nil then
                    ow_user_config.corsairs.self.phantom_roll = 0
                end
                -- Same for the geomancer self entry.
                for _, fk in ipairs(PW_GEO_FAMILY_KEYS) do
                    if ow_user_config.geomancers.self[fk] == nil then
                        ow_user_config.geomancers.self[fk] = 0
                    end
                end
                -- Backfill unity_rank to 1 (highest) if the overlay
                -- didn't include it. Clamp 1..11 in case a malformed
                -- packet ever sneaks through (the overlay validates
                -- on its side, but defense-in-depth).
                local ur = tonumber(ow_user_config.player.unity_rank) or 1
                if ur < 1 then ur = 1 end
                if ur > 11 then ur = 11 end
                ow_user_config.player.unity_rank = ur
                ow_user_config.setup_complete = true
                local ok, err = ow_save_user_config()
                if ok then
                    ow_chat(207,
                        '[OW Setup] Configuration saved. Run //ow config '
                        .. 'to verify, or //ow setup to redo.')
                else
                    ow_chat(123,
                        '[OW Setup] Save failed: ' .. tostring(err))
                end
                -- Refresh settings.Bards immediately so the values flow
                -- without waiting for the next periodic refresh.
                if _ow_refresh_bard_settings then
                    pcall(_ow_refresh_bard_settings)
                end
                -- Same for settings.Cors so GearInfo's roll math picks up
                -- the wizard's Phantom Roll+ value on the very next roll.
                if _ow_refresh_cor_settings then
                    pcall(_ow_refresh_cor_settings)
                end
                -- And push the new Unity rank into settings.player.rank
                -- so GearInfo's Calculator scales Unity-augmented gear
                -- correctly on the next compute (rather than waiting
                -- for the recompute loop to call refresh on its own).
                if _ow_refresh_unity_rank then
                    pcall(_ow_refresh_unity_rank)
                end
                -- Push geo wizard values into settings.Geo[me] so the
                -- compute path picks them up on the next recompute.
                if _ow_refresh_geo_settings then
                    pcall(_ow_refresh_geo_settings)
                end
            elseif action == 'skip' then
                ow_user_config.setup_complete = true
                local ok, err = ow_save_user_config()
                if ok then
                    ow_chat(207,
                        '[OW Setup] Marked complete (no changes). '
                        .. 'Run //ow setup any time to (re)configure.')
                else
                    ow_chat(123,
                        '[OW Setup] Save failed: ' .. tostring(err))
                end
            elseif action == 'cancel' then
                ow_chat(207,
                    '[OW Setup] Cancelled. No changes saved.')
            elseif action == 'request_open' then
                -- Pygame UI clicked the "Gear settings" button or
                -- equivalent. Build the current state and send it
                -- back so the modal renders with up-to-date values.
                _ow_cfgwiz_open()
            end
        elseif head == 'INVACT' then
            -- Inventory action from the overlay's item right-click menu.
            -- Wire forms:
            --   INVACT|drop|<char>|<item_id>      → one-shot drop now
            --   INVACT|autodrop|<char>|<item_id>  → add to Treasury list
            -- <char> is the character whose inventory the overlay was
            -- showing (its multibox lock target). Because only one game
            -- client owns this socket, we act ONLY if THIS client is
            -- that character — otherwise a drop could fire on the wrong
            -- box. An empty <char> (single-box / no lock yet) always acts.
            local a1 = rest:find('|', 1, true)
            if a1 then
                local action = rest:sub(1, a1 - 1)
                local tail   = rest:sub(a1 + 1)
                local a2     = tail:find('|', 1, true)
                local who    = a2 and tail:sub(1, a2 - 1) or ''
                local id_str = a2 and tail:sub(a2 + 1) or ''
                local item_id = tonumber(id_str)
                local me      = windower.ffxi.get_player
                                and windower.ffxi.get_player()
                local myname  = me and me.name or ''
                if who ~= '' and myname ~= '' and who ~= myname then
                    -- Meant for a different character on this machine.
                    -- Silently ignore so the wrong box never drops.
                    if _ow_cast_debug then
                        ow_chat(207,
                            '[OW] INVACT ignored (for ' .. who
                            .. ', I am ' .. myname .. ')')
                    end
                elseif item_id then
                    if action == 'drop' then
                        local ok, err = pcall(_ow_inv_drop_item_by_id, item_id)
                        if not ok then
                            ow_chat(123,
                                '[OmniWatch] drop error: ' .. tostring(err))
                        end
                    elseif action == 'autodrop' then
                        local ok, err = pcall(_ow_inv_autodrop_by_id, item_id)
                        if not ok then
                            ow_chat(123,
                                '[OmniWatch] autodrop error: ' .. tostring(err))
                        end
                    end
                end
            end
        elseif head == 'BLUSETS' then
            -- BLU Spellsets panel actions. Wire forms:
            --   BLUSETS|equip|<char>|<set name>|<Spell;Spell;...>
            --   BLUSETS|stop|<char>
            -- <char> guard mirrors INVACT: only act if THIS client is
            -- that character (empty <char> always acts) — a spellset
            -- change must never fire on the wrong box.
            local b1 = rest:find('|', 1, true)
            if b1 then
                local action = rest:sub(1, b1 - 1)
                local tail   = rest:sub(b1 + 1)
                local b2     = tail:find('|', 1, true)
                local who    = b2 and tail:sub(1, b2 - 1) or tail
                local rest2  = b2 and tail:sub(b2 + 1) or ''
                local me     = windower.ffxi.get_player
                               and windower.ffxi.get_player()
                local myname = me and me.name or ''
                if who ~= '' and myname ~= '' and who ~= myname then
                    if _ow_cast_debug then
                        ow_chat(207,
                            '[OW] BLUSETS ignored (for ' .. who
                            .. ', I am ' .. myname .. ')')
                    end
                elseif action == 'equip' then
                    local b3 = rest2:find('|', 1, true)
                    local setname = b3 and rest2:sub(1, b3 - 1) or '?'
                    local names   = b3 and rest2:sub(b3 + 1) or ''
                    local ok, err = pcall(_ow_blusets_start, setname, names)
                    if not ok then
                        ow_chat(123,
                            '[OmniWatch] blusets error: ' .. tostring(err))
                    end
                elseif action == 'stop' then
                    if _ow_blusets_active then
                        _ow_blusets_active = nil
                        ow_chat(207,
                            '[OmniWatch] BLU spellset change stopped.')
                    end
                end
            end
        elseif head == 'WARP' then
            -- One-click travel from the overlay's Warp button.
            -- Wire form: WARP|<char>|<raw superwarp command>
            -- e.g. WARP|Wormfood|sw hp Southern San d'Oria
            -- <char> is the character whose proximity the overlay was
            -- showing (multibox lock target). Like INVACT, we only act
            -- if THIS client is that character, so a warp can't fire on
            -- the wrong box. Empty <char> (single-box) always acts. The
            -- command body may itself contain spaces (zone names), so we
            -- split off only the first field as <char>.
            local w1 = rest:find('|', 1, true)
            if w1 then
                local who = rest:sub(1, w1 - 1)
                local cmd = rest:sub(w1 + 1)
                local me  = windower.ffxi.get_player
                            and windower.ffxi.get_player()
                local myname = me and me.name or ''
                if who ~= '' and myname ~= '' and who ~= myname then
                    if _ow_cast_debug then
                        ow_chat(207,
                            '[OW] WARP ignored (for ' .. who
                            .. ', I am ' .. myname .. ')')
                    end
                elseif cmd and cmd ~= '' then
                    if _ow_cast_debug then
                        ow_chat(207, '[OW] WARP run: ' .. cmd)
                    end
                    windower.send_command(cmd)
                end
            end
        elseif head == 'CALLTRUST' then
            -- Summon a saved trust set from the overlay's Call Trust button.
            -- Wire form: CALLTRUST|<char>|<set name>|<Name;Name;...>
            -- <char> guard mirrors BLUSETS/WARP: act only on the named box
            -- (empty <char> always acts) so a call can't fire on the wrong
            -- multibox character.
            local c1 = rest:find('|', 1, true)
            if c1 then
                local who   = rest:sub(1, c1 - 1)
                local tail  = rest:sub(c1 + 1)
                local c2    = tail:find('|', 1, true)
                local setnm = c2 and tail:sub(1, c2 - 1) or '?'
                local names = c2 and tail:sub(c2 + 1) or ''
                local me     = windower.ffxi.get_player
                               and windower.ffxi.get_player()
                local myname = me and me.name or ''
                if who ~= '' and myname ~= '' and who ~= myname then
                    if _ow_cast_debug then
                        ow_chat(207,
                            '[OW] CALLTRUST ignored (for ' .. who
                            .. ', I am ' .. myname .. ')')
                    end
                else
                    local ok, err = pcall(_ow_calltrust_start, setnm, names)
                    if not ok then
                        ow_chat(123,
                            '[OmniWatch] calltrust error: ' .. tostring(err))
                    end
                end
            end
        elseif head == 'PUPATT' then
            local ok, perr = pcall(_ow_pupatt_command, rest)
            if not ok then
                ow_chat(123, '[OmniWatch] pupatt error: ' .. tostring(perr))
            end
        elseif head == 'BRDSET' then
            local ok, berr = pcall(_ow_brdset_command, rest)
            if not ok then
                ow_chat(123, '[OmniWatch] brdset error: ' .. tostring(berr))
            end
        elseif head == 'CMD' then
            -- Hotbar buttons of kind="windower" send their command
            -- through here. Python strips the leading '/' before
            -- sending; we re-add it and dispatch via send_command.
            -- Header is 'CMD', rest is the slash-command body.
            -- Example: button command "input /checkparam <me>"
            -- arrives as data="CMD|input /checkparam <me>" and we
            -- run windower.send_command('input /checkparam <me>').
            if rest and rest ~= '' then
                if _ow_cast_debug then
                    ow_chat(207,
                        '[OW] CMD recv: ' .. tostring(rest))
                end
                windower.send_command(rest)
            end
        else
            -- Unrecognised header. Fall through to legacy bare-command
            -- mode: if the entire packet looks like a slash command
            -- payload (no pipe, no known header), treat the whole
            -- thing as one. This covers older python builds that
            -- didn't prefix CMD|.
            if not sep then
                if _ow_cast_debug then
                    ow_chat(207,
                        '[OW] bare cmd recv: ' .. tostring(data))
                end
                windower.send_command(data)
            end
        end
    end
end

-- Commands registered via //omniwatch. Supports:
--   //omniwatch set   <path>    - report literal gearswap set path
--   //omniwatch state <string>  - report fallback state string
--   //omniwatch debug           - toggle diagnostic printing in console/chat
_ow_cast_debug = false
-- Recent-action-name cache for fixing the native client's "?"
-- placeholder. The game client renders "<Actor> uses ?" / "readies ?"
-- when it can't resolve an ability/item ID to a name (newer content
-- than the client's DAT files, custom server abilities, etc.). The
-- action PACKET still carries the numeric ID, and Windower's resource
-- tables (res.monster_abilities / res.job_abilities / res.items /
-- res.spells) can usually resolve it. So when the action handler
-- resolves a name, we stash it keyed by actor_id; when a "?" text line
-- arrives for that actor shortly after, we substitute the real name.
--   _ow_recent_action_name[actor_id] = {name=<str>, ts=<os.clock>}
_ow_recent_action_name = {}
-- _ow_th_table: detected Treasure Hunter level per mob, keyed by mob
-- id → {level=<int>, ts=<os.clock>}. Populated when a TH proc fires
-- (Added Effect Message 603 on melee/ranged/spell damage, or message
-- 608 on weaponskills). The target card reads this to show "TH - N".
-- FFXI only sends the proc message when TH first procs or increases a
-- level, so this reflects the highest level seen on that mob so far.
-- Requires the player to be on a TH-capable job (THF main, or /THF) —
-- otherwise no proc messages are ever sent and the table stays empty.
_ow_th_table = {}
-- TTL for a TH entry (seconds). Guards against a reused mob id showing
-- a stale TH from a previous mob. Refreshed on each proc.
local _OW_TH_TTL = 600
-- How long (seconds) a cached action name stays valid for "?"
-- substitution. The text line follows the action packet within a
-- frame or two, so a short window avoids substituting a stale name
-- onto an unrelated later "?" line.
local _OW_ACTION_NAME_TTL = 3.0
-- _ow_text_capture: temporary diagnostic flag for inspecting raw
-- incoming-text events (mode byte, length, first 100 chars, first
-- 40 hex bytes). Toggled via //ow textcapture. Off by default to
-- avoid console spam during normal use.
_ow_text_capture = false

-- Buff-timer parser debug. Turn on with //ow buffdebug to see the 0x063
-- packet contents printed to chat (one line per parsed slot, with computed
-- expiry seconds). Separate from _ow_cast_debug so you can troubleshoot
-- buff timers without the gear-walk / gifts-applied noise.
_ow_buff_debug = false
_ow_gear_trace = false

_ow_gs_debug   = false

-- Last STATE/SET strings echoed to chat under //ow debug. Used to
-- suppress duplicates so the heartbeat doesn't spam.
_ow_last_echoed_state = ''
_ow_last_echoed_set   = ''

-- Bolter's Roll value tracking. Cat=6 phantom roll packets carry the
-- roll id in act.param and the roll value (1..12) in action.param.
-- We snoop for our own rolls of id 118 (Bolter's) and store the value
-- so ow_compute_speed() can use the precise per-roll value rather
-- than a hardcoded estimate. Cleared on zone change / buff drop.
_ow_bolters_value = 0    -- 0 = no Bolter's active; 1..11 = roll value

-- Base character stats (race + job + level only). Updated from packet
-- 0x061 snoops. Empty until first 0x061 arrives — until then, formulas
-- that need base stats fall back to using delta-only (we'll be off by
-- the base value, ~80-90 per stat at 99). On zone change a fresh 0x061
-- is sent so this auto-refreshes.
_ow_base_stats = {}

-- Generic Phantom Roll state: { roll_id (cat-6 ability id) → roll_value }.
-- Populated by the all-rolls snoop. Cleared on zone change. Currently we
-- only USE _ow_bolters_value for the speed calc; this table is groundwork
-- for future per-roll stat effects (Hunter's→racc, Chaos→att, etc).
_ow_roll_state = {}
-- Parallel table: roll_id → true if this roll was cast under Crooked Cards.
-- Compute path multiplies the final roll value by 1.2 for these.
-- Cleared when the roll's buff drops (handled by _ow_prune_buff_sources).
_ow_roll_crooked = {}

-- Set of all Phantom Roll job-ability IDs (cat=6 act.param). Built once
-- by walking res.job_abilities for entries whose name starts with
-- "Phantom Roll" or whose category implies a roll. Static list to avoid
-- repeated lookups; sourced from BG-wiki / Cor_Rolls.lua keys.
local PW_PHANTOM_ROLL_IDS = {
    [98]=true,  [99]=true,  [100]=true, [101]=true,  -- early rolls
    [102]=true, [103]=true, [104]=true, [105]=true,
    [106]=true, [107]=true, [108]=true, [109]=true,
    [110]=true, [111]=true, [112]=true, [113]=true,
    [114]=true, [115]=true, [116]=true, [117]=true,
    [118]=true,                                       -- Bolter's
    [119]=true, [120]=true, [121]=true, [122]=true,
    [123]=true, [124]=true,
}

-- ── Buff source tracking ──────────────────────────────────────────────────
-- Maps buff_id → list of source records describing what applied that buff.
-- Each source: { src_kind = 'song'|'spell'|'roll'|'food',
--                src_id   = numeric id (spell/ability/item),
--                src_name = display name,
--                potency  = numeric (haste% * 100, attack delta, etc.) }
--
-- When a buff_id disappears from player.buffs we clear the corresponding
-- entries. Multiple sources can share a buff_id (e.g. multiple Marches
-- all share buff 33 [Haste]) — we keep them all so consumers can sum.
_ow_buff_sources = {}

-- Persistence path. Written whenever _ow_buff_sources changes; read once
-- at addon load so a omniwatch.py restart doesn't lose live buff data.
local _PW_BUFF_STATE_PATH = 'data/_ow_buff_state.lua'

local function _ow_save_buff_state()
    local path = (windower.addon_path or '') .. _PW_BUFF_STATE_PATH
    local f, err = io.open(path, 'w')
    if not f then return end
    f:write('-- Auto-generated by OmniWatch. Do not edit by hand.\n')
    f:write('return {\n')
    for buff_id, srcs in pairs(_ow_buff_sources) do
        f:write(string.format('  [%d] = {\n', buff_id))
        for _, s in ipairs(srcs) do
            f:write(string.format(
                '    { src_kind = %q, src_id = %d, src_name = %q, potency = %s, cast_time = %s },\n',
                s.src_kind or '', s.src_id or 0, s.src_name or '',
                tostring(s.potency or 0), tostring(s.cast_time or 0)))
        end
        f:write('  },\n')
    end
    f:write('}\n')
    f:close()
end

local function _ow_load_buff_state()
    local ok, data = pcall(require, _PW_BUFF_STATE_PATH:gsub('%.lua$', ''))
    if ok and type(data) == 'table' then
        _ow_buff_sources = data
    end
end

-- Remove source entries whose buff_id is no longer active on the player.
-- Called periodically so songs/spells that wore off don't keep contributing
-- to haste/speed/etc. Persists state if anything was removed.
local function _ow_prune_buff_sources()
    local player = windower.ffxi.get_player()
    if not (player and player.buffs) then return end
    local active = {}
    local active_count = {}
    for _, bid in ipairs(player.buffs) do
        active[bid] = true
        active_count[bid] = (active_count[bid] or 0) + 1
    end
    local changed = false
    local now = os.time()
    -- Grace period: when a song is cast, cat=4 fires before the buff
    -- packet (0x063) lands, so player.buffs won't contain the buff_id
    -- yet. If we prune in that window, we lose the just-written source
    -- and the song silently disappears from the haste sum. Skip the
    -- bucket entirely if any source in it was written in the last 5s.
    for bid, srcs in pairs(_ow_buff_sources) do
        if not active[bid] then
            local fresh = false
            if type(srcs) == 'table' then
                for _, s in ipairs(srcs) do
                    if s.cast_time and (now - s.cast_time) < 5 then
                        fresh = true
                        break
                    end
                end
            end
            if not fresh then
                -- Diagnostic: log what we're about to nuke
                if type(srcs) == 'table' and #srcs > 0 then
                    local names = {}
                    for _, s in ipairs(srcs) do
                        names[#names+1] = (s.src_kind or '?') .. ':' .. tostring(s.src_name or '?')
                    end
                    ow_chat(207, string.format(
                        '[OW] prune: bid=%d not in player.buffs, dropping %d records: %s',
                        bid, #srcs, table.concat(names, ',')))
                end
                _ow_buff_sources[bid] = nil
                changed = true
            end
        else
            -- Buff_id IS active, but individual song records within the
            -- bucket can still be stale. Songs share buff_id 214 (March
            -- bucket) — when Honor wears off but Victory is still up,
            -- buff 214 stays in player.buffs but Honor's source record
            -- is now stale and would otherwise keep contributing haste.
            -- Drop any source older than 30 min — well past any realistic
            -- song lifetime even with full duration gear (Carnwenhan 1.5×
            -- + instrument 1.4× + Troubadour 2× pushes max-duration songs
            -- to ~12-18 min). The previous 480s cap was dropping march
            -- source records while the buff was still alive in-game,
            -- causing the stat panel to revert to a no-buffs state ~8 min
            -- after a long song was cast.
            if type(srcs) == 'table' then
                local kept = {}
                for _, s in ipairs(srcs) do
                    local age = (s.cast_time and (now - s.cast_time)) or 0
                    if s.src_kind == 'song' and age > 1800 then
                        changed = true  -- record dropped
                    else
                        kept[#kept+1] = s
                    end
                end
                -- Drop stale EXCESS records. When a song is overwritten by
                -- another of the same buff_id — e.g. a dummy song replaced
                -- by the real song in the same slot during an extrasongsmode
                -- rotation — the buff_id stays in player.buffs, so the dummy
                -- record is never pruned above and its acc/att keeps being
                -- summed on TOP of the real song's (the +1-song over-count
                -- that only appears when dummy songs are mixed in). Cap the
                -- bucket to the number of instances of this buff_id actually
                -- live in player.buffs, dropping the OLDEST (the dummy was
                -- cast before the real song that replaced it).
                -- Collapse duplicate records of the SAME song name, keeping
                -- the highest-potency one. The dummy->real rotation and the
                -- cat=8/cat=4 double-write can leave two records for one song
                -- (e.g. a stale nil/0% "Victory March" beside the real one);
                -- both would otherwise sum. One self-song name = one buff.
                do
                    local best, order = {}, {}
                    for _, srec in ipairs(kept) do
                        local key = srec.src_name or tostring(srec.src_id or '?')
                        local cur = best[key]
                        if not cur then
                            best[key] = srec
                            order[#order + 1] = key
                        else
                            changed = true
                            if (tonumber(srec.potency) or 0)
                               > (tonumber(cur.potency) or 0) then
                                best[key] = srec
                            end
                        end
                    end
                    if #order < #kept then
                        local dedup = {}
                        for _, k in ipairs(order) do
                            dedup[#dedup + 1] = best[k]
                        end
                        kept = dedup
                    end
                end
                -- Reconcile song records against the songs ACTUALLY live.
                -- Marches all share buff_id 214, and player.buffs lists 214
                -- only ONCE no matter how many marches are up, so the old
                -- active_count[214] cap was 1 and collapsed stacked marches
                -- to a single record — dropping Honor when Victory landed
                -- (the "+3% instead of stacking" haste bug). Instead, gather
                -- the song names currently present in buff_details (the 0x063
                -- slot reconcile stamps full_name there) and keep every song
                -- record whose name is live; drop song records for songs no
                -- longer active — e.g. a dummy overwritten by the real song
                -- in an extrasongsmode rotation. Non-song records and records
                -- cast in the last 5s (bd may not be stamped yet) are kept.
                -- Skip entirely if no live song names are visible (bd not yet
                -- populated) so we never false-drop a real march.
                do
                    local live_names, saw_any = {}, false
                    if _ExtraData and _ExtraData.player
                       and _ExtraData.player.buff_details then
                        for _, b in pairs(_ExtraData.player.buff_details) do
                            if type(b) == 'table' and b.full_name then
                                live_names[b.full_name] = true
                                saw_any = true
                            end
                        end
                    end
                    if saw_any then
                        local keep2 = {}
                        for _, s in ipairs(kept) do
                            local fresh = s.cast_time
                                and (now - s.cast_time) < 5
                            if s.src_kind ~= 'song' or fresh
                               or (s.src_name and live_names[s.src_name]) then
                                keep2[#keep2 + 1] = s
                            else
                                changed = true  -- stale song record dropped
                            end
                        end
                        kept = keep2
                    end
                end
                if #kept ~= #srcs then
                    if #kept == 0 then
                        _ow_buff_sources[bid] = nil
                    else
                        _ow_buff_sources[bid] = kept
                    end
                end
            end
        end
    end
    if changed then
        _ow_save_buff_state()
    end
    -- Food buff drop check: 251 is the standard Food buff id. When it
    -- drops, clear cached food stats so we stop contributing them.
    if _ow_food_item_id ~= 0 and not active[251] then
        _ow_food_stats = {}
        _ow_food_item_id = 0
    end
    -- Phantom Roll drop: each roll produces a buff with the roll's name
    -- (e.g. "Hunter's Roll" buff_id). When the buff is no longer in
    -- player.buffs, drop the cached roll value.
    if Cor_Rolls then
        for roll_id in pairs(_ow_roll_state) do
            local roll_def = Cor_Rolls[roll_id]
            local buff_id = roll_def and (tonumber(roll_def['status'])
                                          or tonumber(roll_def['buff_id']))
            if buff_id and not active[buff_id] then
                _ow_roll_state[roll_id] = nil
                _ow_roll_crooked[roll_id] = nil
            end
        end
    end
end

ow_safe_register('load', function()
    _ow_load_buff_state()
    -- Prime base stats from windower's last-cached 0x061. Without
    -- this, _ow_base_stats stays empty until a fresh server-side
    -- 0x061 fires (gear swap, level up, buff change) — which means
    -- accuracy/attack/etc. compute against incomplete inputs and
    -- read low. windower.packets.last_incoming gives us the most
    -- recent packet from the session's history. Pattern lifted
    -- from GearInfo's initialize_packet_parsing.
    pcall(function()
        if windower.packets and windower.packets.last_incoming then
            local cached = windower.packets.last_incoming(0x061)
            if cached then
                local ok, p = pcall(packets.parse, 'incoming', cached)
                if ok and p then
                    _ow_base_stats = {
                        str    = tonumber(p['Base STR']) or 0,
                        dex    = tonumber(p['Base DEX']) or 0,
                        vit    = tonumber(p['Base VIT']) or 0,
                        agi    = tonumber(p['Base AGI']) or 0,
                        ['int']= tonumber(p['Base INT']) or 0,
                        mnd    = tonumber(p['Base MND']) or 0,
                        chr    = tonumber(p['Base CHR']) or 0,
                    }
                    if _ow_cast_debug then
                        ow_chat(207, string.format(
                            '[OW] base stats primed from cached 0x061: '
                            ..'STR=%d DEX=%d VIT=%d AGI=%d INT=%d MND=%d CHR=%d',
                            _ow_base_stats.str, _ow_base_stats.dex,
                            _ow_base_stats.vit, _ow_base_stats.agi,
                            _ow_base_stats['int'], _ow_base_stats.mnd,
                            _ow_base_stats.chr))
                    end
                end
            end
        end
    end)
    -- Write the user_config.lua starter template if the file is missing.
    -- This way new installs get a clear template to hand-edit, instead
    -- of a silent empty config. Existing files are NOT touched.
    pcall(ow_write_user_config_template_if_missing)
    ow_chat(207, string.format(
        '[OmniWatch] loaded v%s. Type //ow help for commands.',
        _addon.version))
    -- First-run setup nag. setup_complete is set to true by the wizard
    -- on completion (or by 'skip'). Until then, point the user at the
    -- wizard. Idempotent — doesn't pester after they've completed
    -- once. Hand-editors who never run //ow setup can flip the flag
    -- in user_config.lua to silence this.
    if not (ow_user_config and ow_user_config.setup_complete) then
        ow_chat(207,
            '[OmniWatch] First run: type //ow setup to configure your '
            .. 'Song+ / Phantom Roll+ / Geomancy+ / Unity Rank values. '
            .. 'Or //ow setup skip to dismiss.')
    end
end)

